/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260226-20","meetingId":"r08-1t","date":"2026年2月26日","dateIso":"2026-02-26","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前１０時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"それと、少しおさらいになってしまうのですけれども、実証期間が、今年、まだこれから続くわけですが、その実証期間後の各事業の流れはどのようになっていくのか、再確認させてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"しながわシティラボに関しましては、しながわシティラボの事業の実施基準を定めてございまして、まずは、このしながわシティラボとして区が採用をするかの基準と併せて、その後の継続の可否の判断についても基準の明記をしております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し具体的に資料に即して伺いたいのですが、２ページ目の課題解決型の１ですが、この説明では分からなかったので、室外機へのインプット電力量を制御させという辺り、これはどういうことなのか分からなかったので教えていただきたい。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"最後に、４番目のコンタクトセンター、どのような業務かというご質問ですが、こちらは現在、戸籍住民課で受け付けている典型的な質問などをＦＡＱのような形でＡＩに読み込ませて、比較的定型的で簡易的な質問については、ＡＩで応答ができることを目指しておりまして、まずは。","id":"exchange-002"},{"speaker":"安藤委員","kind":"提案","question":"それと、実証実験提案型、３ページ、６ですが、ジョブトランジットなど、検索すると、普通に株式会社で行うシングルマザー向けの就労支援事業として出てくるのですけれども、これはしながわシティラボの参加がきっかけで生まれたものなのか、それとももともとあったものがしながわシティラボに登録したのか伺いたいのと、それと、しながわシティラボに関わることによるメリット。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区にとってのメリットですが、しながわシティラボの事業に係る経費の負担については、基本的には全て提案事業者の負担としていますので、まずは、区としましては、予算化して本格実施をする前に、こういう課題を発信することによって提案を受けて。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"それだけに品川区の信用力、自治体の信用力、認知力などがアップすることが企業のメリットとありましたけれども、その信用力は本当に大事だと思うのですが、様々な提案を受ける中で、こちらの判断、本当に社会的にどうなのかとか、それを品川区で実証実験することによって、区のブランドイメージがどうなっていくのかというリスクも一方ではあると思うので、そこら辺は慎重にやっていると思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"今日の出されている資料の中の目的で、１点確認を最初にします。目的の中に、自律的取組みを促進するという表現があるのですが、この自律的取組みの解釈を教えていただきたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"品川区では、行政だけではなくて、地域の企業や団体、それからひいては区民の方も含めてＳＤＧｓの達成に向けて、各自が行動変容を起こしていただいて、日々の日常生活の中での行動も含めてＳＤＧｓの達成に寄与していただきたいと考えていますので、こちらは企業や団体。","id":"exchange-005"},{"speaker":"新妻委員","kind":"提案","question":"今後やはり継続をしていくことがすごく大事だと思うのです。区の支援があるときだけやっているということではなくて、今後ずっと継続していくことが必要と思うのですけれども、その点、今後の、長期展望に立った、それぞれの団体・企業等のあり方、そこのお考えはどうかお聞きしたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"例えば区からの実証が終わった後に、区の施設を引き続き使えない場合でも、次に、では、どういうところで継続ができるのかとか、あとは実証の結果、こういう部分が弱点だと少し見えてきたところで。","id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"その継続するというところでの支援をしっかりと強化していただきたいと思います。最後に１点、先ほど課長からご紹介がありましたしながわシティラボのホームページに、都市計画課からの提案で、品川区の夏を冷やす、暑熱対策ソリューションの共創が課題として挙がっております。この関連性をお聞きしたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区では、この暑熱対策に関しまして、区が考え得る範囲のもの以外で、民間から広く新しいアイデア等がないか、それはハードだけではなくてソフト面も含めて、品川区という地域、エリアが、涼しくて外を歩きたくなるようなまちにしていくために。","id":"exchange-007"},{"speaker":"新妻委員","kind":"提案","question":"そうすると既に、数か所からの提案が区に入ってきて、このホームページを確認されたところから、区に、こういうことができるというような提案を受けている段階ということでよろしいでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"委員からご指摘ございましたように、こちらの今の提案状況ですが、事業者からも提案を実際に数件いただいておりまして、その内容をヒアリングするなど、実証にまだつながっている段階ではございませんが、やはり事業者の方に伺いますと、こちらは品川区に限った課題ではなくて。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"提案","question":"それが論理的な帰結になると思うのですけれども、そういうことも、変な話、提案する事業者の実証実験においてのメリットでは認知と信用力の２つある、企業にはそうだとお話がありましたが、それも１つのメリットになってくると思ったのですが、基本的には効果が出れば、品川区としては、その事業を本採用していくような流れになるのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、そこに、例えば区の予算が、予算化をする必要がある場合には、通常の予算編成の流れで総合的に判断をさせていただいて、議会の審議をいただくことですし、あとは、実証実験を連携させていただきました提案事業者がいらっしゃいますが。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"最後に１つだけ伺いたいのは、今回こうやって選定をされて、様々なユニークな事業、私からはユニークに見えるのですけれども、そのような事業を提案されて実証実験に臨む、他の所管課との調整も非常に大変だと思いますし、実証実験の場をどこが引き受けるのかとか、そのような調整は、今まで多分、そのようなことはあまりやっていなかった、当然やっていない自治体もある中で。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"特に中小企業における脱炭素の推進は、区としてもなかなか、中小企業の皆様はどうしても、やはり人材不足だったり、そのほかのリソース不足で、ＳＤＧｓでしたり、この脱炭素まで手が回らないというのが率直な感想として聞いていますので、そこを。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"この概要も拝見させていただいて、今おっしゃられたところ、これはもう、こちらの中小企業向けのＡＩ電気相談所設立についてという話で、エアコンの話とこちらの話とあるのですけれども、これはもう、ある意味、令和７年１１月から令和８年２月で、我々にも視察の案内が来ていて、それは拝見していないのですが、先ほどご説明があって、聞き漏らしていたら申し訳ないのですが、私が多分、この区内の中小企業。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こちらですが、２月までの実証で、まだ最終的な成果の報告はいただいていないものではありますが、中小企業センターやＳＨＩＰに、このアプリを設置することによって各中小企業の皆様にお試しいただくような内容でございまして、こちらについては。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"こちらでご説明のとおり、２回の交流会、それから専門部会を４回開催されているということなのですけれども、参加者の皆さんからのアンケートは取っているのでしょうか。取っておりましたら、回答率や満足度、それから改善等の要望などを教えてください。それから、まとめてお聞きします。会員数は２１企業・団体ですけれども、この数について、どう受け止めていらっしゃいますか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"次年度に向けましては、今回、１年目、２年目については、顔の見える関係性を構築するような交流会を実施してまいりましたが、来年度に向けた、より深い、テーマを絞った議論などができるような会も検討してまいりたいと考えていまして。","id":"exchange-012"},{"speaker":"山本委員","kind":"提案","question":"参加団体の数の受け止め、分かりました。続けて、しながわシティラボについてお伺いいたします。その上で幾つかお伺いしますけれども、こちらの課題解決型、それから実証実験提案型、それぞれ、現在進んでいる状況を教えていただいたのですが、応募している企業は、それぞれどれぐらいあったのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"実際に実証実験につながったのは、その下の１０件になりますが、やはり実施基準にのっとりまして、提案書をいただいたのは３０件ですけれども、一定数、自社の製品やサービスなどの営業に近いような、どの社会課題を解決するものか不明瞭なものなどが一定数ありますので。","id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"年度前半で募集をして、選定をして、動いておりますけれども、ここまで、このしながわシティラボの実施状況を見ますと、しながわシティラボ自体は、資金の支援ではないですが、このような区の実証フィールドを使ってやっている中で、実証フィールドの提供だけにとどまらず、中には資金提供をしたほうがいいものが出てくると思っておりまして、そのような２次要望だとか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今年度から開始しました参加企業・団体からの１分ピッチも、その中から数社の方に登壇いただいた状況ですので、引き続きＳＤＧｓ宣言制度とも連携をして、企業・団体、各ステークホルダーとの連携により、社会課題の解決を目指してまいりたいと考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"要望をします。ＳＤＧｓ施策とのつながりについては、このＳＤＧｓ宣言企業にご参加いただいていることは確認をいたしましたが、今回、交流会や実証実験事業に参加していただいている企業にＳＤＧｓ宣言企業になってもらう方法、これは有効だと思いました。実効性のある、このような取組が進むことを期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"株式会社ＷｉｓｅＶｉｎｅという方がやられるのですけれども、ホームページを見ましたところ、愛媛県の事業者で、一方、財政課を経験された、元財政課職員が社員として入られているということで、プロダクトも真のビルド・アンド・スクラップを完成させるとか、かなり専門性の高い会社と思いますが、この会社を選ばれた理由として、もう１つ、そういう実績とかあると思うのですが。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"この株式会社ＷｉｓｅＶｉｎｅのほかからも、実際に、お問合せベースも含めまして数社から関心を持っていただいて、ご提案をいただいているような状況ですので、非常にこの分野と申しますか、生成ＡＩの分野の方には興味を抱いていただいているものと考えています。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それで、いよいよ、しながわシティラボのホームページを見ますと、もう３月から始めて３回ほどやっている旨の記載があると思うのですけれども、実証期間の終わりが令和８年９月で、私としましてもどのような成果があったのか非常に関心が高いので、成果発表会、ほかの、企業とかやられると思うのですが。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"一般公開をするような成果発表会は今のところ予定はしていないのですが、今後どのような形で公表、区民の方も含めて、対外的にお伝えしていくかを検討してまいりたいと考えております。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどのお話ですと、予算化するにはＫＰＩとかを見て、採用された暁には予算化されるというお話だったと思うのですけれども、今回この生成ＡＩを活用した予算編成・行政評価実施は、予算案、プレス発表で新規の事業として発表されていると思うのですが、既に予算額がついているのですけれども、これはどのような理由でしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"もちろん予算化して、事業負担がある部分につきましては、先ほどの答弁と重なってまいりますが、地方自治法ですとか品川区の契約規則にのっとりまして、この事業者に限らずに、そこは広く進めてまいりたいと考えているところです。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"この３番、４番、生成ＡＩ関係のものは、そもそも、この事業、ピンポイントではなくて、生成ＡＩを使った実証を、ざっくりと予算化しようと事前に考えていたから、今回、予算計上されているという理解でよろしいのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"委員、ご指摘のとおり、区として、この部分の実証を行うための予算をつけて実施を行うということがまずございまして、そのための前段階として広く民間提案を募って、概念実証をするためにしながわシティラボを活用したです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問","question":"株式会社ＷｉｓｅＶｉｎｅと株式会社ＳＨＩＦＴは、予算案が可決されてからになりますけれども、きちんと報酬、会社として自らの持ち出しはないと、しっかりとその対価を受け取って実証実験を行うということでよろしいのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"事業者の負担についてですが、このしながわシティラボの枠組みでの実証実験につきましては、提案事業者の負担でお願いをしておりますので、２月から９月の実証に関しましては、株式会社ＷｉｓｅＶｉｎｅと株式会社ＳＨＩＦＴに負担いただく形にます。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"この予算案のお金は何に使うのですか。２,３６３万円。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"そちらは、この実証実験、いわゆる概念実証が終わった後に、区として本格的に実証をするための経費でございまして、そちらについて改めて事業者選定から進めてまいりたいと考えています。","id":"exchange-021"},{"speaker":"こしば委員","kind":"提案","question":"しながわシティラボの目標が社会課題の解決を目指すということで、まさに、それはもう当たり前ですけれども、その中で、今回の実証事業をするに当たって、各部署から課題を抽出したと認識しておるのですが、今回、実証事業に当たっての課題解決型を４点取って、実証実験提案型は６点ございましたけれども、それ以外にも、様々、各部署で課題が出ていたのは事実なのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、一方で、この課題を出すのも、なかなか区の職員としてもこれまでそのようなノウハウがない部分でございましたので、昨年度、それから今年度につきましては、職員向けの研修、ワークショップなども併せて実施しまして。","id":"exchange-022"},{"speaker":"こしば委員","kind":"質問","question":"食育という意味でもそうだと思うのですけれども、いまひとつ都市型農業、品川区は、特にこれは消費者で、生産者ではないわけであって、その中で農業を発展させていく、どのような腹づもり、考えがあってのことで、この課題が出てきたのか、私には理解ができなかったので、その辺りを分かる範囲で教えていただけますか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"例えば水道の水だけではなくて雨水を使うですとか、あとは、電力につきましても太陽光パネル、この施設の写真の裏側、下に実は置いてあるのですけれども、太陽光発電を活用しているものでございまして、あとは土につきましても、廃ガラスを丸めてボール状にしたものを。","id":"exchange-023"},{"speaker":"こしば委員","kind":"質問・要望","question":"本当にもう脱帽した限りでして、このようなものは、八潮にはありますけれども、またさらに、それこそ子どもたちも、来ているかもしれませんが、全域から来ていただいて、そこで環境に向けた取組を学び、大きな発見をもらえるよう、区からまたさらに周知を展開していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"確認","question":"これからのスケジュールのこともあるから、例えば、午後にして少し目を通す時間を取るとか。次の委員会となると、またすごいことになってしまうから、今日やらないと、いろいろなスケジュールもある。だから今日、副委員長に確認もしたのですけれども、やるという。だから少しだけ時間を入れて、あと理事者のご都合もあると思うので、午後もいいのだったら、そのようにしたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回廃止した事業は２６のようですけれども、最後に資料がありますが、Ｄ評価です。それで、実際廃止した事業は幾つあったのか、そして主なもの、どんなものを廃止したのかご紹介いただきたいのが１つです。","respondent":"吉岡政策推進担当課長","answer":"一方で、事業の完了ですとか廃止に向けた検討が、それ以外になります。一方で、小事業ごとにＤ評価と見ておりますので、例えばＣ評価の取組の一部廃止、事業の中にある取組を廃止したところにつきましては１３事業です。","id":"exchange-026"},{"speaker":"安藤委員","kind":"確認","question":"何かいろいろ削減されていると思いまして、ここでどうこう言えないのですけれども、ただ、中には、いいのかというようなこともあると思うのです。説明を聞き逃したのですが、提出資料の2)が一部ということですけれども、今、削減されたのは全て一覧となって額と一緒に出てくるのか、確認させてください。具体的には、これは大丈夫なのか、どういうことをやるのか、もう少し伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"ＡＩ活用による行政評価ですけれども、今考えておりますのが、事務事業評価シート、令和６年度版という形になりまして、予算、決算、あるいは財務情報に関しては２年分持っているのですが、これをもう少し、いろいろな資料を読み込ませることによって、複数年のシートの結果。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、政策評価について伺いたいのですけれども、提言の骨子および区の対応という、一部抜粋がありますが、提言の骨子の２番で提言されている内容について、施設の利用条件や予約方法を改善してほしいという提言があると書いていますけれども、これはどのような提言だったのかもう少し伺いたいのと、それと、今年はスポーツというテーマでしたが、来年の評価対象分野はどういうものにするお考えなのか。","respondent":"吉岡政策推進担当課長","answer":"最後に、介護の居住手当の削減ですけれども、これは当然、このような利用者の方、対象者の方がいらっしゃる中で多く活用いただければ活用していただきたい、そのような手法があればやっていきたいのですが、今回そういう適正な予算規模を考えていく中で。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"政策評価については廃止と聞こえたのですけれども、そうなのですか。もし仮に、取りあえず適正規模の予算を定めるために、行政評価でそうなったのであれば、年度途中で、やはり制度の認知度や使い方の向上などがあって、より多くの方に、いい政策なわけですから、利用されることになって予算が足りなくなったとなれば機動的な、柔軟的な補正予算を組むなど、必要な予算をつけていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"Ｄについては、先ほどのご説明で、ある程度一定、廃止等行っているし、先ほどの事例もありましたけれども、分かるのですが、Ａが、新しい取組とか対象規模等の拡大について半分になっているということについて、事務事業評価をした結果としてこういう結果になっているのですが、区としては、この辺りは、理由、傾向、事実は事実としてあると思うのですが、これはどういう政策の方向性の転換なのか。","respondent":"吉岡政策推進担当課長","answer":"一方、これは事業単位で見ておりますので、その中の小事業の中で、新規あるいは拡充のメニューがあるのですが、一方で、その小事業面に、課題として少し見過ごせない課題があるようなものにつきましては、やはりＡ評価、Ｃ評価どちらかになった場合に。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど課長からもありましたけれども、経年で見ていくと、どうしてもそのようになってしまうというところと、それでも、こういうチャレンジングなことをやっているという説明をしないと、少し守りの予算になったイメージが出てしまう、そのように感じることもあると思って伺ってみました。","respondent":"吉岡政策推進担当課長","answer":"いずれにいたしましても、事業評価、これはしっかりとそれぞれの事業を見定めた上で今後の方向性をやっていくので、引き続き力を入れながら進めてまいります。","id":"exchange-031"},{"speaker":"まつざわ委員","kind":"質問","question":"教えてほしいのですけれども、令和７年度の予算削除額、これは結局、去年から比べて５億円削れなかったということですか。","respondent":"吉岡政策推進担当課長","answer":"削減できなかったのかという質問に対する回答ではないかもしれないのですけれども、数字としては、昨年度は２０億円を超える削減額がありましたので、それよりも５億円少ない金額です。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"意見","question":"そうすると、削れなかった、要はスクラップし切れなかった、２０億円が正しいわけではないと思いますけれども、私がすごく心配しているのは、新しい事業ばかり増えても、やはりしっかりしたスクラップは、やる必要性が私はずっとあると思っていますので、だからそこら辺で５億円という部分が削り切れなかったというのは少し失礼ですが、もっと果敢に挑戦する。","respondent":"吉岡政策推進担当課長","answer":"そのようなものも含めて、中長期的に判断できるものをしっかりと手をつけながら、当然、短期的にスクラップ、見直しできるものについても力を入れながら、財源の確保もそうですし、職員の負担のバランス、そのようなもので、削減だけではなくて。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"意見","question":"事務事業評価シートの例えば、左の指標の達成状況の中で、文書の電子決裁率が９０％を超えている、でも財務の電子決裁率は約４０％にとどまっているという報告があるのです。これは何か、素人ながら、なぜこういう財務の決裁の電子化が進まないのか。そうすると、決裁のそのようなもの自体を見直さなければいけないのかと思うのですけれども、そこら辺は。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"山本委員","kind":"質問","question":"一方で、事務事業評価としてやると、Ｄ評価として、完了、中止、廃止する事業としては２６事業が挙げられている。つまり、短期的にすぐに見直すべきものと、中長期的に見直していくべきものの色分けも、やはり必要だと思うのですけれども、評価の中でのさらなる色分けに対して、どう考えるかご意見いただければと思います。","respondent":"吉岡政策推進担当課長","answer":"こちらがまず３事業にとどまるのですけども、このようなところをＤ評価、検討ということで、そういう俎上を上げることによって、このような見直しについての加速化を図るということも行っておりますので、そのような部分で、では、どういったときにこの評価を付すかは。","id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"この行政評価をやって３年目を迎えるということですけれども、やはり資料を見ただけで多くのことが分かるような、もしくは、その評価を通じて今後対応すべきことが分かるようにアップデートしていくことがすごく大事だと思います。これは意見、要望です。区のこの対応は、提言を受けて誰がどのように考えて、このように対応しようとなったのか確認をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"こんの副委員長","kind":"質問","question":"個別の掘り下げの話ではなくて、ここに書いてある個別の政策についてではなく、事務事業評価シートそのものの表現の仕方だとか、運用の仕方だとか、そのような質問でお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"山本委員","kind":"質問","question":"しています。そうしています。私は、このシートで、時系列で表現するべきですとか、行政評価全体で外部機関の評価をするべきとか、その仕組みについてご質問やご提言をさせていただいていると見ます。中身のところについては、政策評価は、これは中身の話だと思っているのですけれども、これは、その中身については、今回触れないということなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"山本委員","kind":"質問・要望","question":"そのような機会で、また追加のところはお話ししますけれども、今の答弁を受けての回答といたしましては、そのような検討経緯は理解いたしましたので、ただ、意見として申し上げますと、その提言に対して子ども以外の部分も、多分要望としては含まれていると思いますので、区の対応が主なものとして、抜粋として書かれていると思いますが、それ以外の部分としてもしっかりと、この政策評価委員会の方々。","respondent":"吉岡政策推進担当課長","answer":"それ以外のものについても、中長期的な検討で考えた部分もありますけども、このスポーツだけではなくて、過去の政策評価でいただいた部分も、そのような形で反映させていくように今後とも努めてまいります。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"要求水準書はどのような意味を持つ文書なのかを教えてもらいたいです。３つ目は、様々こういった機能が具体的になってきたのですが、ＰＦＩですので、収益を上げられなければ企業は参入しないと思うのですけれども、区としては、現在の事業が並んでいますが、この事業で参入する企業というのは、どこで収益を上げると考えているのか伺います。","respondent":"吉岡政策推進担当課長","answer":"３つご質問をいただきましたので、お答えさせていただければと思います。今回の実施方針・要求水準書案の現時点での案でお示しいたしました。実施方針に関しましては、何をＰＦＩ事業として各民間事業者に求めるのか。","id":"exchange-040"},{"speaker":"安藤委員","kind":"提案","question":"それと、すみません、４つ目に行ってしまいますけれども、ホール・スタジオを多目的ルームに変更とあるのですが、ホール・スタジオという機能が多目的ルームで包含されるのか、スタジオというのは結構専門的な施設だと思うのですけれども、多目的ルームになってしまう、そういう機能はなくなってしまうとなったら、これも大きな変更だと思うのですが、そちらについても伺います。","respondent":"吉岡政策推進担当課長","answer":"そういった中で、５００ｍ以内にこういった類似の施設、同様の施設があるというのをしっかりと検討したところです。これに関しましては、地域の説明会でも、同じような施設がここに存在するのはどうなのかというご指摘もいただいて、しっかりと検討を重ねたところです。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"就労支援施設、もともと就労支援というと、どうしても就労継続支援Ｂ型とか、そういうのを想像してしまうものですから、それがこのように短時間雇用に変わったとなると、例えば面積とかはどうなってしまうのかとか、あと就労継続支援Ｂ型自体が２３区で遅れていますし、私たちも一般質問で質問しましたけれども、利用者のうち１５３人もの方が区外に通わざるを得ない実態が現在ある中で、就労支援となると。","respondent":"吉岡政策推進担当課長","answer":"ただ、このグラウンド・体育館はメインで使ってきた方というよりは、サブ的に使ってきた方が多くなりますので、使えない時期はあるとは思うのですけれども、それ以外の関係施設の空き状況なども提供させていただきながら、引き続き対応していきたいと考えております。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"就労支援は、そういうことですね。でも、こういったまとまった土地が跡地活用で、今喫緊の課題である施設が入ってこないのは、少し不思議な感じがするのです。改善が必要だと思いますが、今回この施設については、そういう議論で分かりました。それで、冒頭に杉並区の施設の感想を述べさせていただきましたけれども、品川区のコンセプトの根底には区民の要望があるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"何か買物に行ったときに駐輪場でかっぱが脱げるか、細かいことですけれども、そういうことがあるので、お子さんを連れて動くとなったときに、雨の日でも使える施設であって、自転車の需要があるとなれば、駐輪場への屋根の設置は私は必須と思っているのですけれども、その辺りがどうなっているのか、もし屋根がないのであれば、そこはしっかりとつけていただきたいということを要望します。","respondent":"吉岡政策推進担当課長","answer":"障害者就労は、旗の台リボンの限定のところと、あと委託の部分ですけれども、旗の台リボンのところとは情報を連携しながら広く進めていくというのもありますが、今、前のリボンのところもまだ稼働して間もないので。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"提案","question":"それで、結構変更点があって、そもそも超複合施設で、詰め込み過ぎかどうかはあれですけれども、かなりいろいろな、単純計算すると１０種類ぐらいの事業を行う大変さというものは想像するだけでも、委員会等で質問してきたのですが、それがかなり丸まった、そういう印象を受けたのですが、いい悪いは別にして、幾つか具体的に伺っていくのですけれども、先ほどのスタジオの話で、５室。","respondent":"吉岡政策推進担当課長","answer":"続きまして、ビオトープにつきましても、今委員からもございましたとおり、生き物の管理、そういったものは難しいという複数事業者の声もあったのを踏まえまして、事業者それぞれいろいろな提案、考えを持っていらっしゃいます。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"提案","question":"階段の形とか、あとは座るベンチですとか、阿波踊りという１つ地域のキーワードがあったりして、そういったものをテーマにしたようなデザインもあったりして、今回、躯体のデザイン、これは木のところと思うのですけれども、そこについてのイメージは、今回建設も一緒にやるということであるならば、そういった提案、これは質問等でも何回か上げていますけれども、らせん階段であったり。","respondent":"吉岡政策推進担当課長","answer":"当然、民間事業者からいい提案があって、この前提が覆るようなものでなければ、いいアイデアはどんどん提案していただきたいという考えは変わりませんので、さらによくなることは期待できるです。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"最初のスタジオについては、スタジオとして使えなければ、みんながギターを持ってきて、ギターを鳴らすのだったらいいのですけれども、そもそも高価でなかなか手に入らないようなものを、そこで使えるということも非常に重要だと思いますし、最後に申し上げたいのは、いろいろ見てきて、ヤングアダルトと言われるような世代の方たちが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"山本委員","kind":"質問・要望","question":"令和１４年から区が指定管理料を１５年間払うことを前提で考えていくことで、事業者からの金額提示は、個々の施設の指定管理料の積み上げに基づく全体の指定管理料を提示できる形で、複数の事業者から金額的なものを提示してもらう、ランニングコストの部分を提示してもらうのでしょうかイニシャルコストの建設費とかは当然、事業者が負担されるということで、多分。","respondent":"吉岡政策推進担当課長","answer":"なので、設計、建設、１５年間の総事業、こういったものをひっくるめて入札公告で金額を出させていただいて、その金額によって応募していただくことを検討しています。これがＰＦＩ事業の一般的なことで対応するものです。","id":"exchange-048"},{"speaker":"山本委員","kind":"質問・要望","question":"全体の契約は、そのような仕組みということで理解をいたしました。金額はどのようになっていくのかは、今の物価高の影響とかも踏まえてどうなっていくのかと、区としての負担がその後どうなっていくのかに関心がございましたので、ご質問させていただいた次第です。それ以外の使い方、運営の工夫は、ぜひ当事者の皆さんの声を聴きながら、今後竣工までに仕組みを考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"こしば委員","kind":"質問","question":"私からも、先ほど来質疑がありました多目的室の扱いについてお聞きしたいと思います。当初の計画では、ホールとスタジオの２つがそれぞれあって、それが大きな多目的ルームに統一されるのでしょうけれども、こちらはあくまでも５つの多目的室全てが、例えば同じ面積で、また当初のとおり、ホール性能が、そして鏡が備えられている施設という認識でよろしいでしょうか。","respondent":"吉岡政策推進担当課長","answer":"大きい部屋が１８０m2、真ん中の大きさが９０m2、これが１室ずつです。小さい部屋として２０m2ずつで、非常に少人数でも使いやすい部屋を計５室ということで整備を考えおります。防音整備、そしてガラス、あと、鏡を備えた施設です。","id":"exchange-050"},{"speaker":"こしば委員","kind":"意見","question":"これを運営していくのがＰＦＩと言っておりますので、従来型の品川区の施設ですと、予約システム管理があって、そこから入って予約をしていくと思うのですけれども、ＰＦＩはそれがまた別物になると思うので、その辺りはうまく、分けられているのかもしれないですけれども、使い勝手のいいものとしてもらいたいと思います。","respondent":"吉岡政策推進担当課長","answer":"区立施設として同じ枠組みである部屋の予約のシステムにつきましては、区のそのものを使いつつ、一方で、新しく備える機能だとか、そういったところで別途システムが必要であれば、そういった提案も事業者からいただくと考えております。","id":"exchange-051"},{"speaker":"こしば委員","kind":"質問","question":"追加で聞きたいのですけれども、スタジオですと、いろいろと持ち運びなどがあって、場合によってはトラックに積み込んで搬入しなければならないような大きなものがあるかもしれない。そういったこともある程度踏まえた上での計画なのか、教えてもらいたいです。","respondent":"吉岡政策推進担当課長","answer":"そういったところでは、トラックの出入りも想定されますので、運用でそれがどれだけ必要かというのはあるのですけれども、そういった使い方をいたしますので、大きな運ぶ車も一定出入りはできると捉えております。","id":"exchange-052"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"いろいろたくさんの思いが詰まったものを、こうやってまとめてくるのは相当な努力だと思っていて、本当にすばらしい施設を期待しております。その中で１点、図書館。安藤委員からもお話がありました、ゆたか図書館がなくなって、１個に集約していくというか、安藤委員の言い分は分かりますが、私などはずっと言っていたのが、点で施設は考えないで、面で考えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-02","title":"なぎさ会館跡の暫定活用","agenda":"なぎさ会館跡の暫定活用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"集中備蓄倉庫というのは何なのか、普通の災害対策備蓄倉庫との違いを伺います。なぎさ会館の建物ですけれども、耐震化の状況ですとか、継続利用が可能なのかとか、そういった既存躯体の現況について伺いたいというのが２点目です。３点目は、暫定活用の時期ですけれども、いつ頃までなのか。それと、跡地活用の検討状況はどうなっているのか、いつからどのように検討していくのか伺います。","respondent":"吉岡政策推進担当課長","answer":"実際にこちらのなぎさ会館の隣地ですけれども、立会川の幹線雨水放流管、東京都の下水道整備事業で、途中一部貸しているようなところもございまして、区有地としての一体的な活用が今できないような状況ですので、そういった動向を見据えながら、本格活用に向けて検討していく。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちらをぜひやってほしいのですが、そもそもこの地域に限らず、そういった話は、臨海斎場はアクセスが不便だと話が出ているので、例えば水族館行きのバスが出ていますけれども、そのルートを延長して、別のバスにしてもいいと思うのですが、大井町から区民公園まで行って、なぎさ会館の跡地付近を経由して臨海斎場につなぐルートとか、廃止に当たってはそういった声が出ていましたので。","respondent":"吉岡政策推進担当課長","answer":"令和６年度の利用率が２６％、令和７年度も９月末ですと１７.６％で、愛されている施設、使われてきた施設ではありますが、令和元年度以降、ずっと利用率が落ちている実情もございました。","id":"exchange-055"},{"speaker":"安藤委員","kind":"意見","question":"当時承知しているということでしたので、ぜひ他部署とも連携して、アクセスというのはここだけの話ではないのですけれども、ずっと課題になっていますので、利用等も含めて改善を改めてお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"利用のここのプロセス、ここの備品を災害対策用に使うと決まっていったプロセスを、もう少し詳しく教えていただきたいと思っています。それが１点。それと、現在なぎさ会館は、葬祭場ではありますけれども、授乳室ということで、一般の方々も使えるようになっている用途があると思うのですが、今後そこの部分は残していただけるのか、確認をさせていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"無人での管理になりますので、そこで有人にするのかとか、鍵の管理をどうするのかという課題もありますので、そういった部分は、授乳室の話も含めて、検討していく必要があると考えています。","id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"引き続き、遺体安置所の位置づけは残るということです。利用としては、備蓄倉庫は悪くないとは思いますし、また、地元地域の連合町会にもしっかり話をされているということでありましたが、地元からも少し使いたいというお声もあったと伺っておりますので、その辺りはまたご検討いただきたいと思いますが、１点は無人になるということです。","respondent":"吉岡政策推進担当課長","answer":"当然、意見が多く集まれば、その中の調整になりますし、我々でも検討して、所管に持っていくこともございまして、それから全体調整の中での決定事項です。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"災害対策備蓄倉庫として暫定活用されるということで承知しました。それで、先ほどのご質問とかご答弁にあったのですけれども、雨水放流管事業について、この近くでやられていますが、その影響で大規模な改修ができない事情もあると思うのですけれども、その雨水放流管事業は今どのような影響があるのか、具体的に教えてください。","respondent":"吉岡政策推進担当課長","answer":"こういったことが解消されないと、なぎさ会館も含めて、区の敷地が一体化で活用できない状況です。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問","question":"備蓄倉庫として使われているということで、ここを地図で見ると明らかなように、運河に面しているのですけれども、災害時、運河を使って何か備蓄品を運搬するという使い方も想定されているのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"車づけがいいので、区内にあります各避難所へ物資を届ける、河川までという話はまだ聞こえていないのですけれども、多様な運搬方法、各輸送体制については、引き続き所管とともに検討していきたいと思います。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問・要望","question":"なかなか地の利がいい場所にあることと、あと、新妻委員からもお話ありましたけれども、運河を利用されている団体からは、せっかく運河に面しているので、そうした水辺活動とかにも活用できないかというお話は私も伺っているので、当面の間は備蓄倉庫として暫定活用されると思うのですけれども、ぜひ跡地活用につきましては、運河、水辺に面していることも踏まえた検討を行っていただきたいと存じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-03","title":"ふるさと納税寄附金の受入状況および寄附額の見直し","agenda":"ふるさと納税寄附金の受入状況および寄附額の見直し","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これまでも品川区は、この制度自体に意見を言ってきたと思うのですけれども、国にどんな意見をどのように言っているのかお伺いしたいのと、これからもきちんともっと述べていく必要があるという思いで言っているのですが、あと、制度改正についての説明がありましたけれども、この制度改正は、これまでのそういった働きかけでの一定の成果と捉えているのか伺いたいと思います。","respondent":"宮澤税務課長","answer":"今回の税制改正に伴うところで見ますと、まさに募集経費の上限５割の縮小部分、定額での上限の設定ということで、今回１９３万円が上限になりましたけれども、そういった形で、流出額に一定の抑制効果があるところは出ております。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/838925?Template=document&Id=7335#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":69324,"voices":179}},{"id":"r08-20260227-22","meetingId":"r08-1t","date":"2026年2月27日","dateIso":"2026-02-27","committee":"まちづくり・公共交通推進特別委員会","time":"午前１０時００分～午後 ０時０７分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"確認","question":"特に３月２８日にＯＩＭＡＣＨＩ ＴＲＡＣＫＳが完成してオープンする。ここに来て、より具体的に、このような動きがある中で、跡地の活用方法の修正といいますか、整合性を取るといいますか、これまでの方針と変わるようなことが、考え方が、そこに生じるのかどうかということを確認したいと思います。","respondent":"泉広町事業調整担当課長","answer":"具体の、導入機能に関わる部分になってまいりますので、来年度から策定に着手する予定としています活用プランを策定する中で、ＯＩＭＡＣＨＩ ＴＲＡＣＫＳとの関連性等々をしっかりお示しをしながら、議論を進めていければと考えているところです。","id":"exchange-001"},{"speaker":"田中委員","kind":"確認","question":"ちょっとそこを確認したかったということ。世界の都市ランキングで、これまで東京は３位だったものが今度２位になりました。最終的には当然トップを目指すというような視点もあると思います。今までの検討委員の方の意見に縛られてしまうのかどうかというところを確認したいと思います。","respondent":"泉広町事業調整担当課長","answer":"これまでの検討と今後の検討の進め方です。大井町、確かにおっしゃられるとおり、交通結節機能の非常に高い地域ということで、区内外から様々な人が訪れています。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"創出する財源２００億円について、私の聞き間違いであればあれなのですけれども、先ほど、今回の財源、事業費として総額２００億円というようなご説明のように伺ったのです。その確認と、今までの、先ほど言った学識経験者、法学部出身の学識経験者の下で行われた検討会について。そもそもの２００億円の金額の出どころや、その試算の根拠、２００億円の根拠というものはどのようなところなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"こちらの経過につきましては、まず、この２００億円は、現区長が実際に選挙で公約として掲げられたものであるというところが１つと、また、そういったところも踏まえながら、区として検討を進める中で、収支のほうを計算したところ。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"今日配られたものではなくて、事前に配られている資料によると、創出する財源についてはおおむね２００億円と書いてあるのですが、ここでいう創出するというところは、今までのまちづくりの中での表記とは少し違う、要は総額としては別の金額があるけれども、そこから、この間の石田秀男副委員長のご質問にもあったように、例えば定期借地など、そのようなことも前提にして２００億円ということなのですか。","respondent":"泉広町事業調整担当課長","answer":"定期借地を一定想定しながら今後の検討を進めてまいりますが、直接的な地代が今ここでお示ししている金額かというところにつきましては、今後検討を深める中でしっかり精査をしてまいりたいというところの表現です。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"私はこの大きな土地、将来最大限有効活用すべき跡地だと考えていますので、発展的な視点でプランをつくっていただきたい。２００億円という数字は私も区長の公約で、もちろん見てはおります。しかし、場合によっては２００億円の根拠を区長に伺うということも、この委員会なのか、予算特別委員会なのか、一般質問等々になるのか、わかりませんけれども、ぜひ伺いたいなという感想を述べて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"一般質問もしたのですが、お聞きをしたいことを伺っていきます。私は、ここでそれをしっかり考えてほしい。定期借地でこれだけ上げていったほうがいいですよね、こちらは、分からない、どのような提案が来るか分からないけれども、そのような提案と比較して、どちらがいいですかということはやっても、私は７０年の先のことまで縛るわけだから、それをしっかりやっていくということはありだと思うのです。","respondent":"泉広町事業調整担当課長","answer":"そういった状況を踏まえますと、なかなか今回の事業にしながわ中央公園、駅周辺を入れてまいりますと、事業の実現性や、また、その事業の提案が少なくなって、競争性が低下する、そういったところもあるのではないかというような懸念から、今回の範囲につきましては。","id":"exchange-006"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"だけれども、そのようなことで２００億円について考えると、どうしても今言った意見をこれから伺っていくといっても、それがあったら、これはもう何度も話をしているからあれですが、そのような計画しか出てこないのです。その中でいくとなると。そのようなことを含めて、私はそういう提案を１回やってもらってはどうかと。何千億円の話をする中の提案をしてもらうために５,０００万円払ってもいいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"藤原委員","kind":"確認","question":"ちょっと改めて確認をします。今委員長、副委員長と理事者の方の質問、答弁を伺ってまいりました。結局というか、私は議員ですから地域に行くと聞かれるのです。土地は売らないで済むけれどもという話が出たということは、もう定期付借地権でマンションという話は決まっているのですか。でも、もう一般の方たちにはどのような説明をすればいいのですかということをはっきり教えていただけますか。","respondent":"泉広町事業調整担当課長","answer":"今マンションなどの具体的な機能に関するご質問もございましたけれども、この具体な機能につきましては現時点では何も決まってございませんで、来年度から策定をする予定にしています活用プランを策定する中で、皆様とともに議論を進めてまいりたいですので、今現状としては。","id":"exchange-008"},{"speaker":"藤原委員","kind":"提案","question":"だから、区民の皆さんにお示しをする、これこれこのような形でやっていくと、このような経済的な効果が出て、区民の皆様たちにとっての利益にもなるという形に、私はきちんと提案をしていくべきだとまず思っていますし、あと「いや、何になるのですかね。その辺のことをきちんと示してくれないと、何かおかしいというか、そのような疑問が出てしまうのですけれども、その辺についてはいかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"この間我々もサウンディング調査などを通しまして、民間事業者の方にこういった庁舎跡地の活用検討の状況の区民ニーズなどもお伝えしながら、どういった区民ニーズがかなえられるかという視点でもご意見を頂戴してきたです。","id":"exchange-009"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"多分ね。だけれども、今さっき言ったように、２００億円、逆に今いろいろ、定期借地とすることを中心にとおっしゃるのであれば、タワーマンション以外どのような方法があるのですか。そうではないですか。タワーマンションしかないではないですか。それ以外の選択肢はあるのですか。その活用はあるにしても、それ以外のところはもうタワーマンションしかないのではないですかと言っているのです。","respondent":"泉広町事業調整担当課長","answer":"直接的な地代としてそういったものを生み出していくのか、または間接的な効果も含めてやっていくのかというところを含めて、また活用プランをする中で精査を進めたいというところで、具体の機能については来年度の活用プランの中で。","id":"exchange-010"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"でも、私は本気で皆さんに考えてほしい。７０年の縛りをかけて、行政の土地を利用してタワーマンションを建てて、億ションを販売して、それで回遊性もストップさせる。なぜなら、もうテナント需要もそれほどないのだから。だけれども、我々の今やっていることは、ここはもう本当に、私は最後のピースという言葉を使ったけれども、起爆剤という言葉もどうしようかと考えたぐらい。ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"「東京における地域公共交通の基本方針」改定に向けた中間まとめ","agenda":"「東京における地域公共交通の基本方針」改定に向けた中間まとめ","exchanges":[{"speaker":"田中委員","kind":"質問","question":"これは基本的には都の施策なので、質問を考えながらお伺いをしたいのですが、最後のまとめのところの広域調整に係る取組の促進というところです。","respondent":"櫻木地域交通政策課長","answer":"今回在り方検討会、先ほどご紹介させていただきましたが、構成メンバーとして、品川区も途中から参加させていただいておりましたので、その点から何点かご意見を申し上げたことはあります。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひしなバスを運行している品川区の経験といいますか、考えをぜひ伝えていただきたいと思います。この次のテーマでも触れますが、いわゆるバス事業者に対しての規制緩和といいますか、理解を求めるということをぜひ東京都からバス事業者にしていただきたいなと。ひいては東京都から理解を求めるような対応をしていただきたいということをぜひ伝えていただきたいと思いますが、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"基礎バス路線のあるところへ、区が実施主体として調整に入るというか、運行するようなところにおきましては、もともとの趣旨として、需要を各会社が食い合わないようにするというところがあります。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"最初に概要版のほうで、人口が２０３０年、４年後ですけれども、２０３０年をピークに人口減少社会を迎えると言っています。そういったものの改定なども行われていくのかなとは思いますが、ちょっとこれが定められた後の区としての動きというものがどのように想定されるのかを伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"今ご指摘いただいたとおり、東京都のほうで広域的な交通の考え方を来年度改定するということを踏まえまして、また、一般質問等でもお答えさせていただいたこともございましたが、区としましても、一定交通サービス圏域外の解消に尽力した後につきましては。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"向こう１０年ぐらいをスパンにしてと。何か実態とそぐわないものが出てきても困ってしまうなと思ったのですが、その辺は話合いの、議論の場に品川区が入っていらっしゃるということを聞いたので、区の実情というものは伝えていただいて、定められていくものということで大丈夫なのかなというところをちょっとお聞きしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"今回の検討会につきまして、品川区はお声がけいただいて参画しているのですが、令和８年にまたこれの計画を具体的に検討していく会が立ち上がると聞いています。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"声かけいただければ、そのような流れにはなるということで、声がかからないということがどれぐらいあり得るのかどうかということはちょっと想像できないのですけれども、いずれにしても、しっかりと品川区の実情というものが反映された形にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"すみません、不勉強で教えていただきたいのですが、まず運転手の方の人材不足、これはもう何度もお話を伺っていて、例えば定年など、そのようなものを延長しても、例えばそこで辞める方が５０人いて、入ってくるものが５人しかいない。運転手には資格も必要ではないですか。デマンドのワンボックスカーだったら普通二種免許は要るのか要らないのかなどあるではないですか。","respondent":"櫻木地域交通政策課長","answer":"都バスの給料の考え方については私のほうで把握してございませんが、定年後の給料が減ることによって運転手の確保が難しくなっているという話は伺ったことがあります。","id":"exchange-017"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"それで、どうも都バスは、品川区でも大分、昼間の時間帯全く走らないとか、相手がお金出してくれるのにやらないとか、何か結構そのようなものが出てきているではないですか。そのようなものをもう少し解決するには、品川区の立場では難しいのかもしれないけれども、方法は何かないのかということをまず聞きたいです。","respondent":"櫻木地域交通政策課長","answer":"それがいいとか悪いとかいう話ではございませんが、いずれにせよ都のほうでも、ここに示されているとおり、運転手の方々の処遇改善であったり、社会的な認知度の向上であったり、少しずつ地道な成果を重ねていくことで運転士確保につなげているのかなとは思っているところです。","id":"exchange-018"},{"speaker":"えのした委員","kind":"質問","question":"今運転手不足などのお話も出ていましたけれども、東京都、これ自動運転技術に関して、レベル４の自動運転の実証実験をやっております。近隣区だとお隣の大田区が昨年の１月に、羽田イノベーションシティですか、循環バスなど、一般道でも実証運行されたという話も聞いております。２３区、他区、他の自治体でも、やはり自動運転進んでいるのか、品川区での考え、聞いているお話をお聞かせください。","respondent":"櫻木地域交通政策課長","answer":"ではそのようなところに需要がどのぐらいあるのか、全く乗らないところに通してもということもありますので、その辺りは他区の状況等見ながら研究していく段階かなと考えています。","id":"exchange-019"},{"speaker":"えのした委員","kind":"意見","question":"そうですね。品川区の中でも適地、なかなか難しいと思いますけれども、次、項番２、（２）のところでも、オンデマンド交通なども進んでいますので、これはまだまだ未来の話でありますが、検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問","question":"これは世田谷区における試算例ですが、会議に途中から出席されているということで、品川区の空白地域プラス、世田谷区の場合は１日３０本未満のバス停を考慮した分析がされていますけれども、３０本未満とか、２０本未満とか、９本未満とか、これは世田谷区の例ですが、少なからず、確かに影響があるね、課題のある地域ですねという考え方が出ましたけれども、品川区としては何か試算をしたのでしょうか。","respondent":"櫻木地域交通政策課長","answer":"は都営バスのほうも、品川、八潮間であったり、大井町、八潮間あたりは５０本のレベルに該当するのかなというところは確認しております。それ以外のところは５０本未満という形で整備されるのかなと考えています。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"空白ではないけれども課題がある。その中においては、今回のこの東京都の、何だ、東京都の今日の資料、中間まとめ、これをしっかりと精査をしながら、品川区独自のというところで、そのような流れだというように、これまでの様々な質疑、質問の中で認識をしています。その背景には東京都も手がつけられない、民間バス会社と行政の関係性、本来は、いわゆる官民連携という言い方ですかね。なければ結構です。","respondent":"櫻木地域交通政策課長","answer":"一方で、区民の目線から、サービスレベルの向上や最大化という面から見ると、なかなか、そこのバランスを取っていくということは公の役割かなと考えていますので、今後検討を進める際には、そのような視点もしっかり持って進めたいと考えています。","id":"exchange-022"}]},{"id":"topic-03","title":"令和８年度の地域交通の取り組み","agenda":"令和８年度の地域交通の取り組み","exchanges":[{"speaker":"えのした委員","kind":"提案","question":"そこで確認なのですが、ふだんからこの前は、近くに配送業者の事務所があって、結構車がそこにとまっていて、地域の方からも陳情というか、別な意味でも苦情といいますか、お話も多くある地区、地区というか、場所なのです。時間帯がもう、荏原はご要望で８時に時間早まりましたけれども、やはりこれ運行９時からになっているので、そこがせっかくなら８時からやらないのかなというところ。","respondent":"櫻木地域交通政策課長","answer":"利用者の利便性という観点から、一定配慮して、検討していく点かなと考えています。必ずしもアプリが異なるから、では駄目だという話にしますと、すばらしい提案を見逃す可能性もありますので、その辺りはやはりバランスの問題かなと考えています。","id":"exchange-023"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。１点、私乗ったときに、後ろの席かな、ぬいぐるみが、シナモロールが乗っていました。これ、聞いたら、落とし物ではなくて、病気のお子さんや障害をお持ちの方もいらっしゃるということで取組まれていて、見えないところでしたけれども、ああ、このようなものはほっとするなと思ったので、またそういったところも進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"これ何台ぐらいで回るのでしょうか。荏原は２台体制だったと思うのだけれども、２台ではないですか。今１台ですか。運行は１台か。ということでいくと、大体ミーティングポイントは５０か所ぐらいでかなり多くなっていって、範囲も広いのかな。ミニバンタイプ１台ということですね。ごめんなさい。お聞きしたかったことは、運転手の稼働率というのですか。","respondent":"櫻木地域交通政策課長","answer":"運転手の方につきましては、しなるんに従事していただく際は１日しなるんについていただくという形になっておりますので、運行自体が、もし仮に予約が入っていない時間帯は、荏原交通が営業所圏内にありますので、そこで待機していただいているような状況となります。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。そのほうが多分運用はしやすいのだろうなと思うのですけれども、そうした場合に運転手の人件費のようなものは、コミュニティバスとはあまり変わらないというように見るのか、やはりそれでも優位性のようなものはあるのかということを教えていただけますか。","respondent":"櫻木地域交通政策課長","answer":"効率性という意味ではなかなか比較が難しい側面もあろうかとは思いますが、基本的には、バスはバスなりの、やはり様々な設備、装置がありますので、その辺りをどう見るかということと、人件費につきましては、タクシー運転手とバス運転手の給与面の違いというところかと思います。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。大崎地区についてはコミュニティバスを求める声も結構あったりして、そのような中でこのＡＩオンデマンドを導入、実証実験でやっていただくということで、これはいろいろご意見あるかもしれませんけれども、しっかり根づかせていただきたいなとは思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれご説明ありがとうあります。バス、しなバスに関してお伺いしますが、長年要望したことが実現されたことを高く評価をしたいと思います。感謝を申し上げます。本当にありがとうございました。何だったのかという。要は、今まで何もやっていなかったではないかと言われることもあり得るのですが、そもそも何がここまで実現できない要因だったのか、まず端的にお伺いしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"そのようなところで、既存の路線があるところについて、当初コミュニティバスを運行させる際は、そこを避ける形で路線を設定したです。今回既存路線がなくなったということで、区として使うこと、路線を敷いたです。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"タイミングとしてはまさにそのとおりだと思っていますし、そうだろうなとは思っています。要は、区から要望したけれども、京急バスから拒否をされた、同意を得られなかったのか、忖度をしてそもそも要望しなかったのかと、そこはぜひお伺いしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"当然区からは毎年要望して、ご検討いただきたいということを申入れをしてきたような経緯があります。なかなか色よいご返事をいただけなかったという状況であります。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"そのようなことも踏まえて、地域の方には説明をしていきたいと思います。それこそ都民ファーストの都知事ですから、都民の要望に沿った路線ができるように、バス事業者に対しても理解を求めていただきたいという旨は、繰り返しになって恐縮ですけれども、引き続きお伝えをお願いしたいと思います。このこと、バスに関しては大変感謝をしております。続いてＡＩオンデマンド交通の、まず荏原地区に関して。","respondent":"櫻木地域交通政策課長","answer":"ちょっと事例というか、効率的な配車が行われているということで、具体的な事例としてはちょっと挙げられませんが、そのように理解していただければと思います。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"そのような意味でもＡＩの効果があるということを区民の方にも知らせていただくことでさらなる浸透につながるのかなと思いますので、そこもご検討いただきたいと思います。併せて、先ほどのえのした委員のお話にも関連しますけれども、荏原一丁目や二丁目、小山一丁目、二丁目、あるいは小山台など、そういった方面からの要望があったのかなかったのか。その辺はいかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"１台で回せる範囲として１.５から２km2という範囲なので、あまり広げ過ぎると、今度は利用者のサービスが低下してしまいますので、一定の範囲内で収めるということと、あとは町丁目単位で設定することになっておりますので、その辺りを勘案した結果。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"その上で１点だけ、需要として、病院へ行く方、高齢者の方が利用するケースが多いということでした。そこはそこで大きく期待をしています。それで、両者間の利用というものは可能なのでしょうか。荏原地域の導入がＡＩしなるん１.０、今回が２.０とすると、２.５ぐらいで、それも両地域をまたぐ運行というものも、私は前向きに検討していただいてもいいのかなと思うのですが、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"将来的に区全体の交通の在り方を考えていく上で、どのような使い方をしていくかということは１つの検討ポイントかとは思います。","id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"ルート設定でＡＩを使うということは分かるのですが、もう１つ、他の視点でＡＩの使い方というか、需要を考えていくと、雨が降ったとき、それこそ公共交通機関に限らず、交通の需要が増えると思います。そうしたことを本当は予測しながらできるということが、１つＡＩの強みでもあるのかなと思うのですが、今後そうした発展的な考え方に至る可能性というものはあるのでしょうか。お願いします。","respondent":"櫻木地域交通政策課長","answer":"委員がおっしゃる夜間の需要というものは、例えば習い事へのお迎えであったり、習い事へ向かう際の利用であったり、通勤通学の需要等は当然こちらのほうでも当初検討させていただきました。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問・要望","question":"きちんと需要と供給を見ながら、対応いただきたい。それを誰がその需要を満たすのか。民間が本当は全部それを把握して、そこにうまくタクシーを配置するようになってくれたら多分一番いいと思うのですけれども、そこはこれから、来年度などというところではなく、今後の公共交通の在り方をぜひ研究していただきたいなと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"若林委員","kind":"確認","question":"いわゆる法令的な縛りなのかという確認と、それを前提にすると、これは今、想定エリアは円で１点、コンパスで１.５kmでぐるっとした形。そうか。でも、八丁目は入っていますね。そういった考え方とミーティングポイントの設定の仕方というものを、現段階での考えをお聞きしたいということが１つと、あとは確認ですけれども、料金がここに載っていないのですが、どのような設定になるのか教えてください。","respondent":"櫻木地域交通政策課長","answer":"料金につきましても、一応事業者提案という形にはしていますが、参考として、荏原地区ではこのような料金体系ですということを一緒にセットでお示しするような形ですので、それを踏まえて、事業者が創意工夫を凝らした提案をしていただけると認識しております。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/379605?Template=document&Id=7337#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":39509,"voices":101}},{"id":"r08-20260303-3","meetingId":"r08-yosan","date":"2026年3月3日","dateIso":"2026-03-03","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時０８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"おぎの副委員長","kind":"質問","question":"次に第４項、款別審査の質疑等についてです。質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"おはようあります。しかし、収入面・税収がすごくいいからこそ、あえて一言言わせていただきたい、教えていただきたいのが、東京都の令和８年度の予算というのが８.８兆円。本区はいかがでしょうか。高度な運用手法を参考にしながら、ぜひ単なる預金ではなく稼ぐ基金へと、要は脱皮させるというのですか、そういうのも１つの考えかと思いますけれども、まずはそういった区の見解をお聞かせください。","respondent":"加島財政課長、品川会計管理者","answer":"ただ、金利が上昇基調にある中で、新庁舎建設に関するこちらの起債につきましては、今後、歳入増、財政状況等を見ながら、歳入増の一部を減債基金に積み立てるなどいたしまして、残金一括償還時の元金返済額を増やしていくことにより。現在、基金は、地方債、それから財投機関債、それからご質問がありましたとおり、ＥＳＧ債も含めて運用を行っております。今年度収益見込みですけれども３億３,０００万円で、前年と比べまして約１億４,０００万円増となっています。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"質問","question":"そうしたら次に、関連して人件費を伺いたいと思っています。特別区人事委員会による公民較差３.８０％の昇給等の勧告、そして物価高、民間の賃上げを考えれば、職員の処遇改善として必要だということは十分に理解しています。特に、代表質問でも答弁いただきました。例えば経験者採用のコスト増をどう適正管理していくのか、ご見解をお聞かせください。","respondent":"加島財政課長、宮尾人事課長","answer":"具体的には、当該年度における一般財源・特定財源の見込みや、基金現在高の推移など、そういった要素を勘案しながら、財政の持続可能性を確保するように努めているところです。経験者採用につきましては、民間企業などでの有用な職務経験を有する人材を幅広い年代層において確保することで、多様化する行政サービスに的確に対応することを目的に実施してございまして。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問","question":"分かりました。そうすると関連して、会計年度任用職員の話もそうなのです。これも総務省が、令和７年４月に遡って、同一労働同一賃金の観点から処遇改善を行うという話がありました。こういったものを迅速かつ正確に執行できる体制というのが現在整っているのか、また、この遡及適用による財政的な増減規模についても併せて教えてください。","respondent":"宮尾人事課長","answer":"４月に遡っての支給となる改定の部分につきましては、担当の部署におきまして、過去の採用事例なども参考にしながら支給事務を行ってあります。なお、この勧告に基づきまして、４月に遡って支給した額、会計年度任用職員の分ですが、約１億８,６００万円です。","id":"exchange-004"},{"speaker":"まつざわ委員","kind":"意見","question":"分かりました。抑えられます」、「残業代がどれだけ浮きます」、そしてまた「浮いた分を、人にしかできない業務に充てられます」といった具体的な成果というものを、区民に数字で表すべきだと思っています。ＤＸによる業務削減の目標、例えば人件費の抑制額といったものを、財政的効果を数値で可視化するべきだと思いますが、ご見解をお聞かせください。","respondent":"宮尾人事課長、西澤ＤＸ戦略担当課長","answer":"近年、職員数全体としては増員としていますが、例えば今回、日曜開庁の見直しに伴いまして地域センターでは減員とするなど、ニーズや必要とされる業務量を見ながら対応しています。しかし、人口減少社会において、ＤＸで得られた時間や資源といったものを、区民サービスの向上、課題解決、そして区民に寄り添った対応といった、人でなければできない業務に費やしていくことが重要だと考えております。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ効果が分かるＤＸの推進を、今以上に力を入れてやっていただきたいと思っています。今は本当に、すばらしく税収がいいと思っています。しかし、景気というのが本当に水物といいまして、本当に冷え込むときもあると思うのです。例えば貯金・基金、そしてＤＸ、そして賢い借金返済。ぜひこの三本柱で、次世代にツケを回さない強靱な品川区を強く求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"山本委員","kind":"質問","question":"本日からどうぞよろしくお願いいたします。私からは、補正予算の歳入と歳出の全般、３６ページの特別区民税、それから１０９ページの義務教育施設整備基金積立金、１０７ページの防災普及教育費について伺います。歳入、特別区税について伺います。歳入は、主に１０２億円増収、補正予算の部分です。特別区民税４７億円の増額、特別区財政調整交付金４３億円の増額が主と理解しています。","respondent":"宮澤税務課長","answer":"特別区民税が、当初見込みより増額補正になっている主な要因です。１つ目は納税義務者の増加、２つ目は合計所得１,０００万円以上の所得層の方の増加、それに合わせて１世帯当たりの所得が増加したというところ。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問","question":"この部分については当初予算上、見込みにくいというところもあるかと思います。次に、歳出と基金について伺います。主に学校改築に使う義務教育施設整備基金積立金、そして公共施設整備基金積立金に資金を振り分けておりますが、どのように判断し、どのような順序でどれだけの金額を積み立てたか、積立て後の残高とともにご説明をお願いいたします。","respondent":"加島財政課長","answer":"私からは、基金の積立ての考え方についてお答え申し上げます。最終補正予算における基金の積立てですけれども、明示されている優先基準というものはございませんが、今年度の補正予算につきましては、義務教育施設整備基金に６０億円を繰り入れることをまず一番に考えました。","id":"exchange-008"},{"speaker":"山本委員","kind":"提案","question":"これは、一昔前は１校当たり３０億円と言われていたものが大幅に増えております。やはり、先々の財政負担が非常に心配です。昨年の予算特別委員会でご提案した２０年の超長期財務シミュレーションについて、先日の代表質問でもご質問をして、検討中というご答弁を頂いておりますが、既に１年経過しております。現在の検討状況と、進める中での課題、それから公表の見通しについてお伺いいたします。","respondent":"吉岡政策推進担当課長、加島財政課長","answer":"品川区公共施設等総合計画で試算した今後の各学校の更新に係る経費の見込みですけれども、こちらにつきましては、その他の公共施設の部分に、現在の延べ床面積を基に、改修や改築に係る経費を見込んでいるところです。財政シミュレーション、特に長期のというところでは、先ほど申し上げた関係費の動向以外にも、人口動態や複数の経済指標、公共施設の老朽化状況と更新計画について、細かな前提条件を設けた上で分析に取り組む必要があると考えており。","id":"exchange-009"},{"speaker":"山本委員","kind":"提案","question":"重点的にできる限り早期に進めていただきたいということで、引き続き要望します。学校改築を含む公共施設改築工事費については、都や国に補助金等の負担増を一層求めていくことを要望していくべきだと思っています。要望します。そして、願わくは品川区がリードして、２３区で足並みをそろえて要望することが重要であると考えております。現在の状況および区のお考えを確認いたします。","respondent":"荒木学校施設担当課長","answer":"こちらにつきましては、品川区を含めて２３区、公共工事の単価の増額というものに関しては、非常に危機感を持って認識しています。今年も２３区を代表して、補助金の増額の要望は実施しておりますが、来年度も引き続いて、国に協議を求めていきたいと考えております。","id":"exchange-010"},{"speaker":"山本委員","kind":"確認","question":"防災普及教育費について伺います。どうぞよろしくお願いします。エレベーター用防災チェア等配布事業で約３,９００万円減額されております。令和７年度予算がほぼ残っているという理解です。予算の確認と、令和６年度の事業開始からの目標と配布数、それに対する区の認識をお教えください。","respondent":"羽鳥防災課長","answer":"エレベーター用防災チェアについてご説明します。こちらの事業は、令和６年度から令和８年度までの３か年事業ということで進めしています。令和６年度は６００台の見込みに対して実績３４０台という状況でございました。残りの２６０台が在庫となったという結果になってあります。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"状況を理解いたしました。令和６年度に始まった新規施策ですけれども、最近またエレベーターの停止といった状況もありますので、こういったものを活かして、引き続き施策を継続して効果を高めるように動いていただきたいと思います。マンション管理組合として、マンション単位で防災強化・備蓄強化を進めることを要望いたします。その辺りについてのご見解をお伺いいたします。","respondent":"羽鳥防災課長","answer":"例えば、区が取り組んでいるマンション防災アドバイザー派遣や、しながわ防災学校のマンションコースのご案内、また都が実施している東京とどまるマンションといったものの啓発をしっかり進めてまいりたいと考えています。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ今回、つながりを持てたことを有効に活かして、さらに施策効果を高めるような、様々、今ご説明いただいた取組を進めていただきたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、８９ページ、幼保一体施設幼稚園運営費の医療的ケア児関連経費に関連して、保育園における医療的ケア児の受入れについて伺います。医療的ケア児関連経費が減額補正ということですが、ここの理由について、そもそも申請がなかったのか、あるいは申請があったがマッチングが成立しなかったのか、受入れ体制に課題があったのか、この要因についてお聞きしたいと思います。","respondent":"染谷保育施設運営課長","answer":"幼保一体施設幼稚園運営費の医療的ケア関連の計画ですけれども、こちらは、対象となるお子さん、医療的ケアが必要なお子さんの入園のお申込みがなかったため、かかる経費を減額補正したものになっております。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"確認","question":"申込みがなかったということで確認できました。今年度からの取組で、プレス発表もされた内容ですけれども、周知の仕方を改めて考えていく必要があると思います。今後どのように進めていくのかをお聞きしたいと思います。","respondent":"染谷保育施設運営課長","answer":"こちらの周知ですけれども、毎年１０月頃に配布いたします品川区立幼稚園案内に医療的ケア児の受入れが可能であることを掲載するのと、それに加えまして、障害者支援課で新たに作成しております、医療的ケアが必要なお子さんと家族のための支援ガイドブックにも。","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"先日、ある区立幼稚園の園長から直接お話を伺いました。その中で、品川区は本当に区立幼稚園での受入れ体制が、担当部門と現場と密に連携を取られていて、整備され、医療的ケア児の受入れについて十分に対応できているというようなお話を直接伺いました。現場からは、「医療的ケア児の方も両手を広げてお待ちしているのです」という声もお聞きしました。","respondent":"染谷保育施設運営課長","answer":"こちらは、常勤、１日８時間勤務の看護師を配置するというところで予算計上しているものでありますので、預かり保育についても対応するということは想定しています。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。区立幼稚園の預かり保育についても、医療的ケア児の受入れが予算化されているということが確認できました。続いて、以前の子ども若者支援・共生社会推進特別委員会での課長答弁で、保育園に入園している医療的ケア児について、１１園で計１２名が入園しているという説明がありました。保育園入園を現段階で希望、また申請している児童はどのぐらいいるのか、お聞きしたいと思います。","respondent":"染谷保育施設運営課長","answer":"医療的ケア児のお子さんの入園の状況ですけれども、令和８年度、新たに入園をお申込みされた方が４名おりまして、私立の園も含めて全体で、１２園・１２名のお子さんをお預かりする予定となっております。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私立保育園における医療的ケア児の預かりのモデル実施については、これまでマッチングの課題で成立していなかったということも聞いておりますが、昨年と今年で１園ずつ研修も行っているということをお聞きしております。これは、私立保育園であるのか。併せて、体制の整った私立保育園について公表を求める声もありますが、その可能性についてお聞きしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"受入れを実施していただいた園についてですけれども、しっかりと研修などを区で支援していることによりまして、受入れがしやすくなったというようなお声を頂いているところです。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"質問","question":"受入可能な私立保育園の公表について、可能性についてお聞きしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"対応可能な園のホームページの公表等についてですけれども、速やかな人員配置等が調整できれば、新規の園での受入れなどの初動というのもありますので、引き続き、利用者の利便性向上のためにどのような情報提供が可能なのか。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"質問","question":"前に進めていただければと思います。続いて、人工呼吸器が常時必要なお子さんの受入れについて伺います。そこで、まずは区内に１園、人工呼吸器の管理も対応可能な拠点園あるいはモデル園と位置づけ、整備を進め、呼吸器が常時必要な医療的ケア児の就園について、区の考えをお聞きしたいと思います。港区で実施されている医療的ケア児への送迎支援のような取組について、区の認識をお聞きしたいと思います。","respondent":"染谷保育施設運営課長","answer":"あと送迎につきましても、今後、今、３２園のゼロ歳児園での受入れをやっておりますけれども、検討してまいります。","id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"本日は、４７ページの移動教室経費について質問をしていきます。移動教室経費なのですけれども、今回の補正予算では歳入として計上されていますが、補正予算書では歳出が見えないのですが、移動教室経費の財源計上の考え方と、その執行までの流れについてご説明をお願いします。","respondent":"石井学務課長","answer":"こちらにつきましては、子どもたちの豊かな成長に欠かせない体験活動を確実に実施するために設置された文部科学省の補助金でございまして、例年、年度末ぐらいから文部科学省と協議を始め、年度途中に、あくまでも予算事業ですので。","id":"exchange-021"},{"speaker":"せらく委員","kind":"意見","question":"こちらは予算額の決め方というよりは、最終的に効果があった予算を補正している形だと理解しました。移動教室は、公費と保護者負担で実施されており、保護者負担分の徴収方法については、学校単位で口座振替になると思いますが、その事務作業に教員がどの程度関与しているか、お示しください。","respondent":"石井学務課長","answer":"基本的には各学校の運用方法は様々ですけれども、各学校配置の事務職員が引き落とし等の事務を行っており、教員、教職員に関しては、もちろん生徒への案内などといったことはしているとは思いますけれども、直接徴収事務に関わっているのは事務職員であると認識しています。","id":"exchange-022"},{"speaker":"せらく委員","kind":"質問","question":"直接、教員は徴収には関与していないということで承知いたしました。次に、公費と保護者負担の私費を組み合わせて、移動教室を実施されていると思うのですけれども、会計の透明性が非常に重要になってくると思います。収支報告はどのような形式で公開されていますか。区として共通のフォーマットがあるのか教えてください。","respondent":"石井学務課長","answer":"私費会計につきましては、先ほど申しました、品川区立私費会計事務取扱要綱で規定されてありますけれども、公費に準ずるものとして厳正な処理をしなければならないという認識の下、私費会計事務を学校全体で組織的に適正に管理するために。","id":"exchange-023"},{"speaker":"せらく委員","kind":"確認","question":"保護者に公開されるということで、決算が終わったものですね。そうなると、学校によって形式が、フォーマットが変わってくるという認識でよろしいでしょうか。もう一度確認させてください。次に、引き続きまして、併せて質問するのですけれども、移動教室の内容についても質問いたします。行程作成や宿泊施設や交通手段の手配、見積りの取得、契約、安全計画の策定は誰が担っているか、教えてください。","respondent":"石井学務課長","answer":"ただし、個々の学校がそれぞれ独自に行く行事の行程表などといったところに関しましては、各学校が決めるものではあります。その際には、学校の中では移動教室の担当の教員もおりますので、担当の教員と学校でチームをつくっていると認識しています。","id":"exchange-024"},{"speaker":"せらく委員","kind":"質問","question":"学校にも移動教室の担当教諭がいるということなのですけれども、その担当の方は教育活動の準備に加えて、行程策定や、先ほどお聞きしたのですけれども安全計画の策定、あと清算業務や契約も担っていると理解をしてもよろしいでしょうか。その教員の担当の方の業務時間の実態把握というのはされていますでしょうか。","respondent":"石井学務課長","answer":"例えば移動教室を担当しない先生方も、ほかの校務分掌が当てられたり、例えばＤＸの担当やＩＣＴ関係の担当などといったやり取りを我々はしていますけれども、このような形で、各学校における適正な事務配分というものは、校長の裁量の下になされていると認識しております。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。現在、教員の働き方改革というものが強く求められていると思います。専門業者を活用すれば、教員の負担軽減であると同時に、安全管理や、子どもたちにとって最新のプログラム導入がかなえられると思ったのですけれども、区としてこの杉並区の仕組みを把握していらっしゃるか確認と、あと区としてそういった検討をされたことがあれば教えてください。","respondent":"石井学務課長","answer":"一方で、教育旅行というものは、事前の学習や、生徒と一緒につくり上げるものであると思います。委託することによって負担軽減を図ること、それと、あとは教員自身の教育の本丸である部分はバランスを取らなければならないのではないのかと考えているところです。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問","question":"私からは、７５ページ、文化コミュニティ施設経費、９７ページ、商店街活性化事業費、１０１ページ、排水施設建設事業についてお伺いいたします。１点目に、排水施設建設事業についてお伺いいたします。は補正の内容を簡単にご説明ください。","respondent":"関根河川下水道課長","answer":"基本的には、実施している工事の完了による清算や、あるいは工事の状況によって、工法の見直し等が生じたこと等による執行の減という形で、補正をさせていただいたものです。","id":"exchange-027"},{"speaker":"横山委員","kind":"確認","question":"１枚目の写真は、洗足の歩道橋から西小山駅方面を撮影した線路の写真です。写真右側に写っている歩道から交番に沿って大量の雨水が線路方向へ流れ込んだことを一緒に確認しました。隙間を埋めるなどして雨水が入らない構造にできないか、東京都下水道局を交えて協議していると伺いました。そこで、このような地域を重点地区として位置づけ、優先的に対策を講じる考えについて、区のご見解をお伺いいたします。","respondent":"森道路課長","answer":"続きまして、次回、同様の豪雨があった場合の対応についてです。道路課では来年度から道路に降った雨を浸透させる浸透ますの設置を、これまでの年２０か所から年６０か所に増やしていく予定です。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"区長の申出も頂きまして、様々、課長間でも協議を行っていただいているということであります。記録的豪雨が今後も頻発することが一層想定される中で、スピード感を持って関係機関と連携し、実効性のある対策を進めていただくことを強く要望して、こちらの１問目の質問を終わります。２点目に、文化コミュニティ施設経費、商店街活性化事業費についてお伺いいたします。は補正の内容を簡単にご説明ください。","respondent":"大森文化観光戦略課長、小林地域産業振興課長","answer":"７５ページ、文化コミュニティ施設経費についての概要ですが、まず総合区民会館運営費につきましては、大井町再開発ビル等の光熱水費の減額、それから文化センター運営費につきましては。商店街のにぎわい創出としまして、商店街のイベントに対して区は助成を行っておりますけれども、商店街あるいは連携先の事情によりまして最終的には実施されなかったもの。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"理解いたしました。商店街や品川区は、歴史的にも立地的にも人が通ることで栄えてきた場所であり、現在も区内でも有数の生活動線・交流拠点だと考えています。現在、商店街や品川区周辺について、来街者の属性やその立ち寄りの実態について、区としてどのような把握を行っているのでしょうか。観光振興と商店街振興のそれぞれの現状の認識についてお聞かせください。","respondent":"大森文化観光戦略課長、小林地域産業振興課長","answer":"私からは、観光のデータ等につきまして回答します。観光振興協議会等で地元の商店街等の方々の生の声を聞いたり、エビデンスとなるデータ収集の方策につきましては、次年度を含めて引き続き検討してまいるところです。商店街でも、そういう把握をしながら、その内容を翌年度のイベントの企画にまた反映していって、それがにぎわい創出や、ご指摘のような観光の視点ということも商店街の中で大事だと考えていますので、こういうことの取組を進めながら。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"時間がなくなってしまいましたので、続きは別の款で伺いたいと思いますが、ぜひ観光振興、そして商店街、両方の観点で再整理していただくことを要望いたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"澤田委員","kind":"質問・要望","question":"本日もどうぞよろしくお願いいたします。５５ページの、朝の子供の居場所づくり事業費補助金についてお伺いいたします。本事業は３校で試行実施を始め、そのアンケート結果は９月２４日の文教委員会で報告されています。現在、段階的に開設が進められ、２４校で実施されておりますが、こちらの効果検証は行っているのでしょうか。開設に当たって、課題があればお聞かせください。","respondent":"上野子ども育成課長","answer":"委員からのご質問にお答えいたします。朝の児童の居場所ですが、現在、２４校で実施しております。各学校の登録児童数の平均ですけれども、２９名という状況でございまして、一定の効果が確認されております。","id":"exchange-032"},{"speaker":"澤田委員","kind":"質問","question":"人材確保が課題というところで、これは全国的なものであるとも認識しております。品川区も例外ではないというところですけれども、現在、課題に対して区として行っている取組、対策があれば教えてください。","respondent":"上野子ども育成課長","answer":"改善に向けましては、これまでに町会長会議、高齢者クラブでの周知や、町会掲示板でのポスター掲示、それから警備会社といった関係会社などへ、声かけなどを行ってきたところです。","id":"exchange-033"},{"speaker":"澤田委員","kind":"質問・要望","question":"最新の広報しながわのトップページでは、シルバー人材の生き生きと働く姿というのを取り上げていらっしゃって、人材確保というのはそちらでもやっていらっしゃるのかなと思ったのですけれども、さらにシルバー人材センターの母数を増やしていけるように、今回のような広報をはじめ、ケーブルテレビやＳＮＳ、掲示板へのチラシ掲示など、周知をさらに広げていただきたいということと。","respondent":"上野子ども育成課長","answer":"さらにシルバー人材センター以外の人材の活用ですけれども、今後、部内で連携しまして、既存の受託事業者に加え、別の受託先の可能性についても検討してまいりたいと思います。","id":"exchange-034"},{"speaker":"澤田委員","kind":"質問・要望","question":"人の管理というのは本当に大変だと思いますし、朝の時間は本当に貴重なので、なかなか受けてくださる方を探すうえで難しいこともあるかと思うのですが、やはり求めているというか、子どもたちに寂しい思いをさせないために、求めているお母さん・お父さんがいらっしゃいますので、ぜひ引き続き頑張っていただければと考えています。次に申請についてです。","respondent":"上野子ども育成課長","answer":"特別な配慮が必要な児童の把握ですけれども、こちらにつきましては、学校、マイスクールと情報を共有いたしまして、見守り員の方とも対応方法を確認しております。今後も関係者間の連携を維持して、適切な対応を継続してまいります。","id":"exchange-035"},{"speaker":"澤田委員","kind":"質問","question":"それと、要配慮児童が参加する際なのですけれども、その対応というところで知見を持つ方の加配というのはなかなか難しいのかなと思いますけれども、その対応についてどのようにお考えでしょうか。何かトラブルがあった場合の相談体制というのはどのようになっているのかというのも教えてください。","respondent":"上野子ども育成課長","answer":"併せて危機管理マニュアルを整備するとともに、全学校に携帯電話を配備いたしまして、区職員が朝の居場所開所時間に区役所で待機することで、緊急時に連絡が取れるようにしております。必要に応じて電話での指示および、現場に向かい、対応しております。","id":"exchange-036"},{"speaker":"澤田委員","kind":"質問","question":"よろしくお願いします。それとなのですが、少しこれはプラスというところでお聞きするのですけれども、例えばファミリー・サポート・センター提供会員で、今年、マイスター制度ができ、報酬を上げるなどの動きがあったと思います。","respondent":"上野子ども育成課長","answer":"ファミリー・サポート・センターと朝の居場所事業は成り立ちが異なるため、マイスター制度の活用というのは難しいところがありますけれども、機会を捉えて、こちらも情報収集してまいります。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。私からは、１０５ページ、Ｐａｒｋ－ＰＦＩの導入、東品川海上公園リニューアルについて。７１ページ、コンプライアンス推進事業、いじめ防止対策推進事業についてお伺いいたします。今回補正予算案の導入経費減額の理由についてお尋ねしたいと思います。","respondent":"大友公園課長","answer":"Ｐａｒｋ－ＰＦＩの導入の減額理由ですけれども、こちら、Ｐａｒｋ－ＰＦＩ事業の事業者が実施するドッグランや水辺利活用施設などの整備スケジュールが、地域との調整や関係機関との協議により変更されたことに伴って。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"では工期が延びるという理解でよろしいでしょうか。","respondent":"大友公園課長","answer":"全体の最終の工事期間は８月・９月というところは変わっていないのですけれども、着手時期が変わって、後ろは同じというような状況です。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。実際にできる飲食施設、水辺バーベキューテラスも附帯されるということなのですけれど、景観に配慮して、当初２階を予定していたものが１階のみということになったようです。現状、分からない部分もあるかと思いますけれども、現時点でバーベキューテラス以外の店舗の内容というのは、どのようなものになるのでしょうか。","respondent":"大友公園課長","answer":"飲食施設を含めた施設の運営に関する内容ですけれども、こちらは現在、事業者において検討を進めているところです。今後、区や地域などとの調整を経て、６月末頃を目安に取りまとめていく予定です。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"少し心配しているのが、１階のみの面積だけの飲食施設の収益だけで、公園整備というのはどの程度できるのかと、不安に感じているところです。東品川海上公園の整備は、＜Harbor of Harmony＞共同企業体との協定によるかと思うのですけれども、まずこの収益を活用しての公園整備の内容と、売上げの何％を公園整備に充てるかなど、その辺りはどのような協定内容になっているのでしょうか。","respondent":"大友公園課長","answer":"こちらをどのような形で運営していくのかというところについては、その運営事業者に委ねられるところではあるのですけれども、こちらは事業者で収支計画というものを立ててございまして、２階が１階になるというところの影響というところも含めて。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問・要望","question":"区の公園整備の想定としましては、ドッグランや水辺アクティビティの管理などを行う費用ので大丈夫だということで、そこは東品川海上公園のその他の大きい整備、ふだんからの植栽管理などといったことまでは求めていないという理解でよろしいのでしょうか。","respondent":"大友公園課長","answer":"今回整備されるものといたしまして、ウエルカム花壇やデッキなど様々ありますので、そういうものの維持管理も、この費用の中でやっていただく形となっています。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"その程度でしたら何とか、１階のみの飲食施設でも達成できるのかなと思っているのですけれども、万が一、全然、飲食施設の収益が上がらず、今おっしゃった範囲内での維持管理すらもできないという場合におきましては、やはりその飲食施設の、例えばお店の内容が悪いなど、様々原因があろうかと思いますけれども、当初入った飲食施設の内容、業態の状態が悪いから。","respondent":"大友公園課長","answer":"その間でいろいろな、想定しないことというところが出てきた場合については、その都度協議という形になっているところですが、基本的にはこの２０年間、当初提案してきた形で実施していただくものと考えているところです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"ドッグランも、東品川海上公園で区内初の常設ドッグランが整備されることになりますけれども、犬を連れてきた方も、飲食施設に入って利用することができるのかということ。どうしても犬が嫌いな方などもおりますので、その辺り、今後しつけやマナーの関係や、その辺り、ほかの公園利用者との関係、その対策というのはどのようにお考えでしょうか。","respondent":"大友公園課長","answer":"今後、区との調整を経て、こちらも６月末頃、取りまとめていく予定ですけれども、犬を連れた方等々の利用者のマナーなど、様々な課題等々もあるかというところで認識しておりますので、区と事業者が緊密に連携して対応していきたいというところで考えているところです。","id":"exchange-044"},{"speaker":"筒井委員","kind":"質問","question":"区としての考えとして、どのように考えていらっしゃるのでしょうか。","respondent":"大友公園課長","answer":"今回、ドッグランができるというところを踏まえて、どのエリアに立ち入ることができるのかなど等々、そこの親和性をどうしていくのかというところで、一定、親和を持たせる必要はあるというところ、立ち入れたほうがいいという考えの下で調整していくのですけれども。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問・要望","question":"交付金の関係でしょうか、社会資本総合整備計画で、ここのＰａｒｋ－ＰＦＩ事業に関連して、利用者を４０％増加させるという目標を立てられていると思いますけれども、やはり今の東品川海上公園の利用者から４０％増加させるということは、もうなかなか大変なことだと思いますので、これは周知が非常に大事なことだと考えています。","respondent":"大友公園課長","answer":"公園の魅力と利便性を向上させて、１年を通してにぎわいのある公園を目指しています。そのようなところの周知というところにつきましては、様々な媒体がいろいろあるかと思います。機会を通じて、積極的な発信をしていきたいと考えているところです。","id":"exchange-046"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。続いて総務課のいじめ相談対策室、いわゆる区長部局についてお伺いしたいと思います。令和５年度に決定され、実際、令和６年１月から稼働されたかと思いますけれども、約２年ちょっとたちまして、現時点の成果と課題というのはどのようになっているのかということをお聞きしたいと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"重大事態との関係性につきましては、いじめ重大事態自体は区長部局での調査になりますけれども、そこに至らない早期解決・早期発見に向けて対応しています。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１０３ページ、旗台小学校整備事業、そして７９ページ、戸籍・住民基本台帳関係費に関連して、臨海斎場についてお聞きしていきたいと思います。最初、１０３ページ、旗台小学校前地区整備事業補助金、旗台小学校前地区事業推進業務委託がマイナス補正になった理由をお聞かせください。","respondent":"小川木密整備推進課長","answer":"減額になった理由ですけれども、実施計画に関しましては、予定していた内容と計画のところが、進度があまり進まなかったというところからの減額、それと建物調査に関しましては、想定していた件数が思ったより少なかったといったところで、減額させていただいたところです。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"令和７年度、本年度のスケジュールと都市計画決定、組合の設立、事業認可の取得予定について。この面積が１,０００m2ございまして、対象建物が長屋建物が６列で４９戸、そして共同住宅が２棟ということなのですけれども、なかなか進まないというところで、現在の進捗状況をお知らせいただきたいと思います。","respondent":"小川木密整備推進課長","answer":"併せまして、事業計画のところから、現地調査等で測量等の業務等を現在行っているところです。","id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは以前から、私はこの予算特別委員会・決算特別委員会で質問をさせていただいていますけれども、前面に旗台小学校があります。あそこはＲＣ造ですから躯体は大丈夫だと思うのですけれども、その体育館がある西側まで延焼が、そういうおそれがあるということを、なるべく近隣町会、当該町会を含めて、皆さんに周知していただきたい。その辺についてもう一回、お聞きしたいと思います。","respondent":"小川木密整備推進課長","answer":"なかなか権利者の方が多いことや、地区外、遠くに住まわれている方が多いところで、ほかの地区より、非常に時間を要しているというところではありますけれども、我々もしっかりと、こちらは早急に解決していきたいとは考えてありますので、できる限り早く。","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すぐにはできないかと思うのですけれども、なるべく早めにやっていただきたいので、要望でよろしくお願いいたします。次に７９ページ、戸籍・住民基本台帳関係費に関連して、臨海斎場についてお尋ねいたします。今度、令和１２年度までに、北側ですか、増築されるということで、この説明も受けて、ますますもっと利用者が増えるというのを、しつこいですけれども、認識いたしました。","respondent":"築山戸籍住民課長","answer":"ただ、状況としてあまり利用されていないです。臨海斎場といたしましては、今後新たな式場ができるということで、利用状況等を見ながら、アクセスのあり方について引き続き検討したいということで考えているということで聞いております。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これからいろいろ調査していただいて、バス事業者もやはり民間ですから、利益を上げないといけない部分はあるので、やはり、少ないかもしれませんが、状況を鑑みながら、また今後も働きかけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"４９ページ、物価高騰対策重点支援地方創生臨時交付金から、しながわ生活応援事業について伺います。品川区議会公明党は昨年の１２月に、森澤区長に、国の交付金を活用いたしまして、区民への物価高騰対策として、利便性の高い金券等を全区民に配布し、その額が食料品高騰による負担の軽減に資するものとなるようにすることと、具体的な生活支援の要望をさせていただきました。","respondent":"今井しながわ生活応援担当課長","answer":"ほかの区の状況といたしまして、給付時期として最も早い時期を公表している自治体については、現金給付を予定している自治体の中でも、さらに非課税世帯向けの給付などで、今の時点で既に口座情報を区として取得しているような自治体が。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在、進めていただいているということで、春以降というところがまだ見えていない、具体的な日にちが見えていないということを確認いたしました。地域の方から、マイナンバーカードにひもづけた公金口座を活用するのはどうなのかというお声が上がりました。現在、マイナンバーカードを使って品川区が取り組んでいる、給付で活用されている事例があればご紹介いただきたいと思います。","respondent":"横田デジタル推進課長","answer":"マイナンバーカードの氏名・住所を変更いたしましても、公金口座の氏名や住所が変更されないために、照会時にエラーとなって返されるというような課題があります。","id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"そのような具体的な事例を示しながら、ギフトカードを使い切ることができることなどを説明した取扱い説明書を作成し、ギフトカードと一緒に同封していただきたいということも要望したいと思います。そのような工夫はいかがでしょうか。詐欺に遭わないような意識啓発は非常に大事だと思いますが、このような取組について、それぞれ見解を伺います。","respondent":"今井しながわ生活応援担当課長","answer":"町会・自治会や、あと地域ニュース等への掲載の部分ですけれども、区としても地域住民の皆様に本事業の周知を進める上で、町会・自治会への周知が一定のポイント、キーになってくると認識していますので、既に１２月に、補正予算をご議決いただいて以降。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"具体的にしっかり取組を進めていただきたいと思います。「うれしなカード」という愛称をつけるということをお知らせいただきました。発送の際は、ご自宅で受け取れない方も少なからずいらっしゃいますので、それぞれお一人お一人が確実に受け取っていただいて、もらってよかったと思っていただけるような柔軟な対応を要望いたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、９６ページの産業経済費に関わって、省エネルギー対策・業務改善設備更新助成金の継続、中小・零細企業の賃上げ支援について伺います。ぜひ、ここへの支援をしていただきたいと思いまして、省エネルギー対策・業務改善設備更新助成金について伺います。それと、ぜひ、助成金について、継続していただきたいと思いますが、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"そういうことですので、今、エネルギー価格の推移や、国の支援策、現在１月から３月に入っておりますけれども、こういうことも見ながら、実施するかどうかということも含めて決めているところです。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々動きを見ながらということでしたけれども、ぜひこの間も、この助成金は区民の方々にも喜ばれてやっておりますので、ぜひ復活・継続させていっていただきたいと思いますし、実際に省エネ対策でもありますので、恒久的な制度にもしていくべきだと思いますが、その考えを伺いたいと思います。やはり中小企業の経営の中で大変なのは固定費だと思うのです。","respondent":"小林地域産業振興課長","answer":"ですので、我々としましては、先ほど申しましたとおり、エネルギー価格の推移あるいは国の取組といったものの有無、また中小企業の景気状況というものも総合的に勘案しまして、支給の取組についてはまた考えてまいりたいと思っているところです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ省エネルギー対策・業務改善設備更新助成金を復活させていただきたいと思います。次に、中小企業の賃上げ支援について伺いたいと思います。やはり今、物価高の下で賃上げも求められていると思います。ですけれども、やはり賃上げが進めば、地域経済の活性化にもつながってくると思います。共産党は、代表質問でも賃上げ支援を求めました。こうした支援も必要ではないかと考えますが、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"これについては、今後の効果や、賃上げ未実施の他の中小企業への波及効果なども見ながら、区としてどういう取組が今後必要かということは考えてまいりたいと考えています。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"様々賃上げ効果があるということで、お話しいただきました。継続的に実施していくということは当然必要だと思いますけれども、やはり業績がよくなったら上げようということではなくて、賃上げが進めば購買力が上がって、生産力も高まって、品質が高まり、顧客の満足度も高まるということで利益にもつながる。だからこそ促進していくということが必要だと思いますが、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"賃上げ・引上げの余力を引き出すには、単発の取組ではやはりなかなか難しいと考えています。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、そうしたことを進めていっていただきたいと思いますし、一番は直接支援です。これまでも岩手県などを紹介してきましたけれども、今回２３区でも豊島区が、補正予算で賃上げ促進支援金を実施するということで示されました。やはり中小企業を支援して盛り上げていくということが、地域経済が発展していく、活性化していくためにもつながりますので、これは求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"えのした委員","kind":"質問","question":"私からは、９７ページ、商店街活性化事業費、共同装飾灯維持管理費補助、商店街にぎわい創出事業、時間があれば９９ページ、商店街活性化推進事業、アーケード架替え計画助成等について、先ほど一部、横山委員からもご質問がございましたが、違った視点からお伺いいたします。共同装飾灯維持管理費補助の減額補正についてお伺いします。","respondent":"小林地域産業振興課長","answer":"最終的には執行率が８０％ということで、この取組を使って商店街の負担軽減を引き続き実施していくです。","id":"exchange-062"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。減額補正で、商店街が有する装飾灯１,９５０本とありましたけれども、理解いたしました。商店街だけでなく地域のためにと、共同装飾灯の維持管理に努めてきたが、組合員の方からは不平不満も出てくるのが現実で、本当に続けていくのが大変だ」とのお声も伺っております。各商店街の負担軽減のために、より一層の支援が望まれますが、区のご見解をお願いいたします。","respondent":"小林地域産業振興課長","answer":"今後、引き続き物価高騰あるいはエネルギー関係の高騰というのがある中で、商店街の負担をできるだけ減らすようにということで、計算式については予算額の中で一定の見直しを行いまして、７０％以上というところに、できるだけなるように、１つ。","id":"exchange-063"},{"speaker":"えのした委員","kind":"意見","question":"装飾灯が公共インフラの性格を有するということも考慮していただいて、来年度、計算式を見直して、また補助率も７割になるということで、ご支援をありがたく受け止めております。商店街のにぎわいの創出も減額が行われております。この事業の収支と直近の状況についてご説明ください。","respondent":"小林地域産業振興課長","answer":"ただしイベントの実施率としましては、今回、補正に載せている中では、５８件のイベントが予定されている中で５３件を実施しているですので、おおむね予定どおり実施ということで我々としては認識しています。","id":"exchange-064"},{"speaker":"えのした委員","kind":"確認","question":"様々、商店街のご事情などもあるかと思います。年度中の計画の見直しがあったということの確認が取れました。令和７年度は５８件のイベントが予定でしたけれども、商店街のイベントの実施件数は増加傾向にあるのでしょうか、それとも減少傾向にあるのでしょうか。お知らせください。","respondent":"小林地域産業振興課長","answer":"令和８年度の商店街支援、助成金の中では、今年度よりも１０件程度イベントが増加する見込みですので、区としてもこういうものを使いながら、商店街のにぎわい創出あるいはさらなる経済活性化につなげていきたいと考えています。","id":"exchange-065"},{"speaker":"えのした委員","kind":"質問","question":"最後に、昨年１２月、中延商店街、なかのぶスキップロードで発生した火災の支援について、お尋ねします。私も、火災があった日の早朝に現地を視察して、後日、防災士仲間と防災士研修センター代表と共に、中延商店街理事長にお話を伺いました。複数店舗とアーケードが被災されました。再開された店舗もありますが、一日でも早い再建に向けて、区もできる限りの支援をお願いいたします。","respondent":"小林地域産業振興課長","answer":"中延商店街での火災ですけれども、昨年１２月２３日未明の火災でありまして、アーケードの一部が焼失するということと、あと６店舗が被害に遭われたということで認識しています。","id":"exchange-066"},{"speaker":"えのした委員","kind":"質問・要望","question":"これからも品川区の元気の源、商店街への手厚く温かい支援を要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"１０３ページ、市街地整備事業費から、武蔵小山、品川浦、戸越の各再開発に関わって、再開発事業のあり方について、検証・分析を求めて質問したいと思います。巨額の税金を使って、区内各地で再開発が進んでおります。既に事業認可された計画をもとに、今後さらに戸越、品川浦、大井町、西大井と、次々と再開発が拡大されております。そこで、この説明は現在も同じか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"地域の方々が、市街地再開発事業を進めると判断した際には、やはり建物の共同化が必要となってきます。そこに住むには、共同建物に住む、または地区外に転出するなど、生活再建が関わってくるというところで、ご不安の声があるということは区も認識しています。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、区長自身が答弁で「耳を傾けます」とおっしゃっているわけですから、区長はどのような反対意見を聞いたのかということを改めて伺いたいと思います。少なくとも、各地で同じような声が上がっているわけで、なぜそうした声が上がっているのか、そこは冷静に検証や分析が必要だと私は思うのです。その辺も改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"今後、シェードポリシーの検討などを行っていくといった、これまで行ってきた再開発の検証・分析をまた行いつつ、今後の取組に活かしていきたいと考えています。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"区議会に寄せられた陳情は、もちろん区長も目を通しているかと思いますし、地域によっては直接お会いしているということですけれども、ぜひ様々な話を伺っていただきたいと思うのです。追い出しはやめてほしい」と。検証・分析をしていきたいというご説明がありましたが、こうした住民の声がなぜ上がるのか、ここを真摯に検証・分析していただきたいと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"不安がある方に対しましては、どういった不安があるのかといったことを、丁寧に声に寄り添って進めていきたいと考えています。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて、検証・分析というのは、何をどう検証・分析するのか、もう一度ご説明いただきたいと思います。ですから、追い出しだという声が上がるわけです。検証・分析とおっしゃるのであれば、こうした住民の声がなぜ上がるのか。そこをしっかりと分析していただきたい。「丁寧に追い出しを進めていく」では大変困るわけですけれども、改めてその点をご説明いただきたいと思います。","respondent":"中道都市開発課長","answer":"３分の２以上の同意ですけれども、区といたしましては、より多くの方々が、安心して、不安がないような形で、まちづくりが進められるよう取り組んでいきたいと考えています。","id":"exchange-071"},{"speaker":"松永委員","kind":"質問","question":"私からは、８３ページの品川区介護福祉専門学校修学資金貸付事務についてと、品川区介護職員居住支援手当について、１０５ページの住宅・建築物耐震化支援事業について伺いたいと思います。初めに、８３ページの品川区介護福祉専門学校について、伺いたいと思います。そして、区民の約５人に１人に当たる２割の方が６５歳以上の高齢者という状況にあります。過去に遡ってどういった傾向が見られるのか。","respondent":"菅野高齢者福祉課長","answer":"令和５年度が、１年生が２３人で２年生が１３人となっております。そのうちの外国人の数ですけれども、令和７年度、今年度に関しましては、１年生で１名、２年生で１名、それぞれ、中国籍の方。令和６年度は１年生が１名で中国籍の方となっております。","id":"exchange-072"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほどご答弁いただいたように、どんどん生徒数が減ってきているというのが現状です。そうした中で、今後、品川区として介護福祉専門学校という立ち位置ですか、今後どういった形で進めていかれるのか。例えば、必ず介護職に入れるというか、就職率も１００％、国家資格の合格率もかなり高いというような点が挙げられてはおるのですけれども、その中で、２点ぐらいか、やはりデメリットというのがあります。","respondent":"菅野高齢者福祉課長","answer":"生徒数が少ないというところがあるということと、あとキャンパスも建物の中の、中小企業センターの公会堂６階ということもございまして、口コミの、委員がおっしゃったとおり、華やかさがないという部分もある一方で、すごくアットホームで。","id":"exchange-073"},{"speaker":"松永委員","kind":"質問","question":"今、生徒数が少ないということで、営業される方がいろいろな各学校を回られているとは思うのですけれども、その方から、どういったご意見があるのか。いろいろ対策は取っているのだけれども、なかなか入ってくれないという、もしそういった理由や困っていることなど、営業されている方のご意見というのを伺えればと思います。","respondent":"菅野高齢者福祉課長","answer":"本年度については、今のところ、２０９校回っているほか、電話での営業等も９５校へしています。東北のほうの高校にもダイレクトメールを送付した後、一件一件、営業の電話をかけたというところもありますが、現状としては、なかなか入学までは結びついていないです。","id":"exchange-074"},{"speaker":"松永委員","kind":"質問","question":"やはりなかなか生徒数が集まらないという状況。最後に耐震化についてなのですが、あまり時間がないので、少しだけ伺いたいと思います。今回、耐震についても、なかなか助成を活用される方が少ないので、ぜひ今後、耐震化というのはとても大事であるということを含めまして、全区民に対しての周知をお願いしたいのですけれども、区のご意見と今後の展望について、最後にお伺いしたいと思います。","respondent":"森建築課長","answer":"委員ご指摘のとおり、耐震化につきましては、区民の皆さんに周知してご理解いただくことはとても大事だと考えています。避難所等に関しましても、在宅避難ということが一番皆様にとっていいと考えていますので、様々施策を通じまして、耐震化を進めてまいりたいと思ってあります。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"令和６年に基本設計が始まり、現在、実施設計中、間もなく仮設校舎の建設工事が始まる浅間台小学校、来年４月から改築工事スタートと伺っております。続けて質問します。裏門のところです。この倉庫は学校の敷地内にあるのかどうか、なぜ学校の敷地に町会所有の倉庫が存在するのかの経緯、そして撤去を求める理由、また撤去の期限についてお知らせください。","respondent":"荒木学校施設担当課長","answer":"は１点目の補正の減額の理由です。こちらは、今年度予定しておりました、改築に必要な申請手続につきまして、関係機関と協議を進めた結果、来年度の実施となったため、本年度分から減額したものです。この変更の減額に伴う事業スケジュールへの影響はございません。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ＪＲという言い方を町会の方はしていましたけれども、もともとはＪＲの土地であったというところが、区にいつの間にか移管されていてみたいな内容だったと思います。会長をはじめ、町会の方も困り果てている。スペースに余裕があるので、二日市公園に町会倉庫を移転できないかというご相談をされたところ、残念ながら、この要望も却下されたということなのですが、駄目な理由というのを教えてください。","respondent":"大友公園課長","answer":"具体的には、公園の管理施設としての倉庫、災害応急対策に必要な物資の倉庫のみとなっております。そのため、町会の備品などを入れる倉庫をここに設置することはできないということになってあります。","id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこで、教育委員会にお願いしたいのですが、これまでの長年にわたる歴史的経緯、それも無理がない経緯や学校施設への地元町会の協力、そして今後の共存という意味で、改築に当たっては、これまでどおり学校の敷地内に何とかこの倉庫を残す方向で考えていただきたいと思うのですが、お考えをお聞かせください。改築工事の間の代替地も含めてぜひご検討いただきたいと思いますが、ご所見を伺います。","respondent":"荒木学校施設担当課長","answer":"２点目の工事中の移転先ですが、工事中の対応につきましては、今後、改築工事の施工者が決定した段階で、具体的な協議・調整を進めていきたいと考えております。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問","question":"私立幼稚園保育料助成ですけれども、時間がないのでまとめて質問します。同じときに質問をした、いわゆる現在の償還払い、１回払わなくてはいけないところを、法定代理受領といって、いわゆる４万円を超えた部分だけ払えばいいですよというかたちにして欲しいと、ぜひお願いしたいということを申し上げましたところ、当時の課長、今と一緒です。","respondent":"芝野保育入園調整課長","answer":"申し訳ございません。まだ手作業でやらせていただいております。新システムによる補助金の支給は、令和８年度、前期分から行う予定であり、システム化により業務の効率化が図られ、職員の負担軽減につながるものと改めて考えております。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど午前中に３,５００万円の減額補正の理由というのは伺いました。新宿区の落合公園は、公園全体として０.９haしかないのですけれども、６９０m2のドッグランを設置しているということから、これは工夫次第で設置できるのではないでしょうかと設置を求めてまいりました。値段は幾らになるのでしょうか。すぐに担当課に伺いまして、お聞きすると、やはり有料になるという想定であるということでした。","respondent":"大友公園課長","answer":"時間、料金等々につきましては、こちらを含めた施設の運営に関する内容を、現在、事業者において検討を進めているところです。今後、区との調整を経まして、６月末頃を目指し、取りまとめていくという予定です。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"意見","question":"飲食関係の部分などもあるのですけれども、その辺り、もし今どういうふうに考えていらっしゃるのか。先ほど、持続可能なドッグランというお話もありました。これは、営利を取ってもらうべきなのかというところで、その辺りの話合い、先ほどの繰り返しになってしまいますが、最後にご答弁いただいて終わりたいと思います。","respondent":"大友公園課長","answer":"その費用を丸々維持管理や、維持管理を全部、収益で賄うという考えもないところです。あくまでも一部の補填という形を考えてあります。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問","question":"私からは、５５ページ、子どもの居場所運営費について伺います。朝の居場所の活動と理解しております。午前中、ほかの委員からも質疑がありまして、基本的な情報については伺うことができました。基本的な利用状況については午前中の質疑で伺いましたが、シルバー人材センターに委託しながら、体制については、どうもご答弁からは厳しい状況もあるのかなと理解しております。","respondent":"上野子ども育成課長","answer":"朝の居場所の開設時間から職員が職場に待機して、常時、対応可能にしております。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。なぜこの懸念が出てきたかというと、もちろん朝の居場所事業では静かに過ごすということになっていると、広報しながわでも明記されておりますし、１人でぽつんと待っていることもあるのかもしれませんけれども、子どもたちが集まれば、子ども同士、ついふざけてしまうこともあると想定するべきではないでしょうか。","respondent":"上野子ども育成課長","answer":"トラブルがあった際の対応についてのご質問かと思います。トラブル等、緊急時の対応につきましては、地域見守り員の方に、けがの対応、それから子どもとの関わり方についての研修を行っております。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問","question":"子ども育成課としての姿勢は理解いたしました。これは私の想像ですけれども、教員の方たちが心配されるのは、その辺にあるのではないかと思います。その対応はあくまで子ども育成課として対応すべきということです。私もそれは当然だと思うのですけれども、子ども育成課とシルバー人材センターとの取決めでは、その辺までの具体的な取決めがされているのか伺います。","respondent":"上野子ども育成課長","answer":"現時点で試行３校で実施した中では、そのような事例はございませんけれども、きちんとした対応ができるような体制は整えております。","id":"exchange-084"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。それで、シルバー人材センターの方たちとの取決めというのは、やはり契約だと思うのですけれども、その中にそういう具体的なことも明記されていると考えてよろしいのでしょうか。","respondent":"上野子ども育成課長","answer":"運用の中で、トラブル、緊急事態が発生した場合には指定の連絡先に連絡をするということも記載しておりまして、緊急事態が発生した場合には、何かあった場合は子ども育成課に相談して対応してくださいというところは徹底しています。","id":"exchange-085"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、仕様書をきちんと見ていなくて質問しているので大変申し訳ないのですけれども、今までのいろいろな仕様書を見ると、書いていないことまで求めているのではないのかなと思うケースが、ままあるのです。ただ、この事業が本当に必要ということであれば、そこの人員をきちんと確保することで、子ども育成課として、ぜひ前に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"こしば委員","kind":"質問","question":"私からは、１３１ページ、国民健康保険の歳入に当たる繰入金と未納月額についてお伺いしてまいります。保険制度の取組が世界の中でもトップクラスとも言えます、この医療保険大国の日本。国民健康保険の赤字補填を国民健康保険に加入していない区民に負担を強いることにつながってしまう法定外繰入金については、公平性の観点から解消していくべきと考えますが、まず区の考えについて教えてください。","respondent":"山下国保医療年金課長","answer":"東京都国民健康保険運営方針におきましても、国民健康保険財政において必要となる費用については、原則として収支が均衡するように、公費負担と保険料で賄うこととされてございまして、公費負担以外の部分で費用負担を求めることは、給付と負担の関係が不明確となり。","id":"exchange-087"},{"speaker":"こしば委員","kind":"確認","question":"原則は、公費と保険料であると。負担の振り分けが不明確となってしまうというご説明を頂きました。振り返りますと、今、国民健康保険の保険料の未納額は全体で１,４００億円ほどと認識しております。品川区の未納額について、まず確認させてください。そして、この未納額が与えます法定外繰入金への影響についても併せて教えてください。","respondent":"山下国保医療年金課長","answer":"段階的に縮減していく中で、当然、収納率の向上というところが肝要になってまいりますので、そういった取組を一層進めてまいりたいと考えています。最終補正予算における収納額ですけれども……。","id":"exchange-088"},{"speaker":"こしば委員","kind":"質問・要望","question":"繰入金の減少が、ひいては区民全体の納得感にもつながると思います。私は、日本人・外国人の区別なく、ひとしく義務は果たされるべきと考えます。前提といたしまして、未納者で日本国籍を持つ区民と、またそうではない外国籍の区民について教えていただきたいと思います。先ほど７割という話を聞いておりますけれども、それぞれの割合について教えてください。","respondent":"山下国保医療年金課長","answer":"ただいま委員からございましたように、未納額ではなくて収納の率というところでお答えを申し上げますと、日本人世帯主では現状７５％ほどというところ、外国人世帯主については６３％ほどというところで推移しています。","id":"exchange-089"},{"speaker":"こしば委員","kind":"質問","question":"国民皆保険制度は、日本の健康医療を守る大きな役割があります。この収納率も、やはり先ほど６３％が外国人の方で、日本人の方が今、７５％という話で、だんだん差は縮まっているという答弁は頂いておるのですけれども、これを例えば２０％上げていくことによって、どのぐらいの歳入、収入になっていくのか、分かれば教えていただければと思います。","respondent":"山下国保医療年金課長","answer":"こちらは、昨年度、令和６年度の時点では５,０００人だったところ、１００人ほど増えているという状況でして、国民健康保険全体での加入者が６万人余というところからしますと、やはりその割合が増えているというところがありますので、外国人世帯の方の収納率が上がれば。","id":"exchange-090"},{"speaker":"こしば委員","kind":"質問","question":"全体が上がるのは、もちろん全くそのとおりであると思います。具体的には、未納の情報を提供していくという取組を、去年の１２月からたしか始めるという話を聞いておりますけれども、その進捗状況について、まず教えていただければと思います。","respondent":"山下国保医療年金課長","answer":"厚生委員会、１１月の中・下旬の段階では１,０００件ほどとお答え申し上げたところがあるのですが、その後、精査等を踏まえまして、３３０件ほどの情報連携を図ったところ、実際にその効果というところをつかむのは、まだなかなか時間的に難しいところがありますが。","id":"exchange-091"},{"speaker":"こしば委員","kind":"確認","question":"３３０件の情報提供があって、その中でも実際に納付したいという相談もあったということで、確実に出入国在留管理庁との連携が前に進んでいることを確認させていただきました。今後、これから外国籍の方も当然増えてくると思います。","respondent":"山下国保医療年金課長","answer":"ただいまございました、公共サービスメッシュを活用した連携について、自動的に出入国在留管理庁と取り組んでいるところがありますので、引き続き収納率の向上に努めてまいります。","id":"exchange-092"},{"speaker":"大倉委員","kind":"質問・要望","question":"非常に授業でもよく使われて、子どもたち、児童・生徒も、先日は品川区立品川学園などにも伺って、活用がすごく進んでいるなというところで、議会としても、私自身も主権者教育に参加したときに感じているところであります。自分も以前、質問させていただきまして、順次進めていくというところのご答弁をいただいたかと思いますが、今現在どうなっているのかということを教えてください。","respondent":"羽鳥防災課長、石井学務課長","answer":"というのも、声といたしましては、３階建て以上ですけれども１５戸未満のマンションもございまして、そういったところからも、エレベーター用防災チェアを設置したいという声も上がっている状況ではありましたので。今年度ですが、開始してから各学校のアセスメントを行いつつ、今、準備を進めており、昨年末からこの３月にかけて、順次、学校のネットワーク機器の更改作業を進めているところです。","id":"exchange-093"},{"speaker":"大倉委員","kind":"質問・要望","question":"特に子どもなどが１人で入ったときなどは、なかなか使い方や、それが何かというところが分からないことも考えられますので、そういったこともセットで進めていっていただきたいのと、保存水や簡易トイレなどの使用期限というのが、更新することが必要だったときはどういうふうに対応するのかなと思っておりましたので、そこだけ教えていただければと思います。学校のＩＣＴ環境ですが、分かりました。","respondent":"羽鳥防災課長","answer":"こちら、お子様でも分かりやすいようにというところで、使い方のところは見直していきたいとは考えてあります。中身の更新につきましては、各納品先のマンションで更新して、それを継続的に設置していただくということを想定しています。","id":"exchange-094"},{"speaker":"大倉委員","kind":"意見","question":"ぜひお願いいたします。最後、こういったタイミングを捉えて、先ほども午前中の答弁でもありましたけれども、スカイツリーの事故のようなときにはより一層危機感を持って対応、考えが深まっている状況かなと思いますので、こうしたタイミングを見計らって、また周知等、さらにこういった防災が周知されていくように取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"提案","question":"ふるさと納税を楽しみにしている方がおられる一方で、この制度がなければ、どれだけ区民のウェルビーイングを向上できたかと、私もじくじたる思いではあるのですけれども、制度の抜本的な見直しというのを国には引き続き、区として求めていただきたいのですが、制度がある以上、指をくわえて見ていては流出額が増えてしまうということで、私としても過去に様々な提案をしてまいりました。","respondent":"宮澤税務課長","answer":"大井競馬場関連のふるさと納税の返礼品です。指定観覧席の体験型ということで、Ｌ－ＷＩＮＧ、またダイアモンドターンでの観戦席の返礼品、あとキャラクターグッズの商品型の返礼品を用意しています。","id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"提案","question":"そこでご質問したいのは、こういった大井競馬場のバックヤードツアーと併せて、「ウマ娘」の声優とのトークショーや、関係者席や大井競馬場のダートコースに入れるといった、「ウマ娘」とも併せた様々なコラボ、そしてプラスアルファで品川区内の例えば宿泊施設への宿泊券等もプラスして、いわゆる聖地巡礼を起点とした地域経済。","respondent":"宮澤税務課長","answer":"もう一つは、提供していただく事業者との調整が必要になってくる。特に、今ご提案いただいた内容のものというのが、様々な著作権や、あと馬主との関係というのもあろうかと思います。そういったところを踏まえて検討する必要があると考えています。","id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"大井競馬場は年間１００日開催されていまして、これを１０万円で、もし１日３レース、枠をつくると、それだけで３,０００万円の返戻品、寄附額になるかと思うのですが、こういったものは、商品の作成や在庫管理といった手間もなく、気軽にできる、すぐできるラインナップになると思うのですが、こういったものはいかがでしょうか。可能でしょうか。","respondent":"宮澤税務課長","answer":"大井競馬場につきましては魅力的な地域資源と感じておりまして、この間、様々な返礼品に関して連携してきているところですので、その中で引き続き進めていきたいとは思っているところです。","id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"せっかく、２３区で唯一、競馬場を有している品川区ですから、ぜひ積極的に連携して、魅力ある商品開発を続けていただければと強く思います。プラスして、例えばレースで使われたゼッケンや蹄鉄の販売。それこそ今、「ウマ娘」の効果で裾野が広がっていて、大井競馬場の売上げも過去最高を更新し続けていると聞いておりますので、ぜひこういったものも検討していただきたいと思いますが、いかがでしょう。","respondent":"宮澤税務課長","answer":"先ほど委員がご提案のとおり、メガイルミ等もあります。様々、返礼品を拡充していく余地というのは多分にあろうかと思いますので、特別区競馬組合を含めて、関係事業者と調整が必要だとは思っているところです。","id":"exchange-099"},{"speaker":"やなぎさわ委員","kind":"意見","question":"他自治体にない大きな強みです。今年は午年ということもありますので、ぜひこういったことを進めていっていただいて、特に観光型も含めて社会貢献型、様々なメニューが競馬場を通じて実現可能だと考えておりますので、今後とも、ぜひともこの検討をさらに前へ進めて、ぜひ区民のウェルビーイングのためにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"私からは、４１ページの社会保障・税番号制度システム整備費補助金、それから１０７ページの居住支援事業の２つを伺いたいと思います。大家が家主安心保険に加入した件数と、また加入に当たっては、物件に対しての一定の条件があったかと思います。この条件はどういったものなのかお知らせください。","respondent":"川原住宅課長","answer":"今年度１１月から開始したところですが、セーフティーネットの建物を中心に区から周知させていただいて、現在は３件の加入といったところです。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"１０月からで、今３件ということです。これは、先ほどの入居促進事業の全てが高齢者ではありませんけれども、１７７件、今はもう年も越して年度末ですから、相当、件数もまた増えていると思いますけれども、家主の安心保険というものが、入居促進事業を受け入れてくれる家主を拡大するという意味での後押しになるものとも考えております。区としてはどのように捉えておりますでしょうか。お聞かせください。","respondent":"川原住宅課長","answer":"利用拡大への取組については、やはり保険という制度の加入の周知だけではなくて、住宅確保要配慮者のよりよい住宅の確保というところで、断らない家主、家の提供というところでは、引き続き、セーフティーネット住宅の制度の拡充・強化・促進にも資するものでございまして。","id":"exchange-102"},{"speaker":"塚本委員","kind":"意見","question":"居住サポート住宅については、スタートして間もない事業というところでもありますので、ぜひ今後しっかり拡充というか、安心保険を活用しての入居促進事業がより一層、広がっていくようにということでお願いしたいと思います。これを１つの担保として、高齢者といえども入居しやすくするというための事業ですけれども、こちらと家主安心保険。","respondent":"樫村高齢者地域支援課長","answer":"すみ分けといったところですけれども、委員ご指摘のとおり、住宅課でやっている事業につきましてはオーナーに加入いただく、高齢者地域支援課で社会福祉協議会に委託しております安心居住サポートにつきましては、ご本人に加入いただきまして、転居の際に、家主のお金。","id":"exchange-103"},{"speaker":"塚本委員","kind":"質問","question":"社会保障・税番号制度システム整備費補助金ですけれども、１,９１３万８,０００円ということで、この金額が住民基本台帳システムのシステム改修に充てられているということです。戸籍への振り仮名追加の法改正に伴う改修と伺っておりますけれども、最初にこの補助金、振り仮名を追加するというのはすごく大きな改修のように受け止めるのですが、１,９１３万８,０００円で全額賄えたのか。","respondent":"築山戸籍住民課長","answer":"それから３つ目として、金融機関等で読み仮名を変えて複数の振り仮名を用いて銀行口座を開設するといった潜脱行為を防止するといった効果があります。そういった効果がありますので、マイナンバーに振り仮名を載せることになったとしても、効果があるものと考えております。","id":"exchange-104"},{"speaker":"塚本委員","kind":"意見","question":"振り仮名を振ることによって、マイナンバーがより一層、正確な運用ができるということにつながるのだということだと思うのですけれども、先々月、１月１９日の総務委員会で、昨年実施されました定額減税についての報告がありました。そしてなぜ全国に比べて、やや……、結構低いかなと思うのですけれども、数字になっているのかというようなことについての見解をお聞かせください。","respondent":"横田デジタル推進課長","answer":"午前中の答弁と少し重なるところなのですが、現在の国のマイナンバーカード保有率が８１.４％で、公金受取口座の登録率が６２.７％ということになりますので、８１.４％掛ける６２.７％ということで、実質的な公金受取口座の登録率は５１％と答弁したところです。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。そういうことだったのですね。デジタル庁が出している、昨年５月の段階では公金口座の登録率が６５.１％となっていましたけれども、６２.７％。一義的には国の仕事と思いますけれども、区としても、いろいろな、ひもづけることに対しての不安などといったものの解消等の啓発なども含めて、しっかり推進していくべきものと思いますけれども、いかがでしょうか。","respondent":"横田デジタル推進課長","answer":"委員がおっしゃるように、今後、給付付き税額控除と併せた検討が進みそうなことから、こうした国の動向を注視しつつ、公金受取口座を登録することによるメリットについて、引き続き丁寧な周知・広報に努めてまいります。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問・要望","question":"時間的には多少かかりますけれども、とにかくマイナンバーカードを使った様々な今後のいろいろな行政の手続が、非常に利便性が高まるということをしっかりと周知していただいて、この活用が進むような品川区になっていくようにと要望いたしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"安藤委員","kind":"質問","question":"税収が見込みより大幅に増えていますけれども、その理由についてそれぞれ伺っていきたいのですが、特別区民税が４７億円余増えましたけれども、理由は納税者の増加、一定の所得以上の納税者の増ということでした。納税者数は何人増えたのか、またなぜ納税者は増加したのか、伺いたいと思います。株式等譲渡所得割交付金も９億円プラスということですけれども、この理由についても伺いたいと思います。","respondent":"宮澤税務課長、加島財政課長","answer":"当初の見込みよりも約４,４００人ほど増加しているというところで、その増加の原因ですけれども、人口増加というのもあろうかと思いますが、もう一つは、午前中の質疑でもありました、譲渡所得等、給与所得以外にも所得があって。株式等譲渡所得割交付金につきましては、新ＮＩＳＡ開始に伴う個人投資家の増加や、株式市場の好調を背景に、株式譲渡等所得割につきまして決算額を上回ったことによる増で。","id":"exchange-108"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。次に、地方消費税の交付金が１０億円増えた理由についても伺います。それと併せて、特別区交付金が４３億６,０００万円増えた理由は、固定資産税、法人住民税の増ということだったと思いますけれども、この固定資産税が増えた理由、法人住民税が増えた理由というのを区としてはどう捉えているのか伺いたいと思います。","respondent":"加島財政課長","answer":"当初予算の見込み段階におきましては、令和７年度の全体フレームの中で、平均のシェア率等を掛けながら予算額を算出していますけれども、実際に新年度が明けまして算定を行いましたところ、２０億円の増加があったです。","id":"exchange-109"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。かなり、やはりお金があるところにはある。それをしっかりと還元していくというのが大事かなと思いました。伺いたいのですけれども、大きく税収が増えたのですが、最終補正に向けて、それぞれの収入増という金額というのは、およそいつ頃、何月頃に大体分かるものなのか、見込みが立つものなのか、伺いたいと思います。","respondent":"加島財政課長","answer":"最終補正の増収要因ですけれども、本当に予算書が出来上がるぎりぎりまで動向を見極めているところです。なので、今回で申し上げれば１月中旬過ぎまでは、歳入の状況というのを見極めておりました。","id":"exchange-110"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。ちなみに基金総額なのですが、昨年度の決算見込額は１,０６４億円ということでした。伺いたいのは、最終補正をかけた結果、現時点での最終的な基金総額見込額は幾らになると想定するか伺いたいのと、また、それぞれの基金、積立ての目標額というのは区は持っているのか、義務教育施設整備基金と公共施設整備基金、あと財政調整基金、それぞれについて、その理由と併せて伺いたいと思います。","respondent":"加島財政課長","answer":"義務教育施設整備資金につきましても同様の考え方で、安定的な活用には、令和６年度決算額と同額の約２５０億円が必要というところで見込んでいるところですが、両基金ともにつきましても、今後の工事費の推移を見ながら、随時検討していく必要があると考えているところです。","id":"exchange-111"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。もう一個だけ。ある程度の時期に税収増が分かるのであれば、見込みより大きく上昇するという税収を、厳しい区民生活などに充てていくと。例えば、午前中の質疑で共産党から求めましたけれども、省エネルギー対策・業務改善設備更新助成は継続実施する、最終補正で組むなど、機動的な対応を求められていると思いますけれども、そちらについてはいかがでしょうか。","respondent":"加島財政課長","answer":"最終補正予算の考え方とも関連してまいりますけれども、最終補正につきましては、予算の執行過程におきまして、創意工夫を凝らして支出の無駄をなくし、必要な事業や財源を振り向けた結果として、歳出歳入の精査を行っているところです。","id":"exchange-112"},{"speaker":"安藤委員","kind":"意見","question":"都内の他の自治体では、最終補正に給付金事業などを盛り込んでいるところもありますので、私は必要に応じて機動的な対応が必要になってくるときもあると思います。最後に態度表明なのですが、今年度の当初予算には共産党として賛成しました。今回の最終補正についても、当初予算と同様の考え方の下で組まれたもので、また減額分も多くは実績見合いなどですので、一般会計の最終予算には賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問","question":"そうするとそれぞれ先を見越して予算編成を組み直すことができているはずですが、ここまで１００億円を超えた歳入増に対して、これはあれですか、見込みがこれだけ違ったということですか。見込みは、もうそこまで増えるということは思わなかったということですか。毎月見ているのに、このような状況になるのですか。教えてください。","respondent":"加島財政課長","answer":"いろいろな増要因につきましては、この間、理事者からご説明を申し上げてきたところですけれども、例えば財政調整で申し上げますと、当初予算の段階では新年度のフレームというのが示されております。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"そういう方針を途中で変換してもいいのではないですか。ゼロにするという期間は違いますし、それから食料品以外のものを対象としているという違いもありましたけれども、多くの国民はこういうことを望んでいるのではないですか。それだけ大変だ。こういう気持ちを品川区として受け止めていないのではないのですか。そこに目を向けない、目を向けていかないというのはどういうわけですか。教えてください。","respondent":"加島財政課長","answer":"ご紹介させていただきたいのですけれども、令和６年度につきましても、国策ではありますけれども、住民税非課税世帯への物価高騰対策支援給付金以外に、均等割の非課税世帯やひとり親世帯も対象として独自に給付というのを実施しております。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問・要望","question":"違うでしょう。毎年、光熱費から食べるもの、そういうことで様々な方が、生活費が８万円から１０万円も上がっているのです。どうしてそういう方たちに目を向けないのですか。自治体というのは、そんなやり方でいいのですか。「一部の人たちが助かればいいではないですか」。そういう方向に、品川区は自治体として区民の皆さんを守るという意識をしっかり持っていただきたいのですが、いかがですか。","respondent":"加島財政課長","answer":"無償化につきましても、高所得者ばかりが得をしているというようなお話もございましたけれども、こちらにつきましては、所得制限なく全ての区民の方を対象に、対象となる区民の方を無償化させていただいているところですので。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"中小企業もそうです。一部の方たちには光熱費、あと運送業にはエネルギー、ガソリン代を支援しているとか、あとお風呂屋でも燃料費を支援する。一部の方に支援は確かに行っているのです。でも、品川区の中では、小規模事業主はたくさんいるのです。そういうところにも私はしっかり目を向けて、公正公平な予算を組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"田中委員","kind":"質問・要望","question":"私は３８ページの特別区交付金、１１１ページ、学校改築推進経費、時間がありましたら５７ページの密集住宅市街地整備促進事業補助金等について、土地購入についてお伺いしたいと思います。角度を変えてお伺いしたいのですが、最終補正で４３億円という高額な金額が入ってきました。できないとしたら、区長会等でしっかり主張していただきたいと思いますが、いかがでしょうか。","respondent":"加島財政課長","answer":"区の財政課の今の考え方といたしましては、補正予算の財源には、財政調整基金を活用させていただきまして、より議会の皆様、区民の皆様に、予算の原資というのが分かりやすくなるように努めているところです。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"そもそも学校改築のことは、平成１２年以降のときには協議の課題に挙がっておりましたけれども、これは特別交付金２００億円を受け取ったから、もうそれで終わりということなのか、あるいはまだ依然として学校改築も、都区間の協議の課題の大きな要素として、特に東京都に認識してもらっているのかというところを確認したいと思います。","respondent":"加島財政課長","answer":"１点目の財源の有効活用というところにつきましては、先ほどのご意見も踏まえまして、例えば今年も年度途中で行わせていただきました物価高騰対策や、今必要な対策と、それから中長期、将来に備えて、いかにどこで財源を使うかというところの理想的なアプローチの中で。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"それは今後の……、そのことは多分、都も品川区の財政事情というか、経費の使い方を見ていると思いますので、そうすると、都区協議の中においては、いや、もう既に使っているのではないのかということで、協議からは少し後ろ向きの、積み立ててはいけないという意味ではないのですが、その辺はうまく対応していただきたいと思うのですけれども、そこは問題ないのでしょうか。確認したいと思います。","respondent":"加島財政課長","answer":"そういう中で一般財源として、現在、義務教育施設整備基金に積立てを行わせていただいておりますが、私どもといたしましては、現在の最終補正予算では、税収増の上ぶれ等を活用して積立てをしていますけれども、きちんとこの先の需要等を見極めながら、適正な積立額。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問","question":"長期間にわたって工事が行われるということとなると、グラウンドが使えない。私がはっきり主張したいのは、しながわ中央公園を、今は一部民間の私立の学校に、ほぼ優先的に使ってもらっていますけれども、こういうときこそ、公立の学校の改築時において、ぜひこちらを最優先して使ってもらうべきだと思います。いかがでしょうか。","respondent":"荒木学校施設担当課長","answer":"ご提案のしながわ中央公園など、ほかの区立の公園なども含めまして、今後、活用できないかどうかといった可能性については検討していきたいと考えております。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"最後、木造住宅密集市街地関係で、不燃化推進特定整備地区内においての土地の購入という視点でお伺いしたいのですが、いわゆる不燃化のための土地購入は、公園整備や道路整備などで必要だと思います。この地区内において出てきた土地は、指定されている区域内ですから、その土地はそのために有効に活用すべきだと私は思っております。これも不燃化の地域内にある土地であります。","respondent":"小川木密整備推進課長","answer":"活用に関しましては防災強化等、もちろん検討の俎上には上がったのですけれども、この場所に関しまして、すぐ北側に二葉公園があります。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問","question":"私はあえて取り上げたのですけれども、５,０００m2以下は議決なく区が財産を取得できるので、逆に言うと土地取得に対しては厳しく議会としてチェックすべきだという思いで質問しています。それで、もしこれが同じ地域内の認知症施設……。そこに、土地取得に対する、まだまだ大きな疑問を感じておりますが、今お答えできる範囲でお願いします。","respondent":"小川木密整備推進課長","answer":"少なくとも、こちらの用地の取得に関しましては、やはり福祉施設を整備するものなのですが、防災性の向上を目的とした施設、機能を有するような施設が求められているといったところでは、防災性の向上に資する施設についても整備するといったところです。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"ページがよく分からないのですが、ＮＰＯ法人の活用等について、まずお聞きします。これは、マスコミ報道では運営に大きな問題があったということですけれども、区の認識をまずお聞きしたいと思います。そして、フローレンスに対して、令和６年度は予算で１億７,４５０万円、令和７年度の予算で１億４０万円、予算がつけられるということなのですが、それらをどう考えて運用するのかをお聞きします。","respondent":"佐藤経理課長、佐藤保育事業担当課長","answer":"区といたしましては、契約の観点からいきますと、いわゆる贈収賄あるいは信用失墜に当たるような違法行為があれば、入札停止処分などといったところを課すわけなのですけれども。同事業につきまして、区内におきまして小規模保育事業所２園と居宅訪問型保育事業を実施していただいておりまして、先ほど委員からご紹介いただいたような事業というのを実施していただいているです。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"すごく緩いですよね。それを、マスコミ等々の報道によれば、「財政の処理の方法などというのがなっていませんでした」ということを言っていて、フローレンス自体は「改善します」とは言っているけれども、そういう会社、そういうＮＰＯ法人に、品川区のいろいろな事業を頼む、依頼するというのはいかがなものかと思いますが、その認識はどうなのでしょうか。なぜフローレンスだけ継続するという形なのですか。","respondent":"佐藤経理課長","answer":"今回につきましては、事実認定を現在、渋谷区で行っていると聞いておりまして、渋谷区の契約途上においても、入札停止等の処分はまだしていないというところですので、そういった事情を注視しまして適正に対応していきたいと考えております。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、そこを調査としてどう対応していくのですか。それで、自治体にも、やはりそこは、何でしょうか、調査というか、ジャッジをするという流れをつくっていかないと、チェック機能が働かないというところがありますので、今後、ＮＰＯ法人もしくは民間を使うときに、どういう考え方で、こういうことが起きないように、こういうことが起きた場合の対処についてどう考えるか、そこを教えてください。","respondent":"佐藤経理課長","answer":"ＮＰＯ法人に限らず、区が入札等で選定した事業者と契約を結んでおりますけれども、そこの実際の運営に関しては、先ほど担当課長がご答弁申し上げたとおり、様々な事業の中で、そこの事業体の適正性を担保していくということをやっておりますので、契約部門としましては。","id":"exchange-126"},{"speaker":"西本委員","kind":"確認","question":"だから、今それが大きな問題になっていて、やはり国も納得しなければいけないという状況なので、品川区もどう対応されるのか、お考えをお聞きします。これで、１１１ページの学校給食食材費がマイナス３,０００万円になっているのですけれども、これは「寄附で賄いました」ということなのかなと理解していますが、寄附で賄えているとすれば、これはいつまで続くのですか。進捗を教えてください。","respondent":"石井学務課長","answer":"現在ですけれども、今年９月から試行実施を始めまして、一つ一つ、学校現場と丁寧に意見交換を重ね、調理の負担の問題など、いろいろな問題を教育委員会と学校現場が互いに協力し合いながら、ここまで進めてきたところです。","id":"exchange-127"},{"speaker":"西本委員","kind":"意見","question":"これは、調理師たちの負担がすごく大変だったと思うのです。なので、私はこれを調べれば調べるほど、「何で学校給食でやらなければならないのだろうか。そこに寄附金があったにせよ、それを子どもたちの食の安全を含めて考えたときに、やるべきではない」と強く思っております。これは別の項目のときに、款別審査のときに言いますけれども、これは見直しを図るようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問","question":"私からは、８３ページ、介護保険特別会計繰出金、１０７ページ、居住支援事業、１７９ページ、介護給付費等準備基金積立金をお伺いしたいと思います。８３ページと１７９ページの介護保険特別会計についてお伺いしたいと思うのですが、この特別会計、介護については国が２分の１、都と区で４分の１ずつ賄って運営していると認識しております。併せて居住支援についてもお伺いしたいと思います。","respondent":"菅野高齢者福祉課長、川原住宅課長","answer":"こちらの今回の補正なのですけれども、会計決算の翌年度に国・都の負担金を計算しまして、金額を確定するための必要な補正となっておりまして。理由として主なものが、入居促進事業の協力金の枠組みの中で、家主がエアコン設置または買い替えをした場合に、入居に対する協力に関する取組というものを、今年度、新たに行ったところですが。","id":"exchange-129"},{"speaker":"こんの委員","kind":"質問・要望","question":"改めて、基金の目的、また基金の仕組み、また給付等の「等」とついている、いわゆるサービスの給付だけではない使い方があるのかなと思うのですけれども、その部分と基金の使途、使い方について、丁寧に教えていただきたいと思います。もっとこうしたことで、より住まいの設備を整えて、借主に貸すことができるかなと思いますので、来年度はその辺のやり方をどうされようと考えているのか教えてください。","respondent":"菅野高齢者福祉課長、川原住宅課長","answer":"こちらは先ほど、積み立てた理由の一つとして、給付費の見込み、当初予算に対する見込みが少なかったことということをお話しさせていただきましたが、介護給付費等の準備基金というのが。引き続き、ＰＲを強化させていただきまして、引き続き認知症対策、また住環境整備の点からも、入居促進事業の周知徹底というところを図ってまいりたいと思います。","id":"exchange-130"},{"speaker":"こんの委員","kind":"質問","question":"介護のほうですけれども、基金の使い道というか、内容を伺いました。そうした計画の下、積み立てているのか。基金はそういう考え方だというお話も先ほどありましたけれども、こういうのは計画上きちんと、何でしょう、先の見通しとして、見込みとして立てていっていらっしゃるものなのか、それとも積めれば積めるほど積んでおこうというようなところなのか、その辺をもう少し伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"３年間の中で、財政の均衡を保つための基金ということになっておりますが、こちらの基金につきましては、将来の保険料上昇抑制のために活用するものでありまして、状況によって、次期の介護保険事業会計の策定において基金を適切に活用したいと考えています。","id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、６９ページ、基金積立金、基金関係でたくさん質問が出ているので、またそれをやりたいと考えていますが、あと１０９ページの義務教育施設整備基金積立金も含めて、基金関係を伺いたいと思います。私は、基金は積極的に増やすべきだという感覚でありますので、そういう視点で質問をしていきたいと考えています。こういうことをやっていただきたいと思うのですが、その考え方を教えていただきたい。","respondent":"加島財政課長","answer":"これらの結果を踏まえますと、令和８年度末の現在高は、財政調整基金につきましては１７１億円、公共施設整備基金につきましては２１２億円、義務教育施設整備基金につきましては１６０億円を見込んでいるところです。","id":"exchange-132"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、それをぜひ踏まえて、１７７億円、使うのであれば、２００億円以上はしっかり増やしていけるように頑張るのだという算段をどういうふうにするのかというお考えがあれば、ぜひ。だから、そういうのをぜひ、そういうところで、経常的経費も増えてきているのであれば、人件費だ何だと増えていくのであれば、それぐらいの感じだと思うのだけれども、考え方をどういうふうにしていくか教えてください。","respondent":"加島財政課長","answer":"現在、令和７年度末の現在高をご紹介いただいたところですけれども、こちらにつきましては、年度内の予算の歳入見込み等を立てながら、必要な金額を、各基金に積立てをさせていただいたところです。","id":"exchange-133"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、出納閉鎖の話をしようと思ったのだけれども、中塚委員の顔がそこに見えたので、やめておくかなと思った。毎回言っていたから。では期待します。１００ページ、木密整備推進費について。だけど、残念ながら減額で、約１４億２,０００万円の減額。これはどういうことがあって、これだけ頑張ってきたけれども、何でこういうふうになってしまったのかというのをまず教えてください。","respondent":"小川木密整備推進課長","answer":"木密整備推進費の補正の減額の件ですけれども、こちらで大きくは、想定しておりました広場や道路の拡幅整備の用地取得ができずに、関係権利者の方々との調整に時間を要していることや、取得の合意に至らなかったといったところで、補正を行わせていただいたところが。","id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうことがあったのだと思っています。それで、私もこれだけは一生懸命見たのだけれども、よく分からない。これは１４億２,０００万円マイナスで頑張っていらっしゃるわけだ。だけど、これからも用地取得も交渉していくわけでしょう。それなのに、令和８年の予算は１４億マイナスなのです。実績見合いみたいなものなのです。それは、頑張らないということか。その辺の感覚を教えていただきたい。","respondent":"小川木密整備推進課長、加島財政課長","answer":"ただ、我々としましても、しっかりと密集事業というものに取り組まなくてはといったところで考えてありますので、しっかり思いを持って事業に当たっていきたいといったところで考えてあります。こちら、数字だけを比較したときに、委員から見れば少しご不安を与えてしまったかもしれませんが、木密整備推進課でもただいま申し上げましたとおり、きちんと計画に基づいて事業を進捗させていくというところにつきましては。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"確認","question":"６６ページの特別区債についてお尋ねします。令和７年度の当初予算では、学校施設整備のために２３億円の起債を予定しておりました。それが最終補正で０になりました。令和７年度は義務教育施設整備基金から５８億円を繰り入れています。先ほどの議論にもありました。これの確認、この数字でいいのかということと、あと起債をこのように計上していただきましたけれども、行わなかった理由をお願いします。","respondent":"加島財政課長","answer":"２つ目につきましては、学校改築については、施設の老朽化等の状況も踏まえますと、今後、毎年１００億円程度の経費を要すると見込んでおりまして、将来の負担の平準化という起債の趣旨に沿わないことから、起債分につきましては。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問","question":"その中の、基準財政需要額内の投資的経費、第７項教育費、第１・第２項、単位一口算定の概要についての説明文がありました。中学校も同じです。「小学校及び義務教育学校（前期課程）の義務教育施設の改築（雨水有効利用設備を含む）・大規模改修・長寿命化改修及び元利償還金に要する経費」という表現があるのですが、この表現はどういうことを意味しているのでしょうか。","respondent":"加島財政課長","answer":"今ご覧になっている資料と同じものを手元に持っておりませんので、説明が食い違うかもしれませんが、小・中学校・義務教育標準区を設定している中で、学校校舎の長寿命化を図っていく。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問","question":"つまり、基準財政需要額を算定する部分が、今お話ししたように、改築、そして大規模改修、長寿命化改修および元利償還金に要する経費というのがあるのです。ということは、起債を発行してもしなくても算定されるという受け取りでよろしいでしょうか。ということは、令和７年度はこれについて経費が算定されたと考えていいのでしょうか。用途によって違うかもしれませんが、その２点をお願いします。","respondent":"加島財政課長","answer":"改築の部分の経費につきまして、財政調整算定でどれぐらいの交付がされたのかですけれども、基準財政需要額と基準財政収入額の差額分が、普通交付金として交付されますので、その中で学校改築分が幾らかというのは、算定が難しい、抜き出すのが、抽出が難しいです。","id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"確認","question":"ということは、起債されるか否かにかかわらず、学校改築に関しては、いろいろ細かい話がありましたけれども、財政調整の算定に入ってくるということで確認させていただいてよろしいですか。もう一回、すみません。","respondent":"加島財政課長","answer":"起債をしたか、しないかで、財政調整算定の学校改築分の主要な算定に影響があるか、ないかといえば、ございません。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"新庁舎の起債は、トータルでいうと６０％ぐらい起債するという感じですけれども、予算書にありますように、学校改築は令和７年度・８年度もゼロなのです。令和８年度もゼロなのですけれども、そこのところを少し確認していただきたい。ということは、両方とも非常に長期の試算なのだけれども、起債活用の基準というのは、事業ごとなのですか。そこのところをお願いします。","respondent":"加島財政課長","answer":"起債をするかしないかということにつきましては、先ほど申し上げたとおり、近隣の調査状況から、利上げが継続されそうであるということを踏まえての判断で、それから学校改築経費につきましては、令和８年度予算では１００億円となっておりますが、今後も同程度の金額。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"１００億円以上かかるとして、それで起債ゼロというところが、どうしても私は理解できないのです。将来の区民の方に関する平準化という側面からも、今年、今いる区民の方に２００億円、お支払いさせるわけですよね。それを、起債を、１００％とは言いませんけれども、そういったことについての判断について、検討過程については、何らかの文書の中で、あるいは会議の中で記録されたりしているのでしょうか。","respondent":"加島財政課長","answer":"学校改築につきましても、これまでは教育機能や避難所機能を担う、区民が幅広く利用する施設というところも踏まえまして、平準化という観点から起債を行っていたところですけれども、学校改築経費につきまして、先ほども申し上げたとおり。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"私は、やみくもに起債を増やすべきだと申し上げているわけではなく、一方で起債の重要性を認識しています。それを、基本的な整理をしておく。今回、均等、そのほかに１００億円という話が出てきましたが、現在の区民だけではなくて、将来その施設を利用する世代、言い換えればまだ生まれていない区民の方々の負担のあり方も丁寧に考えていく必要があるのではないかと感じております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"松本委員","kind":"確認","question":"その前に、今の基金や起債の流れで、私も確認しておきたいなと。私は逆に腑に落ちた部分もあって、学校の改築の起債をするかどうかというところで、起債せずにやるというところは、これはもう毎年、恐らく１００億円程度、今後かかっていくから、だったら起債でやるのではなくて、毎年交付を組んでいくという形で考えられるという理解でよろしかったでしょうか。","respondent":"加島財政課長","answer":"少し仮定の話も入ってまいりますけれども、今後、毎年１００億円程度、学校改築推進経費が発生するのであれば、それは恒常的な経費と区では受け止めておりますので、特定財源等を活用しながら、一般財源として対応することで、十分、財政の手当てができると考えております。","id":"exchange-143"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。これは、これまで私はこの問題を何回か伺ったかもしれませんけれども、従来は協議の段階にあるということで計上されていなかったのが、今回この流れを見ると、国と都と新庁舎の負担の合意ができたのかなと思うのですが、その理解でよろしいのかと、交渉の経過、新庁舎整備に係る国や都の負担の内容をお伺いできたらと思います。お願いします。","respondent":"小林新庁舎建設担当課長","answer":"新庁舎ですが、令和７年２月末に実施設計が取りまとまりまして、その後、国、それから都、それから区が使用する会議等の協議、具体の協議が進んだところから、それぞれの負担割合に応じた負担金の補正予算を今回、計上するところです。","id":"exchange-144"},{"speaker":"松本委員","kind":"確認","question":"要はエレベーターなどだと思うのですけれども、これも専用部分の割合によって、その負担割合を適用したという理解でいいのかというところを、確認のため伺います。その際に、今、割合で、パーセンテージで協議していただいておりますので、これは建設費用が仮に上がった場合には、そのままパーセンテージとして、都と国にも負担していただけるという理解でいいか、伺います。","respondent":"小林新庁舎建設担当課長","answer":"２点目の単価等のアップに伴います工事費のいわゆる変動等ですが、これにつきましても当然、区分所有者であります国・都が応分の負担をするということで協議を進めてありますので、昨今、やはり建設物価が上がったり、あるいは設計労務単価等も上がっているところですので。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"そこの部分は、区の負担がどうなるかというところで大事なところだと思いますので、引き続き、よろしくお願いいたします。これは、商店街活性化推進事業の中に、もともと助成の項目としてあったものが、助成の申請がありそうな年には上がって、特に申請がなさそうだというときには予算書の中に上がってこないという理解でよろしいのか伺います。","respondent":"小林地域産業振興課長","answer":"ご質問の点につきましては、まさにそのとおりでございまして、我々、毎年度、商店街から、翌年度以降、どういう事業が必要になるかという、それはハード・ソフトを含めてですけれども、両方お聞きしながら予算に組み込んでいくような形にしております。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問","question":"アーケード、これは先ほども火事の話がありました。あるいは、そもそもこれはちょっと古そうですから、商店街のほうでも考えていただきましたら、いろいろ区としてもアドバイスをすることができるのですみたいなところの話をするのかと考えたときに、やはり今、商店街と関係がある地域産業振興課が働きかけるというのが大事になろうかと思うのですが、この辺はいかがでしょうか。","respondent":"小林地域産業振興課長","answer":"ただいまご指摘のようなアーケードの部分、あるいはイベント支援も含めて、バックアップしながらハードのほうも問題がないように運営していければと考えています。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"これはもう本当に、地震が起こる可能性というのはかなり高いので、ぜひとも積極的にお願いいたします。本日の利子割交付金などについては、先ほど基金の話が延びてしまったので、また明日、伺えればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結局これだけたくさん基金がたまったわけですから、これは当然、第１０期、これからの計画をするわけですけれども、介護保険料引下げに使うということになってくると思うのですけれども、大体１００円引き下げるのに３億円が必要だということですので、見込額からすると８００円ぐらいは、１人当たり平均で、基準額で引き下げられるのではないかと思っているのですが、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そういった状況の中で、来期についてはどうかというところなのですが、やはり今の国の審議会でも見直しの意見が出て、今後夏までに指針が出てくると思いますので、そういった国の指針に基づいて、区として計画をつくりながら、その計画をするために。","id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問・要望","question":"こういうところに対しても加算をつけるなど、ぜひとも、さらなる支援をお願いしたいと思いますけれども、いかがでしょうかと伺いたいと思います。国民健康保険の滞納者に対する差押えについて、この５年間の件数を教えていただきたいと思います。差押えというのは、やはり払える能力があるのに払わないという人に、もう悪質な滞納者に対してということで限定して行うべきだと考えますが、いかがでしょうか。","respondent":"菅野高齢者福祉課長、山下国保医療年金課長","answer":"物価高騰等の中で、事業者も大変苦しい状況だとも、区としても認識しているところです。アンケート等を取るなど、介護サービス事業者がしっかりと介護サービスを提供できるような体制を整えてまいりたいと考えています。職員の努力と、そういった事務の効率化のところで、差押えの件数が結果として伸びているというところがございまして、制度の運営に当たりましては、国民健康保険制度の適正な運営に際しまして。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"失業や傷病などで生活困窮に陥っている場合、差押えがどれほど本人を追い詰めることになるかというのを考えていただきたいのです。最後に態度を述べたいと思います。後期高齢者医療保険についても、２０２４年から過去最大の値上げをしたものに加えて、２割負担の本格実施や出産育児支援金の増額など、さらなる負担増になっているものであり、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"若林委員","kind":"質問・要望","question":"どんどん減額の理由を確認させていただきたいと思います。８７ページの児童・子育て応援関係の各種手当事業も減額になっておりますので、この理由を確認させていただきたいと思います。品川区では毎年、事務事業評価等今やっておりますけれども、こういった事業評価というのはどういう形でやっておられるのかというのを教えていただきたいと思います。執行状況を見た上での事後評価をお聞きしたい。","respondent":"柏木子育て応援課長、五十嵐保健予防課長、菅野高齢者福祉課長、加島財政課長、崎村企画課長","answer":"こちら、令和６年度の予算では、制度改正に伴う予算編成を行いましたが、改正内容の高校生年代につきましては、公務員世帯の人数。私からは、帯状疱疹ワクチンの減額の理由につきまして説明します。こちらにつきましては、実績見合いでの減額となっているものです。多くの今までのたくさんの卒業生が輩出されて、今、介護事業所でそれぞれ活躍しているというところを見ると、大変有意義な専門学校で。","id":"exchange-152"},{"speaker":"若林委員","kind":"質問・要望","question":"ウェルビーイング２.０で組まれた予算がこの補正に載ってこないということは、順調に執行されていると逆に理解しますし、そういう意味では、中間の報告としては十分に評価されているのではないかと思います。一方で、減額も実績見合い等で、ただ帯状疱疹ワクチンは実績ということで、また来年度、頑張っていただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"藤原委員","kind":"質問","question":"９６ページ、清掃費、８３ページ、品川区介護職員居住支援手当、１０１ページ、都市計画道路整備方針検討業務委託についてお伺いします。清掃についてお伺いします。私は、品川区廃棄物減量等推進審議会に入っております。実はこの間、会長のご発言で、感動した言葉がありました。そのとき思いました。私たちは平成１１年に初当選したのですけれども、それが１９９９年でした。","respondent":"篠田品川区清掃事務所長","answer":"清掃事業というのはもともと東京都が担っていたところ、平成１２年の時点から、特別区において収集運搬等を担うことになったということで、こちらに関しては地元に密着した形で、責任を負う形で、きちんとこれまで目指したとおり進められてきていると認識しています。","id":"exchange-154"},{"speaker":"藤原委員","kind":"意見","question":"そうですよね。各戸収集をしたり、本当に区民に対して手厚くしていると思っているのですが、その中でニュースを見ました。東京都知事、小池百合子知事が言いましたね。清掃は有料化します。したいと思っていますと。私は思いました。何を言っちゃっているのか。清掃は各自治体に移管されてきたのですよね。所長、これは率直にどう思いましたか。ぜひ意見を聞かせてください。","respondent":"篠田品川区清掃事務所長","answer":"ただ、記者会見をよく見ていると、知事も一言、「特別区によって決めることではあるのですけれども」と添えていらっしゃったので、一応、認識はお持ちなのかなとは思っているところです。","id":"exchange-155"},{"speaker":"藤原委員","kind":"質問・要望","question":"「特別区で決めることなのですが」と言うならば、特別区でやっているのですから、一言言わなければいいのです。私はそう思っておりますので、このことはしっかり区長会においても主張していっていただきたいと思いますので、まずよろしくお願いいたします。次は介護職員についてお伺いします。この減額なのですけれども、これについても、これだけの金額を減額していて、どうしてという思いがありました。","respondent":"菅野高齢者福祉課長","answer":"それと同時に今年度は、訪問介護事業者につきましては基本報酬が引き下がったというところで、その部分についての給付金もさせていただきまして、事業所への支援とともに、従事者の収入アップも併せて支援するというようなところをしていますので、本当に最後は、お正月、三が日。","id":"exchange-156"},{"speaker":"藤原委員","kind":"質問","question":"これはじっくり民生費でも伺います。そして、同僚議員から久しぶりに、利用者から頂いた手紙を何で言わないのだと言われたので、それをまた読みながらやっていきたいと考えています。次に都市計画道路なのですけれども、これはマイナスになっていますが、マイナスの理由を教えてください。","respondent":"高梨都市計画課長","answer":"都市計画道路の整備方針の検討に係る委託経費の減額についてですが、こちらは契約落差による減額です。","id":"exchange-157"},{"speaker":"藤原委員","kind":"確認","question":"これは具体的に出してくれると思ったのですけれども、基本的には西大井のところですよね。「西大井等」でもいいですけれども、その辺を確認させてください。","respondent":"高梨都市計画課長","answer":"今年度行った都市計画道路の検討につきましては、西大井の補助２０５号線を含む、区内の未整備の都市計画道路について、その必要性等々について検討したもので、減額分については、その委託について契約させていただいたところ、当初予算との落差がありましたもので。","id":"exchange-158"},{"speaker":"藤原委員","kind":"質問","question":"課長、安心しました。補助２０５号線をはじめ、きちんと調査して、続けてください。あそこは大事な道ですから。補助２０５号線も含めて、これから西大井が変わるのです。それで、補助２０５号線もまだ途中ではないですか。心から、そう思っているのです。そういう思いで伺っているのですけれども、これだけ、ぱっと見たときに、あれ、もうこれは外されてしまって、やらないのかという思いがすごくあったので。","respondent":"高梨都市計画課長","answer":"しかしながら、区といたしましては、補助２０５号線の整備と原踏切の除却は、将来的には必要な事業であると認識していますので、今後も、周辺のまちづくりの状況や地域の皆様のご意見を聞きながら注視してまいりたいと、このように考えているところです。","id":"exchange-159"},{"speaker":"藤原委員","kind":"質問・要望","question":"それでしたら、最初からそういうふうに答えてください。やはり私は強い思いがあるのです。将来的に必要なのではないのです。今、必要なのです。これが、西大井に住んでいる方たちの悲願なのです。だから私はずっと、西大井のことに関して聞いてきました。要望してきました。今日はこれで終わりますが、よく覚えておいてください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-160"},{"speaker":"せお委員","kind":"質問","question":"本日最後になりました。１０５ページ、Ｐａｒｋ－ＰＦＩの導入、時間があれば６５ページ、児童相談所設置区における措置費共同経理課負担金についてお伺いします。改めて公園管理という部分が、どの部分を今回の事業者が行うのかということと、「東品川海上公園＜Harbor of Harmony＞共同企業体」となっていますけれども、共同で行うという意義をどう考えているか、お聞かせください。","respondent":"大友公園課長","answer":"Ｐａｒｋ－ＰＦＩの制度なのですけれども、事業者が設置する施設から得られる収益を還元して、公園施設の整備・運営・維持管理をする制度です。","id":"exchange-161"},{"speaker":"せお委員","kind":"質問・要望","question":"これも午前中にご答弁がありましたけれども、私からも、ゾーニングを行うなど配慮していただいて、公共の場という観点で進めていただきたいと要望しておきます。さらには、マナーを守れない人が一定数、来てしまうことも考えられます。そこで、ドッグランにおいてマナーを守れない人が出てきた際や、そして続いてしまったというときに、現時点でどのように対応するのか、分かれば教えてください。","respondent":"大友公園課長","answer":"にぎわいが創出されるということはよいことと考えているのですけれども、ご指摘のとおり、仮に混雑するような状況が発生する場合、特にドッグランなどでこのような状況が発生した場合等については、施設の利用時間の見直しや、利用時のマナー啓発。","id":"exchange-162"},{"speaker":"せお委員","kind":"質問・要望","question":"そこは意見だけ聞きたいと思います。トイレもですかね。こちらの自販機、ごみ箱、トイレなどのアートについて、現在検討している方法、そして区民の障害者アートの利用、今の話ですけれども、そういったところについて見解を伺います。質問は、今回のＰＦＩの事業においては、障害者が働ける場所というのはあるのかということと、あと、区全体の仕組みをつくることに関して見解を伺いたいと思います。","respondent":"大友公園課長","answer":"続きまして、ＰＦＩ事業での障害者雇用の取組をどう考えているかという点につきましてなのですけれども、こちらは、障害者雇用を事業者公募の条件とはしてしないところではありますけれども、事業者の選定のあたりから、障害者雇用について事業者に確認しておりまして。","id":"exchange-163"},{"speaker":"せお委員","kind":"質問・要望","question":"本当は公募のところで要件に入れていただきたかったというのは、私としては思うのですけれども、そういったところもぜひ進めていただきたい。最後にどこが答弁するか分からないですけれども、全庁的にそういったところで、「こういうところがある」という話合いが、情報共有できるような場所みたいなところがつくれればうれしいと思うのですが、ぜひご見解を伺えれば。","respondent":"大友公園課長","answer":"今回のＰａｒｋ－ＰＦＩの障害者雇用もそうですけれども、公園課でも水族館は超短時間雇用等々を実施しています。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/361190?Template=document&Id=7379#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":123094,"voices":373}},{"id":"r08-20260304-3","meetingId":"r08-yosan","date":"2026年3月4日","dateIso":"2026-03-04","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を145件抜き出しています。","topics":[{"id":"topic-01","title":"令和８年度品川区一般会計予算","agenda":"令和８年度品川区一般会計予算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"おはようあります。本日も１日よろしくお願いいたします。私からは、８３ページ、廃棄物処理手数料についてお伺いします。令和７年度品川区一般廃棄物処理実施計画についてご説明ください。","respondent":"篠田品川区清掃事務所長","answer":"廃棄物処理計画についてです。こちらにつきましては、令和４年度に策定いたしまして、この先１０年間の品川区における廃棄物処理に関する計画を立てております。","id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"私も確認させていただきましたが、環境教育として様々取組が記載されており、小学生ごみ減量・リサイクルポスター展、スケルトン車両による環境学習、ごみ・資源追っかけ隊等、様々実施が記載されております。その際に回収したキャップは、先月の２月に行われたエコカップキッズフェスティバルのノベルティのカラビナにアップサイクルされているとのことで、視察にも伺いました。","respondent":"篠田品川区清掃事務所長","answer":"区内のイベントへの参加につきましては、昨年度から清掃事務所として取組を始めまして、今年度につきましては、区によるイベントや、区内の企業のイベント等、あるいは町会の防災訓練ですとかお祭り、そういったものに参加させていただきまして、この後。","id":"exchange-002"},{"speaker":"えのした委員","kind":"提案","question":"町会ですとかお祭り、そして幼稚園・保育園は４４回、小学校は４回ですか、かなり回数も多く、地域にこちらから伺う形で取り組まれている。そこで提案します。はスケルトン収集車から申請するのはいかがでしょうか。令和７年度の予算特別委員会でも、私から質問させていただきましたが、会派の要望から、トイレトラックのナンバーは、寄附額の１,４２３万円、「品川８３０さ１４２３」となっております。","respondent":"篠田品川区清掃事務所長","answer":"初めに、ご提案いただいたナンバーの件です。今走っている車のナンバーの取替えということになりますので、若干検討する必要はあるかと思いますけれども、なかなか面白いご提案として受け止めします。それから、シティランにおける紙コップのリサイクルです。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問","question":"夏のリサイクルの実証実験の集大成、私も大変期待しております。先日、東京マラソンも視察をしてきました。世界６大大会の１つでもある東京マラソン。そして、これ、案内の中に、４体のキャラクターが出てきていたのですけれども、いつも象キャラクターがいるのですが、いくら探しても名前が出てこなくて、こちらは名前とかがあれば教えていただけますか。","respondent":"篠田品川区清掃事務所長","answer":"リサイクルするぞうということで「するぞうくん」といいます。そのほかのキャラクターは、今回、シティランに合わせて、動物のキャラクターをつくったもので、特に名前はないです。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、歳入全般と、５０ページの特別区民税、それから１５８ページのふるさと納税寄附金について伺います。歳入全般、特別区民税について伺います。特別区民税は６１９億円と前年度比５９億円、約１０％伸びております。特別区債の起債６５億円をゼロとしているなどの要因ですけれども、歳入増が１％にとどまった要素、前年に対して減額要素をお教えください。","respondent":"宮澤税務課長、加島財政課長","answer":"所得の増加というところで、特に合計所得１,０００万円以上の方の所得層が非常に伸びているです。もう１つにつきましては、株式の譲渡益または配当所得といった譲渡所得に係る税収の部分も一貫して増加しているという傾向にあります。ただ、その一方で、国庫支出金につきましては、児童手当給付金、防災安全交付金等の減によりまして、約３８億円の減となっているほか、冒頭でご説明申し上げた環境性能割の廃止等によりまして。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問","question":"ここの見方をどう考えるかは非常に分析が必要ですけれども、特別区民税６２億円と財調交付金で４０億円で約１００億円増えているものの、それ以外がマイナスで、結果として歳入は１％程度の伸びにとどまっているというところなのかなと思います。関連して、歳出における財政の予算編成に対する考え方についてお伺いしたいと思います。お願いします。","respondent":"加島財政課長","answer":"物価高における予算編成上での認識につきましては、確かに物価高の影響を受けまして、物件費等に影響が出ているのかと推測するところではありますが、１件１件の物価高騰影響の集計は持ち合わせておりません。","id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"理解が深まりました。議員としても把握しにくいですし、その先にいる区民の方々にお伝えするということも難しいのかなという、分かってもらうのは大変なのかなと思いますので、この辺りを時系列でどういうふうに示していくのかということが非常に大事なことだと思いますので、分かりやすく伝えていくということも、引き続き要望してまいります。少し限られた時間ですけれども、区のご意見を伺えれば幸いです。","respondent":"宮澤税務課長","answer":"寄附、恐らく返礼品を伴わない一般的な寄附のことかと思います。特設サイトを今年度開設しましたので、そういったところも活用しながら、簡単に受入れができるような仕組みを考えていきたいと考えております。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、１７７ページの環境政策加速化事業補助金に関連して、「ゼロカーボンシティしながわ」の実現に向けた省エネ・省資源の推進についてお伺いします。環境政策加速化事業補助金は、どういったものに活用されるのかお聞きしたいと思います。","respondent":"中西環境課長","answer":"こちらに関しましては、まず環境課の事業で申し上げますと、ＺＥＢの普及事業、それから、しながわゼロカーボンアクション助成の宅配ボックスの助成事業ですとか、あとはマイボトルの給水機の設置事業、それから、住宅課の事業で申し上げますと。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。では、こちらに関連して、まず、令和７年度のしながわゼロカーボンアクション助成についてお伺いします。現場の声として、この助成の需要の高さを感じています。今年度のように需要が想定を上回った場合、来年度はどのように対応するのかお伺いします。さらに、今年度の申請状況を踏まえ、来年度はどのように見直していくのか伺います。区の見解を伺います。","respondent":"中西環境課長","answer":"来年度も一応１００件分の予算を見込んですが、今後のニーズですとか、また、ペロブスカイト太陽電池のような太陽光発電の技術等の進展もありますので、そういうことを含めながら件数等は精査してまいりたいと存じます。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ぜひ前向きに柔軟に進めていただければと思います。令和７年度から、このしながわゼロカーボンアクション助成は、制度が一元化されて、パンフレットの整理や電子申請の導入が進められました。これらの取組は区民にとっても非常に分かりやすい取組だと受け止めております。そこで、この点について、要望するとともに区の見解を伺います。","respondent":"中西環境課長","answer":"ただ、前回も委員からご指摘を頂戴しておりますし、また、職員から、例えばホームページですとか、例えば窓口にご申請、お問合せをいただいた際とか、そういったときに何か伝えることができないかですとか、なかなか個々別々に全てをご紹介することは難しいところがありますが。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ検討していただければと思います。続きまして、来年度のエコルとごしの屋外への紙製人工芝、いわゆるペーパーターフの導入について伺います。先日、エコルとごしの利用者、職員の方々から、現場のお声を伺いました。検証結果を見える化して、エコルとごしの環境学習をさらに発展させていくべきと考えますが、この点について、区の考えをお聞きします。","respondent":"中西環境課長","answer":"例えば、コミュニティラウンジへ展示をするなど、比較ができるような展示ができないかといったことを指定管理者とも連携しながら検討してまいりたいと存じます。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ進めていただければと思います。最後に、中小企業向けに現在実施しているＡＩ電気相談所についてお聞きします。この実証実験は２月末で終了していますが、環境課として把握している範囲で、相談件数、利用件数などをお聞きできればと思います。","respondent":"中西環境課長","answer":"ＡＩ電気相談所は、しながわシティラボでの実証実験ですが、アカウント登録をいただいた会社が５社、それから、実際に再エネ電力への切替えに至った会社が１社となっています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"提案","question":"この取組は、しながわシティラボにおいて、提案、締結された実証実験であることは認知しておりますが、以前の建設委員会の場において、課長から、実証を進めながら家庭向けへの応用の可能性についても相談していくと答弁がありました。","respondent":"中西環境課長","answer":"今後、今回の実証実験の報告等を業者から受ける予定になってあります。年度内の意見交換を踏まえまして、また業者のほうから提案があれば、実証実験等も前向きに検討してまいりたいと存じます。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"中小企業センターですが、大会議室とレクリエーションホールのマイクの集音性能について、昨年の予算特別委員会で改善を要望したのですが、最近、よくなったと感じているのですけれども、あれから改修など対応していただいたのでしょうか、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"今後とも利用者の皆さんに気持ちよく使っていただけるように、センターに寄せられたご意見などを丁寧に拾いながら、施設、設備の利便性向上、改善に努めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"安藤委員","kind":"確認","question":"ありがとうございました。やはり利用者の声を届けるというのは大切だなと再確認いたしました。次に、１１１ページ、自衛官等募集事務費に関連して、子どもへの自衛隊ＰＲについて伺います。自衛隊員への応募数は、年々減少しておりまして、定員に対する欠員状態が続いていると。過去にもこういうことは行われていたのか、行われていたのなら、いつから何校で行われていたのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"内容といたしましては、自衛隊の仕事の内容を聞き取るですとか、実際の訓練の様子を見学するといったようなことがありました。昨年度も同じ学校で、同じ学年、８年生の職場体験があったと把握しております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"具体的な訓練も見学ということでした。これ、なぜそのようなことが行われることになったのかの経緯を伺いたいというのが１つと、併せて、教育の内容については政治は介入しないということが原則なのですが、まだ判断能力が十分に備わっていない子どもの頃からの体験をさせる、宣伝するということは問題だと思います。それだけに、私は、なおさらどうかと思います。","respondent":"丸谷教育総合支援センター長","answer":"決して、その職種の宣伝行為や募集というような趣旨ではございませんので、自衛隊だから体験先としてふさわしくないということではなくて、体験内容によって判断すべきと考えております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"関連して、２点伺います。３月１１日に近い土曜日には、このところ、毎年、自衛隊防災フェアが行われてきましたが、共産党は中止を求めてきました。今年は開催されたのでしょうか。既に開催されたとしたら、どのような内容だったのか伺います。もう１つ伺うのですが、品川区教育委員会は、子ども向けの「防衛白書」の扱いをどのようにしているのでしょうか、伺いたいと思います。","respondent":"大友公園課長、丸谷教育総合支援センター長","answer":"前段の自衛隊防災フェアの部分についてお答えします。この自衛隊防災フェアですけれども、今年も１月２５日の日曜日に実施されているところです。区立学校に確認をしたところ、この子ども版の「防衛白書」が届いているという学校はございませんでした。そのため、本区においては学校には配られていないということで認識をしております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年も中止を求めましたけれども、ＶＲ体験も戦車に乗って被災地に赴くみたいな、そういうＶＲ体験だったのです。そういった問題。１点伺いたいのですが、コミュニティバス大崎ルートの先のほうには、上大崎地域があるのです。伺いたいのは、やはり様々な運行上の課題を区民と一緒に解決し、コミュニティバス大崎ルートの運行で、上大崎地域のニーズもカバーすべきだと思うのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"今後、様々、区内全体の交通計画を立てていく中で、どのような解決が図れるのか研究検討するところだと認識しております。区民と一緒にというお話も、地域の方々、計画をつくる中で様々ご意見を伺いながら進めていければと考えています。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に、シルバーパス購入費補助なのですけれども、代表質問では、荒川区のように、シルバーパスを全ての対象者が１,０００円で購入できるよう、区として助成するよう求めましたけれども、区の答弁は、東京都の動向を注視していくということだったと思います。","respondent":"樫村高齢者地域支援課長","answer":"引き続き、東京都の動向を注視しながら、区としても、東京都の動向を踏まえて検討をしてまいりたいと考えています。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"本日は、８３ページの廃棄物処理手数料、１０５ページの橋梁改修事業について質問していきます。廃棄物処理手数料については、粗大ごみや運行管理システム、次年度の予算に入っているものについてお聞きしていきます。それには、手数料の増額ということもあったかと思いますが、粗大ごみの量の推移、傾向をお聞きしたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"粗大ごみの手数料の推移等についてのご質問です。令和８年度の予算に関しましては、令和７年度の粗大ごみの実績等を踏まえまして、同額程度を見込んでいるものです。ただ、粗大ごみ自体は若干増えてきております。","id":"exchange-020"},{"speaker":"せらく委員","kind":"確認","question":"粗大ごみ自体は増えているということでした。どのような過程を経て、このような事業に対する予算になったのでしょうか。粗大ごみの収集にも活用するのかという点と、この事業によって、区民が収集状況をリアルタイムで確認できることで、具体的にどのようなメリットがあると想定しているか教えてください。","respondent":"篠田品川区清掃事務所長","answer":"そちらのほうもうまく図れるような形でやっていきたいと思っているのですけれども、新しい業者については、新年度に入ってから選定をするということになってありますので、その辺は、今、検討の最中です。","id":"exchange-021"},{"speaker":"せらく委員","kind":"確認","question":"業務の効率化という視点から質問します。これはどのような仕組みになっているか、毎週の収集のある程度決まった、いわゆる既存のコースが、さらに効率化をすることを想定しているのでしょうか。粗大ごみも別のシステムということだったのですけれども、粗大ごみのほうも、このようなリアルタイムで確認できるようなシステムを検討しているのか、改めて、すみません、教えてください。","respondent":"篠田品川区清掃事務所長","answer":"こちらに関しまして、１つは、現在も、例えば、道路渋滞等で、ある地域の収集が進んでいないということがあれば、ほかのものを応援に行かせているのですけれども、電話でのやり取りでということになりますので、なかなかうまくいかないところを。","id":"exchange-022"},{"speaker":"せらく委員","kind":"確認","question":"粗大ごみは廃棄物手数料を徴収して回収されていますが、その中には、まだ使えるのにもったいないと思いながら出しているという区民の声を最近もお聞きしました。循環を促して、よりリユースを促進するために、今回、ごみ収集車の情報をリアルタイムで公開するシステムを活用して、粗大ごみのほうも、リユースにつながるような粗大ごみの引取りという形を検討するべきだと考えますが、いかがでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"粗大ごみ全体のリユースとしましては、持込分以外にも、収集したものを、自転車などに関しましてはリユースをかけているといったことがありますので、全般にわたりまして幅広くリユースできるように、今後も検討する姿勢を続けてまいりたいと考えているところです。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"いつも本当にありがとうあります。なお、こちらの質問の趣旨は、一括して連携しますというご説明を求めるものではなく、例えば、０歳児見守り・子育てサポート事業をスタートしたことにより、どういった課題が見えてきて、どのように子ども虐待予防の施策に反映されているのでしょうかといった部分をお聞きしたいといった意図を持って、お聞きしております。どのような予防策が共有されていますでしょうか。","respondent":"長谷川児童相談課長、吉野子ども家庭支援センター長、石橋品川保健センター所長、丸谷教育総合支援センター長、木村人権・ジェンダー平等推進課長","answer":"ただ、複合的に様々な課題が絡み合っているところですので、すぐにこれをやったら解決というところが難しい状況ではありますけれども。この対応としまして、令和７年４月より、３つの保健センター内に地域子ども家庭支援センターを開設しました。必要に応じて保健センターにおいて保健師が、支援が必要な家庭においては、支援に即座に入る相談をする、電話をするなどの対応を実施して。学校の役割についてです。学校は、日々登校してくる児童生徒を見取るという大変大きな役割を担っているという認識です。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"各課で様々な施策を、新しいものであったり、今まで歴史のあるような子育て支援であったり、様々行っていただいているのですけれども、今、児童相談所ができて少したったというタイミングなので、ぜひそれらを取りまとめていただいて、子ども家庭支援センターのほうで、これから５年後、１０年後、どのようにしていくのかという。","respondent":"吉野子ども家庭支援センター長","answer":"委員のご指摘のとおりでして、関係機関だけでなくて、地域の団体であったりとかＮＰＯ法人も含めた大きな連携をしまして、地域のネットワークの構築を図ってまいりたいと思います。","id":"exchange-025"},{"speaker":"澤田委員","kind":"質問","question":"私からは、９１ページ、児童入所施設措置費等についてお伺いいたします。現在、２０室ありますが、稼働率、また、ここ数年で利用されている世帯数を教えていただければと思います。","respondent":"吉野子ども家庭支援センター長","answer":"ひまわり荘の利用ですが、入退所等の変動はあるのですけれども、令和６年度は９世帯、令和７年度の１２月末現在では１１世帯となっておりまして、例年１０世帯ほどの利用となっております。","id":"exchange-026"},{"speaker":"澤田委員","kind":"質問・要望","question":"毎年大体１０世帯くらいというところで、半分ぐらい、半分強なのかなと。関連してですけれども、同施設内にある子どもショートステイの１日の受入れ人数は５名ですけれども、こちらでは満員になることがどれくらいあるのか、把握されていれば教えていただきたいということと、平日や土日の利用率、もしくは、大体でもいいので、何割ぐらい利用されているのか等をお聞かせください。","respondent":"吉野子ども家庭支援センター長","answer":"ほかの曜日になりますと、３０件ほどになっております。それから、年間に利用する年齢層ですけれども、令和７年度現在、小学校５年生以上と中学生の利用がなく、主に就学前のお子さんが多くなっている現状です。","id":"exchange-027"},{"speaker":"澤田委員","kind":"質問・要望","question":"利用率は大体３０％ということと、あと、小学校５、６年生、中学生の利用は今のところないというところで、小さいお子さんが多いのだなということが分かりました。続いて、１つ確認させていただきたいのですが、ひまわり荘に入居されている方のケアをする職員と同じ施設なので、同施設にある子どもショートステイの職員は兼務してお子さんたちに対応されているのでしょうか。","respondent":"吉野子ども家庭支援センター長","answer":"ショートステイ等の事業と、ひまわり荘の職員ですけれども、子ども支援員で、専門的な知見に基づいて、それぞれ別々に配置されている状況にあります。","id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"子どもショートステイなのですけれども、現在、１５歳までの預かりです。現在は小学校高学年や中学生の受入れがないということですが、早い子だと、小学校４年生ぐらいから思春期、二次性徴が始まって、男女一緒の部屋で就寝することに違和感を持つお子さんも出てくるのかなと思います。周知を広げるという意味でも、ニーズ調査をしていただくことを検討していただければと思いますが、ご所見をお伺いします。","respondent":"吉野子ども家庭支援センター長","answer":"今後ですけれども、思春期の子どもの保護者だけでなくて、実態把握のためのお子さんのご意見、こちらもお聞きするということを検討していきたいと考えております。","id":"exchange-029"},{"speaker":"澤田委員","kind":"意見","question":"児童福祉法で転用は難しいということです。空いているのに使えないということは、とても残念だなと思います。アンケートも実施というか、実態調査も実施することを検討してくださるということなので、その辺もお声を聞きながら、しっかり整備していただければなと思うのですが、その可能性というか、お考えをお聞かせください。","respondent":"吉野子ども家庭支援センター長","answer":"家庭あんしんセンターの建物の見直しについてですが、当該施設、開設から２３年を経過しておりますが、適切な維持管理に努めておりまして、定期的な修繕を行っております。施設全体が快適で安全性の維持向上に取り組んでいるところです。","id":"exchange-030"},{"speaker":"澤田委員","kind":"質問","question":"どうぞよろしくお願いします。次に、今年度は乳幼児ショートステイが拡大されました。すまいるスクールでの申請も電子化された今、様々子育て施策もＤＸ化が進んでおります。子どもショートステイでは、都度、利用時に申請書を郵送か直接持ち込むことになっておりますので、ぜひほかの事業と同様にＤＸ化を推進していただければと思いますが、ご見解をお聞かせください。","respondent":"吉野子ども家庭支援センター長","answer":"ＤＸ化を進めてまいります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"私からは、５４ページ、地方消費税交付金、５６ページ、特別区財政調整交付金、１６０ページ、財政調整基金繰入金に関連してお伺いいたします。本日は、消費税は個人だけではなくて自治体も払っているという観点からの質問をさせていただいきます。品川区は、会計上、いろいろ物件費だとかサービス費用に対して、消費税を支払っているかと思いますけれども、それについて消費税額を把握しているでしょうか。","respondent":"加島財政課長","answer":"今現在の財務会計システム上では、消費税を１件１件把握できる仕様にはなっておりませんので、正確な総額は把握できておりません。","id":"exchange-032"},{"speaker":"筒井委員","kind":"確認","question":"把握できていないということなのですけれども、最近、東京都のほうで、東京都都営住宅等事業会計で、消費税未納の問題が起きてしまいました。品川区の消費税支払いについても、消費税未納の問題とかが起き得るかと思いますけれども、そうしたことを確認するシステムに、今はなっていないということなのですけれども、未納の問題に対応できるのでしょうか。","respondent":"加島財政課長","answer":"都営住宅の消費税未納問題については、特別会計の問題かと思いますけれども、介護保険特別会計等におきましても適切に運用されているものと認識しております。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"なぜ買い物をするに当たり、罰金のような税金が発生するのか。本当になぜこうした税金が考えられたのか不思議でならないのですけれども。消費税は、国政上の問題ということで、主張することは難しいと私も考えておりますが、そうした観点もぜひ受け止めて、今後、国民会議に区としても、区長会を通じてでもいいですけれども、届けるべきだと考えていますが、区の認識をお伺いいたします。","respondent":"加島財政課長","answer":"そこのところの相互関係は、特段この税制の、消費税を実施するに当たって、差障りがあるとは考えておりません。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"今度、さらに国は、東京都と地方の税収格差是正、いわゆる偏在是正措置を検討されているです。それに加えて、ふるさと納税という国の不合理な税制もありますので、小池百合子東京都知事も、この国の偏在是正措置に反対をしておりますし、区長会も反対の緊急声明を出しておりますけれども、ぜひ品川区も偏在是正措置に反対していただきたいと思いますけれども、ご見解のほど、よろしくお願い申し上げます。","respondent":"加島財政課長","answer":"今後、区として何らかの意思表明という形につきましては、また検討が必要ですけれども、ホームページ等を用いまして、そういった不合理な税制改正に対する声を周知していくというところは努めてまいりたいと思います。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ力強い声を国に対して届けていっていただきたいと思います。最後に、財政調整基金です。一方、品川区では、財政調整基金、今後、２２０億円ぐらいまで積み立てたいということなのですけれども、お隣の港区は５００億円超。端的に言って、品川区は財政調整基金は足りているのか、危機管理体制として、ある程度増やしていくべきだと考えておりますが、改めて区のご見解をお伺いいたします。","respondent":"加島財政課長","answer":"こちらの財政調整基金の現在高の考え方ですけれども、昨日申し上げましたとおり、財政調整基金につきましては、リーマンショックが発生したときの減収見込み、減収の実績から、標準財政規模の２０％を２年間分というところで、今現在、必要想定額を見積もっているところです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ危機に備えていっていただきたいと思います。いろいろ区民の負担は増す中、そうした行政需要、危機管理もしなければいけないということで、大変な状況かなと私も理解しておりますけれど、そうした新たな基金として準備をする、そして、それを想定した区民に対する支援も、今後ぜひ検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。１１７ページ、地域住民と外国人との交流促進に関連して国際友好協会、１４５ページ、防災普及教育費、災害時応急物資確保費に関連して、なぎさ会館跡地の暫定活用を伺いたいと思います。最初に、１１７ページ、地域住民と外国人との交流促進に関連して、国際友好協会についてお尋ねいたします。これは、国際友好協会も第三庁舎から荏原町のほうに移転をして一年たちました。","respondent":"藤村総務課長","answer":"日本語教室のほうに来られる生徒ですとか、そういった方々も、場所が変わったことによりまして、少し幅広くなってきているかなという印象はあります。","id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"何なの？そういった中で、もう少し地域交流という観点で、周知をしていただきたい。外の掲示板はありますけれども、そこで町会行事のお知らせを掲示するか否かというのは、分かりませんけれども、何か周知が足りなくて、あそこは、国際交流のどういうことをやっているのかというようなお尋ねをされることもあるので、ぜひそこは改善をしていただきたいと思います。人数を把握したいのでよろしくお願いします。","respondent":"藤村総務課長","answer":"多文化共生を進める上で、しっかり改善していく事項もあります。国際友好協会が国際交流の窓口という形になっておりますので、地域の外国人の方ですとか、大使館との連携をもう少ししっかり図っていきたいと考えております。１１月に開催された防災がテーマの講座です。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"防災をテーマとしたという講座、私はこれ、すごく必要だと思うのです。地域でも、やはり、防災のイベント、地域、町ぐるみで参加できるようなものを、私のところで言うと、荏原第４地域センターの地区委員の方が主催をしている防災イベントとか、そういったことも、ぜひ今、荏原町に拠点を構えているわけですから、検討していただきたいと思います。これは要望で、よろしくお願いいたします。","respondent":"遠藤防災体制整備担当課長","answer":"こちらに関しましては、また、現在、南品川児童センターの改築に合わせまして、集中備蓄倉庫の物資をほかの備蓄倉庫のほうに移転しているということや、他の備蓄倉庫についても非常に逼迫した状況だということがありますので、暫定活用の際に。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これからいろいろ内容については検討していくと思うのですけれども、大体いつぐらいからやるのかが１つ。あそこは躯体をいじらないで、建替等何もやらないということで私は理解しましたけれども、これ、実際、有事が起きたときに、ここを拠点として物資を搬送する場合、これ、協定を結んでいるＪＰロジスティクスとやっていく、そういう認識でいいのかというかとを教えてください。","respondent":"遠藤防災体制整備担当課長","answer":"有事の際の活用というところで、ＪＰロジスティクスとの関係性を回答します。ＪＰロジスティクスに関しましては、京浜トラックターミナルに、国あるいは都からの支援物資をまず優先的に受け付ける。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問","question":"私からは、１２９ページ、東京ユースヘルスケア推進事業から、しながわほけんしつについて、１４９ページ、公立学校給食費負担軽減事業補助金から、私立小中学校の給食費について、同じページの不登校対策事業費から、学びの多様化学校について、持ち時間の中で３点お伺いしてまいります。思春期から若年成人期にかけての健康管理は多様化をしております。これまでの利用実績や相談内容の傾向を伺います。","respondent":"柴田子ども施策連携担当課長","answer":"本事業は、現在、チャット相談と対面相談会の２つを軸に事業を実施しておりますが、チャット相談につきましては、毎月３０から５０件程度の相談があり、利用登録者、いわゆるお友達登録数は、累計で１,８００人を超えているところです。","id":"exchange-042"},{"speaker":"新妻委員","kind":"提案","question":"私は、これまで一般質問でプレコンセプションケアや、また、リプロダクティブ・ヘルス／ライツの取組についても提案等をさせていただいてまいりました。ユースヘルスケアしながわほけんしつでのリプロダクティブ・ヘルス／ライツの学ぶ機会、また、これを展開していくことへの区の認識をお伺いいたします。ユースヘルスケアのさらなる充実を図るべきと考えますが、令和８年度の具体的な取組を伺います。","respondent":"柴田子ども施策連携担当課長","answer":"令和８年度の取組といたしましては、これまでの実施内容を継続することに加えまして、新たに若者が気軽に集える雰囲気の場所、例えば、レンタルのイベントスペースなどを活用しまして、対面相談会イベントを実施していく考えです。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"確実に進めていただきたいことを要望いたします。次に、学校給食費から私立小中学校への給食費助成について伺います。昨年の予算特別委員会の総括質疑において、私立小中学校に通うご家庭への給食費助成について要望いたしました。都から正式な予算が出ているわけではありませんけれども、ぜひ活用して、品川区もここに手を挙げていただきたいと思いますが、見解を伺います。","respondent":"崎村企画課長","answer":"確かに、今お話がありましたように、公立学校に通っている生徒については給食費が無償化されていて、私立学校に通っているお子さんには出ていないというところで差が出ているところについては、昨年の施政方針で申し上げましたけれども、基本的には。","id":"exchange-044"},{"speaker":"新妻委員","kind":"質問・要望","question":"先般の都議会第１回定例会の代表質問で、公明党からも確認いたしましたとおり、今現在、東京都内では８区市町村が私立学校等への給食費の助成をしているというふうになっております。東京都がつける予算に対して、この８区が手を挙げると思われます。そして、検討に当たっては、どこの場所に設置をするのかということがあって進められていることと思いますが、どこに設置をされるのかお伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"不登校特例校から学びの多様化学校ということで名称が変わり、また、近隣、大田区や世田谷区にも設置が進んでいるということで、本区においても、こうした学びの多様化学校の設置について、内部でも検討を進めてきたところです。","id":"exchange-045"},{"speaker":"新妻委員","kind":"質問","question":"具体的に検討が進んでいるということが分かりました。今現在、大田区では、令和１３年度を目指して、区有地を活用して、（仮称）大田区立みらい学園ということで、新たな小中一緒になった大きな学校ができるのでしょうか。推進をお願いしたいと思います。今、マイスクールがあります。マイスクールと、この学びの多様化学校では何が大きな違いなのか、最後にお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"教員の配置について、学びの多様化学校は学校ですので、正規教員が配置されるということも大きな違いだと考えております。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問・要望","question":"不登校になる要因は様々かと思います。不登校に何かのきっかけでなったわけではなく、そもそも特性として、そういう小さいところで学んでいくことが合っている子どももいると思いますので、それぞれの形に合った学びの場がしっかりと広がっていきますことを要望させていただきまして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"こしば委員","kind":"質問","question":"よろしくお願いします。私からは、６７ページの歴史館使用料と今後の歴史館についてと、もう１つは、７７ページ、自転車駐車場使用料と、それに関連しまして、西大井駅周辺の駐輪対策についてお伺いしてまいります。当日は、御殿山の特別観覧料を含めまして、３００円の観覧料を支払い、中に入りました。この回数についてどのように受け止めているのか、お考えを教えてください。","respondent":"大森文化観光戦略課長","answer":"歴史館の貸し館につきましては、書院と茶室と講堂という３つの施設があります。そちらは、ご指摘のとおり、年間の利用率からいくと、今年度１月時点で、１１％から１３％ほどに収まっております。","id":"exchange-048"},{"speaker":"こしば委員","kind":"質問","question":"今、観覧料の総額は年間ベースで４７万９,０００円、特別観覧料が６１万７,０００円、合わせて１０９万円。維持運営費に１億円ほどかかる中で、物価高騰、また、維持運営に係る資材の高騰の影響もあるかと思いますが、観覧料について、このまま据置きのままでいくのか、また、今後も方針を変えることなく続けていくのか、観覧料についての考えについて教えていただければと思います。","respondent":"大森文化観光戦略課長","answer":"こちらは、今回の御殿山の特別展等も前期・後期と分けまして、チケットを１枚にするといった、台紙を配ってシールを貼って前期と後期で見ていただいた方に、ちょっとしたプレゼントになるといったような様々な工夫をしまして、入館者の増に工夫をしていければと考えていますので。","id":"exchange-049"},{"speaker":"こしば委員","kind":"質問・要望","question":"思いはしっかりと受け止めました。この有効活用をぜひ検討していただきたく、例えば、結婚前のフォトウェディングだとか、あと、着物の着付け教室、あと、品川区にゆかりのある坂本龍馬だとか、伊藤博文、そういった人物の幕末志士に扮したコスプレのイベントなど、そういったものにぜひ、ひもづけていただいて、有効活用を考えていただきたいと思いますけれども、お考えをお伺いしたいと思います。","respondent":"大森文化観光戦略課長","answer":"歴史館の活用について、庭園でコンサートをしたりとかという実績はあるものの、なかなかやはり職員の数とか、そういった関係で、なかなか大きなイベントをやるということが困難な状況ではありますけれども、その中で、施設の有効活用という観点。","id":"exchange-050"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ有効活用を検討していただきたいと思います。もう１つ、講堂、ちょうど先日、私、視察したときに、偶然にも４０周年の行事がされておりまして、二胡という中国の楽器を使ったイベントがされておりまして、大変２階がにぎわってきました。分かる範囲で、例えば、令和７年度で利用されてきました団体の数であったりだとか、あと、団体の特徴、そういったものを分かる範囲で教えていただければと思います。","respondent":"大森文化観光戦略課長","answer":"先ほど申し上げましたように、若干使用料は高めという話もあるのですけれども、まずは、広報等、ホームページの改修等、そういったところで施設のＰＲをもっとしていきまして、利用団体への配慮は、引き続き検討してまいりたいと思います。","id":"exchange-051"},{"speaker":"こしば委員","kind":"質問","question":"当日使用の需要が極めて高い西大井駅の周辺についてお伺いしてまいります。時間に余裕がないときに、どうしても３階を使わずに、ほかの駐輪場が空いてればいいのですけれども、結局そこで無断駐輪してしまう、そのようなケースも地元の方々からもよく聞いているところです。その一方で、今後、この西大井駅周辺、駐輪場を新しく設置するとも聞いておりますけれども、その辺りを教えていただければ思います。","respondent":"山下交通安全担当課長","answer":"西大井駅周辺の駐輪場の関係ですが、委員ご指摘のとおり、西大井の駐輪場につきましては、利用率が高く、なかなかご不便をかけているところで、さらには３階の利用の不便さが出ているということですけれども、参考ですけれども、３階の駐輪場におきましては。","id":"exchange-052"},{"speaker":"こしば委員","kind":"質問・要望","question":"時間が少なくなってきたので、次に新しく駐輪場を新設されるという話も聞きました。そういう中で、防犯シールを貼ることによって、所有者自身が盗難の防止にもつながっていくと思いますけれども、この辺り、ぜひ品川区のほうでも、警察や民間施設の管理会社とも連携をとっていただきまして、防犯登録を促していく仕組みづくりをぜひご検討いただきたいと思いますが、お伺いしたいと思います。","respondent":"山下交通安全担当課長","answer":"ちなみに、施設のための駐輪場につきましては、民有地、私地等です。こちらの敷地につきましては、基本的には管理者の管理権に基づく対応をしていただいているところです。区としましては、路上に放置されている自転車につきましては指導撤去等をしてまいります。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問","question":"６０ページから始まる使用料及び手数料より、区有施設における子ども料金の無償化について受益者負担の考え方、関連して、子どもの国民健康保険料、区営自転車駐輪場、五反田文化センタープラネタリウムについて、それぞれ順次伺いたいと思います。そこで、子育ての社会化ということですが、受益者負担の考え方に何か変更があったのか伺います。","respondent":"崎村企画課長","answer":"一方で、今回の施政方針でも申し上げましたけれども、これまで区が進めてきた子どもと子育てを社会全体で支える、子育ての社会化をさらに進めていくと決意を申し上げましたが、子育ての社会化、これは今までも行ってまいりましたけれども。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"子ども施策に関わる受益者負担については克服するという説明でした。従来だと、プールを利用し、受益者は子ども自身が受益者だということで料金を払ったのですけれども、今回からは克服ということになると、受益者は、要するに、プールに入った体験という、受益者は社会全体の利益である、だから、自己負担ではなくて税金で負担するのだと、この考えでよいのか改めて伺いたいと思います。","respondent":"崎村企画課長","answer":"こういったことを踏まえまして、体験活動の格差解消に向けて、区として何に取り組めるかと検討したときに、区有施設の使用料金を無償化するといった取組を来年度から始めるものです。","id":"exchange-055"},{"speaker":"中塚委員","kind":"提案","question":"いよいよ子どもに関わる負担というところで、関連して、国民健康保険の子どもの保険料無償化へ進むべきだと思います。ならば、子どもが生まれるために保険料の負担を求める、これは子育ての社会化とは相入れないと私は思いますが、いかがでしょうか。学生の使用料無償化、または学割の導入について、建設委員会でも提案いたしましたが、改めて提案いたします。それぞれいかがでしょうか。","respondent":"山下国保医療年金課長、山下交通安全担当課長","answer":"様々取組を進めているところですけれども、未就学児の軽減割等も実際に実施していますので、制度に沿って運営をしていく考えです。しかし、将来的に、駐輪場の需要ですとか、様々な環境、また、他区の導入状況等を踏まえて検討する余地はあるのかと考えているところです。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ子育ての社会化と、次なるステージへと述べているわけですから、子どもの国民健康保険料についても、駐輪場についても、子どもの負担の無償化、軽減へご検討いただきたいと、その姿勢を貫いていただきたいと強く要望したいと思います。なぜ７０歳以上なのかと私は疑問です。ぜひ五反田文化センタープラネタリウムにも高齢者、障害者の無償化を導入していただきたいと思いますが、いかがでしょうか。","respondent":"守屋スポーツ推進課長、大森文化観光戦略課長","answer":"高齢者の健康増進等などの支援のために、様々な高齢者サービスや事業のバランスなどを総合的に勘案して、７０歳以上を無料にしたものと認識しております。五反田文化センタープラネタリウムにおける高齢者、障害者の使用料減免措置につきましては、今後、各施設間の均衡等も踏まえまして、課題等を整理してまいる所存です。","id":"exchange-057"},{"speaker":"中塚委員","kind":"提案","question":"区有施設の高齢者の使用料無料の対象年齢について、現在、７０歳ということで、６５歳を提案したのですけれども、その考えはないとのことでありました。何か急に冷たくなったなという思いがいたします。定年の年齢や年金支給年齢を見ると、６５歳ということで、７０歳というのは社会の実態と合いませんので、ぜひともご検討いただきたいと要望したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"松永委員","kind":"質問","question":"私からは、１６３ページの過料より、路上喫煙について、１７９ページの公益信託岩田記念戸籍制度研究助成基金について伺いたいと思います。初めに、１６３ページの過料の路上喫煙について伺いたいと思います。この路上喫煙で主に過料が課された場所について伺いたいと思います。そうしたところはどういうふうな状況になっているのか伺いたいと思います。","respondent":"澤邉生活安全担当課長","answer":"ただいま過料の徴収場所についてのご質疑をいただきました。品川区の条例につきましては、過料を徴収する場所が決まっております。各主要な駅、五反田駅等を周辺とした地区になっておりまして、その場所以外については過料の徴収はしておりません。","id":"exchange-059"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、今日質問する内容といたしましては、大森駅の歩道橋の、要は、エスカレーターをおりたところです、水神口のほうなのですけれども、あそこで朝５時に予定がありまして、そちらでいろいろ調査をさせていただいたのですが、外国人の方がバスから降りて、３０人ぐらいですか、降りて、そこで、近くのコンビニが２つあるのですけれども、青いほうのコンビニの前と、あとは公衆トイレの前でたむろして。","respondent":"澤邉生活安全担当課長","answer":"委員ご指摘のありました英語等表記につきましては、委員のご指摘にありましたとおり、路上にはありますけれども、さらに今年度から、英語表記等々の、ポスター的なものも始めておりますので、そういったものを活用して、大森駅をできる限りパトロールをしてまいりたいと。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問・要望","question":"今回、たばこ税も増えておりますので、そうしたところにぜひ活用していただきたいと思います。次に、１７９ページの公益信託岩田記念戸籍制度研究助成基金について伺いたいと思います。この助成基金についてですが、初めてお聞きするような項目だと思います。私にとってはですが。この事業内容について、どういったものなのかお知らせください。いつからこの事業が始められたのか併せて伺います。","respondent":"築山戸籍住民課長","answer":"主に行政等の団体に対して、戸籍制度の研修等に対して助成をしてくれるものになっております。制度につきましては、品川区は令和５年度からこちらを活用しています。","id":"exchange-061"},{"speaker":"松永委員","kind":"質問","question":"令和５年度ということですので、最近かなと思います。この制度を、基金を活用できるというのは、大変難しい条件があったとお聞きしております。その中で、品川区として、戸籍についての思いというか、いろいろな形で伝えられて、やっとこういう形で歳入に掲載できたのかなと思うのですが、品川区の戸籍についての思いを改めて伺いたいと思います。","respondent":"築山戸籍住民課長","answer":"戸籍事務です。戸籍は、法定受託事務ではありますが、専門性が高い事務です。そのため、区民の方に正確な事務を適正かつ素早く窓口で対応できるようにということで、職員のスキルアップが必要だと考えております。","id":"exchange-062"},{"speaker":"松永委員","kind":"質問","question":"先ほど少し研修のお話があったので、研修について伺いたいと思うのですが、研修で得られた知識、例えば、実務の効率化とか、区民サービスの向上につなげていただいていると思うのですけれども、今後、私、予算書の中で、何に使われているかという掲載がなかったので、ぜひそうしたところの掲載もできたらお願いしたいと思います。戸籍の届出について、どういった対策をとられているのでしょうか。","respondent":"築山戸籍住民課長","answer":"窓口でご相談があった場合は、そのときに、都度、個々の個別の対応を行っているところです。","id":"exchange-063"},{"speaker":"松永委員","kind":"質問","question":"そこで最後に、ご意見等を聞ければなと思うのですが、日本には、無戸籍の方、いわゆる戸籍を持たない方は、法務省の調べでは全国で約７００人と言われておるのですけれども、品川区に、もしそういう方がおられた場合の対応方法とか、今後どういった形でやられるのか最後に伺います。","respondent":"築山戸籍住民課長","answer":"過去、無戸籍者の調査をしまして、現在、全ての方が解消しています。現在も法務局と連携しながら情報共有を行っているところです。今後そのような無戸籍者の方がいらっしゃった場合は、引き続き、法務局と調整しながら対応してまいります。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひとも品川区でさらに対象拡大をして、私立学校や国立、都立、それから朝鮮学校を含む各種学校など、品川区の全ての子どもたちの給食費の無償化を求めて質問したいと思います。ぜひとも品川区の全ての子どもたちの学校給食費無償化へ、私立、国立、都立、朝鮮学校を含む各種学校などに通う小中学生への、給食費の無償化に踏み出していただきたいと思いますが、いかがでしょうか。","respondent":"崎村企画課長","answer":"そうした経過を踏まえまして、動向を踏まえてになりますけれども、詳細な制度設計、情報等を踏まえて、区のほうでも検討していきたいと考えております。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今は区立の小中学生と、それから特別支援学校の子どもたちは無償化されているわけですけれども、それ以外に通う子どもたちの人数が、小中学生で何人いるかということと、その無償化には幾らぐらいかかるのかということを教えていただきたいと思います。","respondent":"石井学務課長","answer":"仮に、先ほど委員がおっしゃったような形で、そういった方々に関しての無償化事業を実際に実施するとなると、約３億円から５億円ぐらいの幅の金額の財源が必要になってくるのではないかという推計は可能です。","id":"exchange-066"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３億円から５億円ということです。先ほどもありましたけれども、それから、学校を選択する自由も保障されるものですので、ぜひ全ての子どもたちに給食費の無償化を、それ相当の額の支給ということになると思うのですけれども、そういう形で無償化を実現していただきたいということで強く要望をしておきたいと思います。改めて、ぜひ無償化に踏み出していただきたいと思いますが、いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"完全な接種率を出すのは難しいため、今回は、２回打たなければいけない不活化ワクチンですので、不活化ワクチンを１回打っている方と、生ワクチンを１回接種している方を足した数を対象人口で割らせていただいたものを接種率ということでお答えします。","id":"exchange-067"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に親も働いていて、子どもがインフルエンザにかかっても仕事も休めなかったりとか、子どもたちも、なるべくインフルエンザにならないようにというふうなところで予防接種を頑張って受けて、４８.７％というふうな接種率にもなっていると思いますので、ぜひ無償化に踏み出していただきたいと、これも要望させていただきたいと思います。１０回出されたのです。実績について、まずお聞かせください。","respondent":"樫村高齢者地域支援課長","answer":"高齢者補聴器購入助成事業の、まず実績ですけれども、委員ご指摘のとおり、令和５年度に開始した事業でございまして、令和５年度につきましては、７月開始で１３０人の実績、令和６年度につきましては４１５人、そして今年度、令和７年度につきましては。","id":"exchange-068"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点では、さらにそれを拡大していただきたいと思います。７万２,４５０円というのは本当に助かってはいるのですけれども、これではまだ購入できない。スタンダードでも１５万円ぐらいはかかるというふうなことで言われていますので、東京都からは、１４万４,９００円までは半額補助が出ますので、ここまでぜひ拡大していただきたいと思うのですけれども、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"それから非課税者につきましては、先ほど委員のお話の中にもございましたけれども、本区としましては、令和５年度の７月に、まず対象者を非課税者に限定しまして３万５,０００円で実施、そして令和６年度には、所得制限を撤廃しまして、課税者、非課税者に対して実施。","id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は、非課税者は少なくとも１４万４,９００円まで拡大していただきたいですし、できれば課税者まで所得制限なく１４万４,９００円まで、ぜひとも拡大していただきたいと思いますけれども、そこのところが、いや、そういうふうに、そこまで出せるのに、東京都が非課税者をここまで出すのにやらないというその理由は、所得制限をなくしたいという、そういう思いからなのか、その点を伺いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"事業の対象者の考え方ですけれども、区としましては、先ほど申し上げたとおりの経過で、令和５年度から、順次、事業の拡大をしてきたという経緯がありますので、今、大変ご好評もいただいている事業ですので、この形で実施をしていきたいと考えています。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問","question":"私からは、９９ページの児童相談事業について伺いたいと思います。だからこそ、どういう状態になったら家に帰してもらえるのか、児童相談所がいいのか、子ども家庭支援センターがいいのか、その辺は分かりませんけれども、指摘なり指導なり、何かそういう話合いの場を持ちたかったということなのですが、その点について、何か教えていただければと思います。","respondent":"長谷川児童相談課長","answer":"一方で、今回の事例のように、説明が十分に伝わらなかった、あるいは認識に齟齬が生じたとのご指摘がある場合には、真摯に受け止め、より分かりやすい説明や丁寧な対応に努めてまいる所存です。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"一律に言えることではないというのは、私も本当にそのとおりだと思っておりまして、だからこそ、やはり個々のケースで、自分たちはどうしたらいい、一応、一応などと失礼な言い方をしてしまいましたが、自分たちに非があったということは認めておられて、それをどういうふうに改善をすれば、客観的に、これは家庭に帰せる状況になるかということを自分たちとして知りたい、だから。","respondent":"長谷川児童相談課長","answer":"どのケースのことかということは、今、議論にはなっていないので、あくまでも一般論と解釈し、お答えさせいただきますが、また先ほどの繰り返しにもなってしまいますけれども、こちらの説明が十分でなく。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。それ以上のご答弁は難しいかなと思うのですけれども、例えば、保護者のほうから見れば、コミュニケーションを十分にとられていないなと思った場合は、児童相談所に直接お電話なり、それとも子ども家庭支援センターなのでしょうか、その辺のアドバイスが私にできなくて、こういう質問に至っているわけですけれども、その辺、具体的な手続について教えていただければと思います。","respondent":"長谷川児童相談課長","answer":"児童相談所は、基本的に開庁時間が決まっておりますけれども、夜間帯であるとか早朝時間、あるいは休日に関しても電話応対ができますので、ご案内している電話番号のほうに連絡いただき、ご対応します。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークとしても、区に児童相談所ができたということは、大変大切なことであり、評価をしておりますので、今後も適切な一次保護などをされた上で、親御さんとのコミュニケーションもぜひ努めていっていただきたいと思います。その点について、東京都の児童相談所に比べて品川区の児童相談所として、これに力を入れているというようなところがあったら、教えていただければと思います。","respondent":"長谷川児童相談課長","answer":"品川区児童相談所は令和６年１０月に開設いたしまして、東京都児童相談所が行っていた支援をそのまま引継ぎ実施しています。区立児童相談所を開設した最も大きなメリット、利点としては、やはり地域が都に比べると狭いというところ。機動力が非常に高まったなと思っています。","id":"exchange-074"},{"speaker":"吉田委員","kind":"提案","question":"このご相談いただいた方からは、これからも私たちとしても、児童相談所の機能について話合いを進めたいと考えていますので、これからも適切なご提案ができたらというふうに思っておりますし、ぜひ、私の一般質問に対するご答弁では、検証が進むということですので、是非そちらもどうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"来年度予算案の審査初日に当たり、歳入を含む令和８年度の区政の方向を示す本会議初日に拝聴いたしました森澤区長の施政方針から伺ってまいります。８分ぐらい、市政方針の解釈と感想を述べた後に、後半でまとめて個別の内容について３点伺ってまいります。今から６年前、令和２年の第４回定例会で、私は会派を代表して一般質問の中で、この障害者施策の担当部長の設置を求めて、次のような質問をしました。","respondent":"加島財政課長、崎村企画課長、菅野高齢者福祉課長、佐藤障害者施策推進課長","answer":"今後につきましては、また社会経済情勢の変化や区民ニーズ、財政状況など、総合的に勘案しながら予算編成を通じて判断していくものですが。しかしながら、区の実態が全国平均と比べ構成比に大きな乖離があるというようなお話もございましたので、国の基準を遵守しつつ。計画策定ですとか施設整備を所管する障害者施策推進課を令和４年度に新設するなどしまして、これまで様々な体制強化を図ってまいりましたけれども。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、我々もこれは何度も経験しているのですが、改革は進めば進むほど抵抗が強くなる。政治や組織、経済などの構造改革において、これはしばしば観察される現象です。区長には、こうした反作用に負けずに、信じる道を真っすぐに進んでいっていただきたいと思います。『どうせ社会は変えられないなんてだれが言った？』、こういう本を書かれていますけれども、我々もその決意で頑張ってまいります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１０分なので、私は、５６ページ、特別区財政調整交付金と、１３９ページ、都市計画交付金のお話をさせていただきたいと考えています。極端なことを言って、固定資産税の在り方から考えたらどうだぐらいのことは言いましたけれども、それはどういう意味ですかと。今、都市計画交付金は３,０００億円になってきていて、それの１０％というのはあまりにひど過ぎる。それだったらそれでいいではないですか。","respondent":"加島財政課長","answer":"そういった課長間のやり取りの中では、品川区で先行して進めた無償化施策について、制服ですとか、修学旅行費とか、どのような反響がありますかというようなお話をいただいたりですとか、それによって区民のウェルビーイングが。","id":"exchange-078"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つだけ、都税という話は、基本的には、これ、市町村民税だということが根底にある。特別区だから都税に今なっているけれども、ほかは全部市町村民税。ここの４０人も、私、半分ぐらいの人は分かっていないような気がするのだよな。財調だって、管理職の人には悪いけれども、管理職の人も、よく聞くと、「それって財調算定されているんじゃないですかね」って。","respondent":"加島財政課長","answer":"全都市計画事業の交付対象化、それから実施に見合う都市計画交付金の拡大です。そして何よりも、先ほどございました使途が不明となっていることへの詳細な情報の提示を求めているところです。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"お願いします。私は、１６３ページ、奨学金貸付金返還金と、１２３ページの介護人材確保対策事業費補助金でお願いします。品川区が行っている給付型奨学金、非常に好評ですけれども、さらなる拡充を求めて質問をいたします。７８万円も今増えております。超低金利の時代です。ぜひこういった奨学金支払中の方たちに対して、区として支援をしていただけないかと思うのですが、いかがでしょうか。","respondent":"柏木子育て応援課長","answer":"本区におきましても、本区の奨学金の返還でお困りの際は、現在も相談を受け付けております。引き続き、本区におきましても丁寧に対応してまいりたいと考えています。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私が聞いていたのは、大学の奨学金だったので、高校とは違うのですけれども、やはり返済されていらっしゃるのは、主に２０代、３０代の方ということです。こういった「不」を解消していくことが、それこそ森澤区長の目指すところであるかなと私は思っていますので、ぜひこういったところに手を差し伸べてほしいと強く思います。実現可能かと思いますけれども、改めて答弁をお願いします。","respondent":"柏木子育て応援課長","answer":"課題等につきましては、先ほどご答弁をさせていただいたとおりです。先ほど、ほかの区の事例がございましたが、そういった他区の状況等は今後も見ていきたいと考えています。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ他区の事例も参考にしていただきたいと思います。そこで、想像を働かせていただきたいは、誰かの支払いが増えているということは、誰かの実入り、収入が増えているということなのです。これは当然どんどんこれから上がっていきます。そういった地域振興という意味でも、若者に対し負担感の重い奨学金に対して、区として手を差し伸べるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"大倉委員","kind":"質問","question":"お願いします。６０ページの歳入、使用料のところで、午前中も少しありましたけれども、子どもの料金無償化のところを伺えればということと、１５１ページの保幼小連携推進経費と、１５１ページ、在外選挙人名簿登録事務委託費について、伺えればと思います。実際に選挙が始まったときには、どのような手続というか、事務になってくるのか教えていただければと思います。","respondent":"大友公園課長、守屋スポーツ推進課長、大森文化観光戦略課長、染谷保育施設運営課長、今井選挙管理委員会事務局長","answer":"その他受付等々の費用等で、公園課所管分としては、約１００万円程度、そこで見込んでいる形になってあります。スポーツ施設の部分につきましては、歳入減というところですと、学校温水プールの無償化に伴う歳入減で。子ども料金の無償化についての歳入は予算に反映されております。歴史館とプラネタリウム、合わせて約２３万円という形で減額しております。具体的には、例えば、自然に親しむですとか、水をテーマにしたりですとか、体で遊ぼうですとか、音に触れるとか、そういう様々な。","id":"exchange-083"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺のデータ、今後検証して、さらにこれから施策をどう広げていくかというところも視点として持っていただきたいと思っています。教えていただければと思います。人材のところで、それぞれ人を増やす必要があるところがあるのかどうかも教えていただければと思います。保幼小連携については、具体的な事業で、どういった事業がこれを使ってやられているかとか分かれば教えていただきたいと思います。","respondent":"守屋スポーツ推進課長、染谷保育施設運営課長、今井選挙管理委員会事務局長","answer":"事業自体は７月からの開始となりますので、そういった利用状況等を見ながら、データを取りまして。すくわくプログラムの具体的な実施内容ですが、例えば、子どもが園庭で見つけた好きな自然物を凍らせて、それを削ったり溶かしたりして遊ぶ中で。ただ、こちら、郵便投票で私どもが投票用紙を送達できるのは、国政選挙の任期満了の６０日前か。","id":"exchange-084"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば、体験格差をなくしていくとか、子育ての社会化をしていくというところで、１８歳までということなので、中学校などへ行って部活動をするとかとなったときに、今は部活動の地域移行なども進められているところでありますが、そういった小学校、義務教育学校、中学校での部活動での体験など、今後、費用がかかる部分についても、ぜひ体験格差をなくしていただきたい。大変だったと思います。","respondent":"酒川指導課長、唐澤教育施策推進担当課長、今井選挙管理委員会事務局長","answer":"部活動の地域移行に当たりましては、体験格差を生じさせないよう十分配慮していきたいと考えております。探求的な学習の連携についてですが、探究的な学習の基盤である生活科で保幼小の連携を図ってまいりますし、また。引き続き、選挙の管理執行には、期間を限らず適正に対応していきたいと考えています。","id":"exchange-085"},{"speaker":"大倉委員","kind":"質問","question":"最後に、選挙について、場所によっては、かなりなりすましが増えたというような記事をＳＮＳで、目にしました。そういったときに、警察だと、例えば、期日前投票所とかになりすましは刑罰に当たりますというような掲示もするようにして啓発をしていくみたいなこともされているところもあるようなのですが、そうしたなりすましをされないような掲示、周知は、どのようにされていくお考えか教えてください。","respondent":"今井選挙管理委員会事務局長","answer":"なりすましは、これは詐欺投票で公職選挙法の違反になります。こちらの周知は、まだ投票所等では周知しておりませんけれども、例えば、これから区のホームページ等を含めて、周知または注意喚起していきたいと考えています。","id":"exchange-086"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、４９ページの特別区税とか特別区交付金など歳入全般について、それから、１０５ページの無電柱化推進計画事業補助金、１４１ページの電線類地中化事業費、これについて伺っていきたいと思います。区として、一応８０％にじりじり近づいているような状況ですけれども、財政の硬直化という観点から、この８０％という数字をどういうふうに見ているのか、その見解をお聞きいたします。","respondent":"加島財政課長","answer":"ただ、事務事業評価によるスクラップ・アンド・ビルドによりまして、経常的経費につきましても、聖域なき歳出改革というところで見直しを図っておりますので、そこから特に経費を固定化させることなく、きちんとアップデートを図っていくことによって、この経常経費の７８.１％。","id":"exchange-087"},{"speaker":"塚本委員","kind":"意見","question":"そうですね、時間もあれなのですけれども、いわゆる８０％を超えないようにということでの財政の運営ということなのだと思うのですけれども、そういった中で、今後、特に都とか国からの税収も大きく期待したいというか、そういったところからの税収増もいろいろなすべきかなというふうに思います。","respondent":"加島財政課長","answer":"都区財政調整におきまして、交付金が需要額を下回った場合ですけれども、こちらにつきましては、都区間で恒久的ルールが定められておりまして、この場合には、各特別区の普通交付金の額を基準財政需要額に応じて一律に減額して算定することで調整されることになります。","id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"やはり定められた金額を、交付額をそれぞれ２３区でということになるのかなということで、本来であれば、本来必要な需要額をきちんと都としてたらずまいという言い方をするのですか、手当てしていただくという制度になっていければなというふうに思うのですけれども、そこについては、本来的な、そもそも論になってしまうというところもあると思うので、今後とも、注視するというか。","respondent":"森道路課長","answer":"３倍増になったというのは、区費のほうかなと思いますけれども、こちらにつきましては、競馬場通りにおいて、電線共同溝本体の工事に本格的に着手するということで、その分、増加しています。","id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"どういったところが、今現在、計画どおりいっていない理由なのか、そして、それは、今後、この計画の中で、２９年ということでお尻が迫ってきていますけれども、しっかり進めていっていただきたいという思いがあるのですけれども、この進捗についてお伺いいたします。","respondent":"森道路課長","answer":"こちらにつきましては、それぞれ道幅がそれほど広くないということと、それから、地下埋設物が錯綜しているということと、旗の台駅のほうには商店街もありますので、そういったご協力も欠かせないところがありますので進んでおりませんが、引き続き計画を見直しながら。","id":"exchange-090"},{"speaker":"塚本委員","kind":"質問","question":"ぜひ今おっしゃった路線について、いち早くというか、計画どおりに進めていただけるように、重ねてお願いを申し上げまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"須貝委員","kind":"質問","question":"私は、７ページ、予算編成の基本となっている施政方針についてお聞きしたいと思います。でも、現実論、今、弱者がどんどん増えているのではないですか。今日いっぱい出ていましたよね、子育て支援、介護、それから障害者支援、それから学校の問題もあると思います。様々なところで様々な問題が提起されていると思うのですが、その辺についてどのようにお考えなのでしょうか。","respondent":"崎村企画課長","answer":"弱者が増えているのではないかというようなご質問ですけれども、定量的な何か数字を持ち合わせているものではありませんので、委員の主観的なお考えなのかなと考えています。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"それ、企画が言うのですか。では、各事業部に聞いてみたいですよ。皆さん、全然そういう問題もない、相談もないのですか。品川区は安泰なのですか。どうなのですか。違いますか、これ、うそですか。入りたいのです、施設に。こういうことを皆さんで肌で聞いているのではないのですか。本当ですか。そんなでたらめを企画が言っていいのですか。本当にその辺について、もう一度ご見解をお聞かせください。","respondent":"久保田企画経営部長","answer":"企画課長が今ご答弁申し上げましたけれども、品川区としましては、確かにいろいろと支援をしていかなければいけない事情をお持ちの方がたくさんいることは、それは現実として認識しております。","id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"ですけれども、現実論どうなのですか。でも、現実論はますます増えていませんか。だから、こうやって掲げて、逆に、減るどころか増えていったら、弱者がどんどん増える一方ではないですか。そうしたら、そちらの方はどうするのですか。そちらの方をまず助けてから、前に前に、弱者を生まない社会をつくっていくということを考えなければいけないのではないですか。その辺についてご見解をお聞かせください。","respondent":"崎村企画課長","answer":"ですので、昨年の施政方針でも申し上げましたけれども、弱者を救うのではなくて、弱者そのものを生まない社会を構築したいといったことで、品川区としては取組を進めているところです。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問","question":"でも、現実論、弱者が増えていたら、このようなことは書けないのではないですか。１日２食という方もいます。そういうところに目を背けないで、私はやはり弱い人をまず助けてから、こういう理念を掲げるべきではないかと思います。それから、施政方針の３に、しなやかな社会をつくるとあります。それは皆さんご存じではないですか。それをこういう書き方をしていいのですか。ご見解をお聞かせください。","respondent":"崎村企画課長","answer":"「しなやか」という言葉について少し申し上げますと、先ほども幾つか国において起こった事例を挙げていただきましたけれども、逆境でも折れずに自分らしく立ち直る力がある、回復力、よく「レジリエンス」という言葉を使われていますけれども。","id":"exchange-095"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に戦ったのですよ、皆さん。だって、新聞記事を見れば分かるではないですか。どれだけの人が苦しんだのですか。亡くなった方がどれだけいるのですか。お店も潰れて、家庭も崩壊して、自殺までする、そういうつらい目に遭った、そういう人たちのことを考えて、こういう施政方針も、しっかりこれは予算書の根幹となるのですから、私はしっかりそういうことは書いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"せお委員","kind":"質問・要望","question":"１３７ページ、５歳児健康診査、８９ページ、生活困窮者支援費、１４９ページ、給食運営費についてお伺いします。５歳児健診です。品川区では、今年度からモデル実施をしてきましたが、そのスキーム、実施方法を改めて教えていただきたいのと、あと、現状でお話しできる範囲での成果と課題も教えてください。","respondent":"石橋品川保健センター所長","answer":"しかし、区としましては、対象の方全員に受診をしていただきたい健診として認識しておりますので、今後、５歳児健診の必要性、意義をしっかりと区民に浸透できるように周知に努めてまいりたいと考えております。","id":"exchange-097"},{"speaker":"せお委員","kind":"提案","question":"こども家庭庁によると、令和７年度こども家庭科学研究費補助金成育疾患克服等次世代育成基盤研究事業によるアンケート調査において、自治体にアンケートをとって、２段階方式についても、全５歳児を対象にした集団健診と同様の効果を持つ場合があると確認されましたと書かれています。相談先と療育ともに、今後の展開がありましたら教えてください。","respondent":"石橋品川保健センター所長、佐藤障害者施策推進課長","answer":"そのことを踏まえまして、２回目の健診について、心理士の方を１回目より多く確保して実施したという実績が今回あります。療育の受入体制強化ですけれども、放課後等デイサービス等につきまして、障害福祉部のほうで受入れの強化を図っているところで、ニーズに応えるため、昨年１１月から、物件の家賃補助などを含めた開設補助制度なども創設しまして。","id":"exchange-098"},{"speaker":"せお委員","kind":"質問・要望","question":"放課後等デイサービスももちろんそうなのですけれども、児童発達支援のほうもぜひ広げていっていただきたいと、要望しておきます。次に移ります。高齢者熱中症見守り宅配事業は、来年度の当初予算にはないのですけれども、エアコン購入費助成が宅配事業の代わりとなっているのか、そこら辺を教えていただければと思います。","respondent":"東野福祉計画課長","answer":"昨年の６月補正で行ったものなので、時期的にそういった暑い時期になってしまったというところもありまして、今年度、令和８年度予算につきましては、実は福祉部としてどうするかというところを検討いたしまして、一旦は予算要求をさせていただきました。","id":"exchange-099"},{"speaker":"せお委員","kind":"質問","question":"理解しました。対象者も減るというところで、代わりというか、そこ自体をやめるのであれば、代わりとなる事業というか、そういったものが必要なのかなと考えるのですけれども、そこら辺はどのようにお考えか、現在考えていることがあれば教えてください。","respondent":"東野福祉計画課長","answer":"評価につきましては、先ほどもお話しさせていただきました一定の熱中症に対する情報については、高齢者に意識づけされたという評価、それから、同じ手法、同規模で実施しても、周知行動変容の効果が限定的になることとしております。","id":"exchange-100"},{"speaker":"せお委員","kind":"質問・要望","question":"最初はどこを目指しているか分からなかったです。ゴールをどこに設定したのかなということが分からなかったので、高齢者への熱中症対策、見守り支援もどこかで継続できる仕組みを要望したいと思います。こういった子どもの意見を聞くこともやっていただきたいですし、ごめんなさい、要望で終わりますが、こういったイベント的に、月１回などで行っていただくことがベストかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問・要望","question":"なのに、職場体験はいけない、おかしくないですか。いろいろな形で接していただいて、子どもたちに夢とか希望とかを持ってもらって、そういうものをやっていきましょうというのが職場体験ではないですか。その気持ちをぜひとも続けていただきたいなという思いがあります。この職場体験、自衛隊防災フェア、これらに対しての自衛隊の方々に対しての支援をどう考えられるか、もう一度お願いします。","respondent":"丸谷教育総合支援センター長、星災害対策担当課長","answer":"子どもたちに様々な体験先を選んでいって、大人の働く姿を見たりですとか、実際に体験することで自分のキャリアを考えていくということで、１つの体験先としての、学校が適しているという判断です。そういった認識でおります。区に対する自衛隊の対応ですけれども、やはり災害が起こったときに来ていただいて、消防、警察とともに区民の命を守る救助をしていただくというところからも、区としては。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"よろしくお願いします。でも、今年は入っていないのですか。できれば、企業かもしれないし、個人かもしれませんが、誰がどういう思いで、毎年毎年寄附をしようとしているのか、教えていただきたい。そうなってくると、それは契約を交わしていかないと、予算を立てにくくなるのではないですか。一般財源から出すという形になってしまうかもしれませんけれども、寄附の件も含めて教えてください。","respondent":"石井学務課長","answer":"そのような中で、今回の当初予算に計上するということは見送らせていただきました。それで、寄附を受けた際には、きちんと予算計上の中で新たな財源として組替えがなされるものと認識をしています。","id":"exchange-103"},{"speaker":"西本委員","kind":"意見","question":"この有機農法の野菜なのですけれども、改めて、なぜやるのかということを、調べれば調べるほどよく分からなくなってくるのです。だから、何のために、子どもたちの給食にオーガニック給食をやらなければいけないのかということがよく分からなくなってくるのです、調べれば調べるほど。なので、そういうリスクをかけてまで、なぜ品川区はやらなければいけないのか、それをお答えください。","respondent":"石井学務課長","answer":"なぜやるかと申しますと、やはり当然、みどりの食料システム戦略では、農業技術の確立がすごくイノベーションを通じて行われておりますけれども、そもそものところ、やはりこれは持続可能な農業をつくり上げていく、それは、いわゆる生産者側にアプローチする考え方とすれば。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、１４３ページ、居住支援事業、１４５ページ、鉄道駅総合バリアフリー推進事業費補助金、この２点をお伺いします。現在、品川区にある居住支援法人は何者となったのでしょうか。現状をお聞きしたいと思います。併せて、鉄道駅のバリアフリーの質問ですけれども、この事業は、来年度進める事業について、具体的な場所や内容などを簡潔に伺いたいと思います。","respondent":"川原住宅課長、櫻木地域交通政策課長","answer":"そして２つ目は、区民にこの法人を勧めるに当たって、どのような連携を居住支援法人ととっているかというご質問ですが、現在は、区のホームページにも区内の拠点を置く居住支援法人ということでＰＲをさせていただいているところです。委員がご指摘いただいているスロープの件についての受け止めですが、区としましても、バリアフリー計画の改定の中で、まち歩きであったり、区民アンケート等を進める中で。","id":"exchange-105"},{"speaker":"こんの委員","kind":"質問・要望","question":"できるだけ法人が所管と、もう既につながっていて、連携がとれる、もっと言えば、権限を与えてもらえるというようなところまでいくと、支援がしやすいのかなと思いますので、ぜひそこら辺のところを、今後、この２法人と連携をとっていただきながら、より支援が具体的に行われるように、区としても計らっていく体制をとっていただきたいと思いますが、いかがでしょうか。次に、大井町駅のバリアフリーです。","respondent":"川原住宅課長、櫻木地域交通政策課長","answer":"今後、引き続き、また来年度の居住支援協議会などを利用しまして、事例の共有などをして、関係課にどのようにつなげていくか、スムーズにできるかといったところは、今後の研究として実施をしてまいりたいと思います。委員からご提案いただきました東京駅の新幹線の改札前のスロープを参考とすることについて、基本的にバリアフリーの考え方としましては５％、または、特定の場合だと８％勾配を確保するということで、一定。","id":"exchange-106"},{"speaker":"こんの委員","kind":"質問・要望","question":"区民の皆さん、先ほど、サンピア商店街の方々のお声とともに、先日、私立幼稚園に通うお母さん方、お子さんが通う母の会の方々からも、ここにスロープをつけていただきたいという要望も具体的にいただいておりますので、ぜひ区民の方、また、来訪者の方々も、安全に駅との円滑な歩行ができるように、ぜひ品川区として協議を進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、４９ページの予算の事項別明細書全般について、また、後段は、財政調整、都市計画交付金などについてお伺いしたいと思います。会派は対しての概要版が届けられています。中には、貴重なこの場で質問をして、確認がとれました、安心しましたとかで終わってしまう。これまでそういった視点で、私は言ってきましたので、今後に向けて、ぜひ前向きなお答えをいただきたいと思いますが、いかがでしょうか。","respondent":"加島財政課長","answer":"それを全て１冊にまとめてというところも確かに選択肢の１つとしてはあるのかもしれないですが、予算編成過程の中で、また、その後、プレス発表がある中で、各所管において全庁を中心にしながら資料を取りまとめている中では、私どもは、今の形、会派説明資料、議案説明資料の形。","id":"exchange-108"},{"speaker":"田中委員","kind":"提案","question":"そういった提案に対して、その結果の返事というのですか、回答が、私だけなのかもしれないのですけれども、こういう議論を通じて受け止めた議案に対して、こういう成果を上げることができましたとか、あるいは、こういうふうにしていきますという、そういう返事がないなとすごく感じます。今は個別の話ではなくて総論として伺っておりますが、いかがでしょうか。","respondent":"久保田企画経営部長","answer":"今いろいろなご質問をいただきましたけれども、我々、議会とは区政の両輪という認識でいますので、きちんと協力、連携しながら進めているところです。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"ご案内のとおり、２３区には、港区とか渋谷区のように不交付団体もあります。そういう意味での温度差もありますし、あと、東京都ですから、２３区以外の市町村もあります。それはぜひ言っていただきたいのですが、一方で、主張はするけれども、ほかの区も、担当者もいる中で発言していただけるということは、我々としては、温かく、また力強く見守っていくべきだと思いますが、財政課長、一言お願いします。","respondent":"加島財政課長","answer":"港区、渋谷区は不交付というご案内もございましたが、２３区が等しく行うべき事務、役割を果たすことができるように、この都区財政調整制度があると認識しております。","id":"exchange-110"},{"speaker":"田中委員","kind":"意見","question":"都市計画税については、また土木費で話したいと思いますが、それはそれで、私は課題も認識しておりますが、一方で、東京都が都市計画事業を行うことの理解もしておりますし、また、それをぜひ皆様にもご理解いただいた上で、実りある質疑をしていただけるようにお願いしたいと思いますし、冒頭申し上げたチェック機関としての予算特別委員会が、より充実するように資料提供もお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問","question":"１７８ページの特別区債です。総務費は、令和８年度起債ゼロということです。新庁舎の総工事費が約６７３億円というふうな形で区から出ています。起債予定は６１％、約４００億円規模です。令和７年度は４１億５,０００万円を起債しました。令和８年度に新庁舎整備に関する総務費の０円という形の起債を計上しなかった理由は、出来高払の請求がなかったからという理解なのか、その辺をご説明ください。","respondent":"小林新庁舎建設担当課長","answer":"新庁舎に関する工事費のお問合せですが、令和８年度につきましては、委員ご案内のとおり、出来高に関する請求等が予定されていないところから、予算計上しないところです。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、窓から見えますが、工事を令和７年度、令和８年度とやっていくのですけれども、それを令和７年度に払ってしまったということなのか。それとも令和７年度分だけ請求があったから支払ったということなのか、すみません、その辺、私、よく分からないのでお願いします。","respondent":"小林新庁舎建設担当課長","answer":"その後の支払いにつきましては、出来高に関する請求があった場合に対しましてお支払いをするということになってありますので、令和８年度の分まで令和７年度のお金で支払ったというより、出来高払と前払金という性格の異なるものと認識いただければと思います。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問","question":"性格が違うというご説明をいただきました。ということで、２００ページには工事の費用が全く出ていないけれども、管理委託とか監督委託の費用が出ているということになるのですか。","respondent":"小林新庁舎建設担当課長","answer":"いわゆる工事監理の費用と、それから監督員支援に関する費用につきましては、これは委託になりまして、これは年度ごとに支払う費用ですので、これについては予算計上をさせていただいたところです。","id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"建設関係はまたお尋ねしたいと思います。そこで、起債の話ですけれども、令和８年度から令和１１年度の建設工事費は６１.７億円で、特別区債は３５４億６,０００万円と出ています。令和９年度から令和１１年度の年度別発行上限や、起債の年度別計画は設定しているでしょうか。","respondent":"加島財政課長","answer":"そのため、現在、具体的に、この場で申し上げられる数字は確定したものはございません。先ほど、全体での事業の充当率は確かに６１％となりますけれども、区負担分につきましての起債充当率には７５％となるというところは申し添えさせていただければと存じます。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"分かりました。ということは、現時点では、起債の総額や一般財源の投入額、そして、それらが年度別にどういうふうに配分していくかという、いわゆる財源フレームでしょうか。それは、今お話があったように、出来高が出てこないから、現在は存在しない、あるいは公表できない、あるいは、想定しているけれども公表できないということなのでしょうか。","respondent":"加島財政課長","answer":"お見込みのとおりです。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"意見","question":"ということで、フレームは分からないと。そこで、仮に残りの３５４億円を３年間、令和９、１０、１１年度で発行すれば、年間約１２０億円ずつ起債するわけです。それは区政にとって極めて大きなインパクトがあります。仮にですが、最大規模で起債すれば、年間公債費が幾ら増加するかという確定試算はもちろんあると思うのですが、それをお答えください。","respondent":"加島財政課長","answer":"公債費ですけれども、このたび借入れでの計画になりますが、令和８年度から１２年度まで払う利払いの額が約７,６００万円に対しまして、令和１２年度に満期一括償還として元金として支払っていく額が１２億７,０００万円を計画しているところで。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和７年度についてはホームページでも公開されています。その部分についての、試算をお願いしたいのと、あと、昨日、学校債を起債しないという理由の１つに金利が上昇するということを挙げていただきましたけれども、仮に金利が１％上昇した場合の、この１２０億円掛ける３の公債費増加額の、１％増加しても、長期金利だからそのままとは限りませんが、それについての試算は、今、やられているでしょうか。","respondent":"加島財政課長","answer":"令和９年度以降の借入れの計画につきましては、工事の出来高に応じて区負担分の起債、７５％を起債してまいりますので、先ほど申し上げたとおり、現段階では具体的にお伝えできる数字はございません。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今いろいろご説明いただいたのですが、３９５億マイナス４０億した金額を、今後、年度ごとに出来高等でやっていくということなのですと言われて、区民の方にこのまま説明してもなかなか分かっていただけないのです。全体の財源計画および年度別配分計画を、いつ、どの時点で議会に示すのか、今、年度ごとにとおっしゃいましたが、その全体像、それをいつ示していただけるのかということをお尋ねします。","respondent":"加島財政課長","answer":"こちらにつきまして、そういった答弁を通じて説明をさせていただいているところです。起債の計画につきましては、今年度借り入れた４０億円につきましては、区ホームページのほうに借換え計画を載せさせていただいているところです。","id":"exchange-119"},{"speaker":"松本委員","kind":"質問","question":"それぞれ２億円と５億円の増額補正になっています。増額の要因についても、昨日、答弁があったかと思うのですが、それを踏まえても、現下の利上げとか、上場企業の実績を勘案すると、昨日、話が出ていた固い固い見通しというようなお話があったかと思いますが、ただ、そうはいっても、やはり今年度と同額というのは、やや少し違和感があるのですけれども、ここはどのようにお考えでしょうか。","respondent":"加島財政課長","answer":"そのような背景から、令和８年度当初予算でも増額するということも考えられたのですけれども、最終補正予算編成時点におきまして、直近の国の月例経済報告では、企業収益は米国の通商政策による影響が、自動車産業を中心に見られる中で。","id":"exchange-120"},{"speaker":"松本委員","kind":"質問","question":"詳細な説明、ありがとうございました。事実上、人件費等で上がっている状況かと思います。これは施設の利用料だけではなくて、例えば賃貸料もあると思います。全般的に物価の上昇等を踏まえて、区の施設の利用料、賃料などについて、これは各所管ではなくて、区の総合的な観点から、どのように考えていけばいいか伺えればと思います。","respondent":"崎村企画課長","answer":"ただ一方で、やはり利用料、使用料というものについては、区民生活、地域活動に密接的に関わるものでありますので、単に物価上昇分を使用料に転嫁するということではなくて、まずは施設運営に当たって見直すべきものがないかということを検討した上で、住民負担の影響ですとか。","id":"exchange-121"},{"speaker":"松本委員","kind":"質問","question":"そうすると、やはり区の施設をどう効率的に運用していくのかというところが大切になってくるかと思いますので、次のシルバーセンターの使用料の質問に移りたいと思います。予算書の７１ページには、各シルバーセンターの使用回数が記載されています。有償の部分ではありますけれども、稼働がこれだけ少ないというのは、どうなのかなというふうにも思うのですけれども、所管の見解を伺います。","respondent":"樫村高齢者地域支援課長","answer":"旗の台シルバーセンターにつきましては、来年度４回ということで記載していますが、実際に令和６年度は９８回の目的外利用がございまして、うち、２回のみが有料、９６回が無料でございました。","id":"exchange-122"},{"speaker":"松本委員","kind":"質問","question":"小山シルバーセンターの利用状況が分からなかったのですが、無料の利用というのは、今おっしゃられていた日曜日とか夜間の無料がそれだけの数ということでよろしいか伺います。","respondent":"樫村高齢者地域支援課長","answer":"小山シルバーセンターにつきましても、５０回と記載をしていますが、令和６年度につきましては、実際７回の利用がございまして、うち１回が有料、６回が無料でございました。","id":"exchange-123"},{"speaker":"松本委員","kind":"質問","question":"ここで、先ほどの区有施設をうまく効率的に活用するというふうに考えていくと、シルバーセンターはお年寄りの方たちのためのものという前提で考えがちなのですけれども、空いている時間とか、空いている期間を分析していただいて、地元の子どもたちが学習できるようなスペースとしても活用していく、こうした考え方もあるのではないかと思いますが、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"シルバーセンターの目的外利用につきましては、事前に申請があった場合に人員を配置しまして開ける運用を行っているところでございまして、そういった意味での稼働率は、少し低い数字にはなるのですけれども、シルバーセンターの目的外利用としては、高水準での運用といいますか。","id":"exchange-124"},{"speaker":"松本委員","kind":"質問","question":"稼働率として、ただ、先ほど伺ったところ、小山シルバーセンターは７回か６回ですか、年間でその数なので、やはり必ずしも高くはないのではないかと思います。人件費のところはあるとは思うのですけれども、施設を有効に活用するというところでいくと、別の考え方もあるのではないかと思いますので、引き続き私のほうでも各種質問させていただければと思います。申し訳ありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１５７ページの防災ラジオ売払代金に関わって、防災ラジオの配布、９９ページの児童虐待防止対策等総合支援事業費補助金に関わって、品川区児童相談所の充実を求めて伺います。防災ラジオについてです。この緊急放送が聞き取れないと安全にも関わってきます。希望する高齢者、障害者に無料で配布していただきたいと思いますが、いかがでしょうか。","respondent":"遠藤防災体制整備担当課長","answer":"防災ラジオに関しましては、購入者から、年度ごとにアンケート調査をしておりまして、そのアンケート調査によりますと、価格について「高い」、「安い」、「妥当」という項目がございまして。","id":"exchange-126"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり高齢者の方、特にインターネットやＳＮＳができない人もおりますので、配布をするということが、区民の命を災害から守ることにもつながると思いますので、ぜひそこは、実施を要望したいと思います。年々相談が増えている状況ですけれども、まず、児童福祉司が１人当たり何ケースを担当しているのか伺います。品川区児童相談所の開設から１年半が迫っていますが、退職した職員の人数と離職率を伺います。","respondent":"長谷川児童相談課長","answer":"１人当たりのケース数になりますけれども、現在、６６１件を２５名で対応しておりますので、割り返しますと２６.４４件となります。国が示している標準件数が４０件であることから、区の２６件というのは、割と担当としては、そんなに逼迫はしていないかなと捉えております。","id":"exchange-127"},{"speaker":"のだて委員","kind":"質問","question":"国の標準では４０件ということで、その中で品川区では２６件ということで、国の目安よりも少ないというのは、職員の負担を考えるとよかったと思います。離職についても、児童福祉司はゼロということでよかったと思うのですが、実際、休職している人もいないのかどうか、そこを伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"休職者に関しましては、おおよそ１０名程度、年度内で休職した職員がおります。そのうち８名は復職しておりますが、２名が引き続きの休職となっております。","id":"exchange-128"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした中で職員も疲弊していくという中で、引き続き働き続けられるように、職員のケアを充実させていただきたいと思いますが、いかがでしょうか。退職にならないためにも、１回離れて休みたいという職員には、別の部署に異動して、休んでからまた児童相談所に戻ってきてもらうということができれば、辞めることなく経験を積んでいくことができると思うのですけれども、いかがでしょうか。","respondent":"長谷川児童相談課長","answer":"ただ一方で、職務を進める上で様々な困難にぶつかることもあり、そうした困難である気持ちを聞き取るためにヒアリングを実施しております。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ働き続けられるように、職員のケアをしていっていただきたいと思います。次は、一時保護、午前中にも議論がありました。今、定員オーバーして、最大時は２４名ということで、全然足りていない状況なのですけれども、なぜ定員を１４名にしたのか、理由を伺います。この定員オーバーしている状況で、一時保護が必要になった場合の対応はどうなっているのか伺います。","respondent":"長谷川児童相談課長","answer":"品川区児童相談所としましては、子どもの命を守る一時保護を、保護所の事情で受け入れないという選択はそもそもなく、必要な子どもは何としても保護する必要がありますし、保護所が満杯だから保護解除するというような選択もなく。","id":"exchange-130"},{"speaker":"のだて委員","kind":"質問・要望","question":"受け入れないことはないということで、少し安心しましたけれども、ぜひそうしたところでしっかり受け入れていただいて、帰すことがないようにしていただきたいと思いますし、区で受け入れられないときに、別の場所になった場合も、見えにくくなると思いますので、しっかり対応が遅れないようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"若林委員","kind":"質問","question":"５２ページの特別区たばこ税について、まず、歳入増の理由をお聞きいたします。併せて、いわゆる屋外の喫煙対策に、来年度はどのように取り組むのか、お話をお聞きしたいと思います。それから、歳入項目が見つからなかったのですが、いわゆる平和に関する歳入はないのかということ。歳入が恐らくない中で、区としてやる意義をお聞きしたいと思います。","respondent":"宮澤税務課長、澤邉生活安全担当課長、藤村総務課長","answer":"こちらは、令和７年度の税制改正により加熱式たばこの課税方式の見直し、増税となっておりますので、それを見越して増額となっているところです。来年度もこの設備の助成については、増額をしまして対応してまいりたいと思います。そういった平和を知る機会ですとか、次世代に継承する機会を継続的に提供することで、平和の潮流をつくり出すことができると考えて。","id":"exchange-132"},{"speaker":"若林委員","kind":"確認","question":"課のほうでも一定把握されていると。もう１回確認しますけれども、本会議場では、戦争ほど残酷なものはない、戦争ほど悲惨なものはない、愚かな指導者たちに率いられた国民もまた誠に哀れである。いずれにしても、戦争はなぜ起きてしまうのか、こういうことを私たちが考え続ける。思考停止に陥らないように主体的に考えること、こういった事業の在り方についての今後のお考えをお聞きしたいと思います。","respondent":"勝亦健康課長、藤村総務課長","answer":"区内の企業の方からの周辺の喫煙のクレーム等も結構ありますので、企業のほうに、従業員の方に受動喫煙の配慮義務、努力義務、そういった啓発をしていただくような形で、企業への協力を求めていきたいと考えています。思考停止してしまうことがよくないということですが、だからこそ、過去の歴史であるとか、戦争の惨禍について知ることによって、そうならない未来につなげることができるのかなと考えております。","id":"exchange-133"},{"speaker":"藤原委員","kind":"質問・要望","question":"８３ページ、建築確認手数料、７７ページ、区営住宅使用料、１３９ページ、都市計画交付金についてお伺いします。私が昨年の第４回定例会で一般質問をさせていただきました項目の中で都市計画交付金についてお伺いします。今後とも引き続き東京都に対して見直しを求めていただきたいと思いますが、いかがでしょうかという質問をしたときに、これ、本当にいい答弁をしていただきました。","respondent":"久保田企画経営部長","answer":"都市計画交付金の関係ですけれども、都区財政調整協議の中でいろいろ協議はしています。区側からも、まだまだ足りないということは強く主張はしているところなのですけれども、協議が調わずに、第４回定例会のときにお答えした答弁の状態であるです。","id":"exchange-134"},{"speaker":"藤原委員","kind":"質問","question":"協議が調わないというのは、協議ができないということですか。ということは、東京都、これだけではないではないですか、都区の在り方検討会、これももうずっと協議されていないわけですよね。されていない。駄目なら駄目と言ってくれればいいわけですよね、こういう理由でと。これ、同じ東京都ですよね。２３区があって、そして、日本の国民同士でやるところではないですか。よろしくお願いします。","respondent":"久保田企画経営部長","answer":"ただ、こうした状況をこのままでいいということはありませんので、我々としましては、引き続き、我々は我々の主張として、協議をしていきたいと考えているところです。","id":"exchange-135"},{"speaker":"藤原委員","kind":"質問","question":"新井副区長、ストレートにお伺いして申し訳ないのですけれども、東京都はこういうものなのですか。だって、真剣に、２３区および区の職員の方たちが、協議したいのだと、お話ししたいのだと言っているのに、調わない。東京都は、２３区が言っていることはいいよとなってしまうのでしょうか。少しストレートな質問なのですけれども、ぜひそこをお伺いしたいのです。","respondent":"新井副区長","answer":"何を言えばいいのかということはあるのですけれど、都区の在り方の議論をするときに、いつも私が思い出すのは、平成１１年でしたか、地方分権一括法が制定されまして、ご存知のことかと思いますけれど、従来の国と地方の関係が、上下主従から対等平等になったと。","id":"exchange-136"},{"speaker":"藤原委員","kind":"確認","question":"副区長に答えていただいてよかった。もうこれ以上言わないで、期待していますので、何年後、何十年後に、私がああいう質問をしたということを思い出せるような結果が出るようになることを心から祈念いたしまして、次の質問をします。建築確認なのですけれども、確認申請の数と、おうちができた後の完了検査の数が少し違いますよね。申請の数と、できたという確認の数が。これはどうしてでしょうか。","respondent":"森建築課長","answer":"件数が違っているところに関しましては、年度をまたいでいたりとか、長い工期のものがあったりとかいたしますので、数字がずれている、そのようなことです。","id":"exchange-137"},{"speaker":"藤原委員","kind":"確認","question":"でも、こういうことがあったのですよ、昔。確認しますが、そうではないですよね。１点。時効がないのですから、これ、１０年、２０年前ぐらいに建てても、例えば、セットバックしますよという形で建築確認を申請を出して、完了検査をしないで、そのままセットバックしないで建てている家があったら、今でも役所に、行政に、こういう家があるのだけど是正してくださいと言えば、動いていただけますよね。","respondent":"森建築課長","answer":"建築基準法違反につきましては、委員ご指摘のとおり、時効等はございません。ただ、建築基準法と憲法との兼ね合いになりまして、憲法の存在点というところまで侵して建築基準法で立ち退きを命ずることができるのかどうかとなってくるかなとは思ってあります。","id":"exchange-138"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１回言いますよ、セットバックして建築申請をしているのに、実際にはセットバックしていない家、現実にあるのです。これはおかしいと言っても、憲法で住む権利があるからと言われてしまっては、しようがないではないですか。今日、憲法論を話すわけではないですけれども、でも、やはり正直者がばかを見ないような世の中にしていただきたいと思うのですけれども、その辺はいかがですか。","respondent":"森建築課長","answer":"完了検査はとても大事なことだと考えています。金融関係の業界で、完了検査がない建物には融資をしないと決めていると聞いてありますので、新しく確認申請どおり完了検査が通っていないような建物が発生することはとても少ないと考えています。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも、それ、住宅ローンのことでしょう。現金で一括で払ってしまえば全然そんな住宅ローンは関係ないではないですか。だけど、きちんとここは法律ルールの隙間があると思うので、もう今は義務ですよね。そこはしっかりやってくださいね。これは要望します。私は、まず、日本の方が区営住宅、公共住宅に入居できるように、公という意味で優先していただきたいと思うのですけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"区営住宅における日本人の方の優先入居といったお話です。現在の区営住宅の外国人の方の入居については、一定の制限を設けているような形でございまして、在留資格が１年以上もしくは日本国籍を取得している方といったルールがあります。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも、外国の方が入っていますよね。そうは言っても。私は、まず衣食住の住ですよ。日本の方を優先にしていただきたいと心から思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"まつざわ委員","kind":"質問","question":"予算書の第２表の債務負担行為等を見ますと、浅間台、鈴ケ森、源氏前、城南第二、学校改築に関する多額の限度額が並んでいます。この債務負担行為というのは、将来の予算をはじめ、見えない借金とも言いますが、膨らみ続ける建築コストが、将来の一般施策を圧迫するリスクについて、区はどのような危機感を持って臨んでいるのか、まず、基本的な認識を伺います。","respondent":"荒木学校施設担当課長","answer":"将来世代への負担をできる限り抑えつつ、必要な教育環境を整備していくことが喫緊の課題と考えていますので、引き続き効率的な学校改築を進めていきたいと考えています。","id":"exchange-142"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そういった改築困難校に対して、例えば、これ、新築というこの２文字に縛られずに、文教委員会でも話がありましたけれども、大崎中学校と三ツ木小学校は近いから一緒にしてしまえばいいではないですか。そういった柔軟な考え方。地域にも迷惑がかかるのは分かっていますけれども、地域を含め、やはり学校で学ぶ子どもたちの意見もぜひ聞いていただきたいと思いますが、２点よろしくお願いします。","respondent":"荒木学校施設担当課長","answer":"いずれといたしましても、来年度進めていく予定の改築困難校の基本構想の中で様々な手法を検討していきたいと思います。ご提案のあったヒアリングにつきましては、改築プロセスの一部に子どもたちから参画してもらうということは非常に重要な視点と考えています。","id":"exchange-143"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"その上で重要なのは、新築であっても、改修であっても、建てた後に幾らかかるという、ＬＣＣというのですか、ライフサイクルコスト、この視点だと思っています。品川区はＺＥＢには相当力を入れていますけれども、やはり５０年、１００年、そういった区民に過度なメンテナンスを負わせない徹底した工夫が必要だと考えますが、具体的な対策、施設整備計画の柔軟な見直しについて、ご見解をお聞かせください。","respondent":"荒木学校施設担当課長","answer":"加えて、今、工事中の城南第二小学校およびそれ以降の学校に関しましては、ＺＥＢ化を標準として計画を進めているところです。今後も維持管理費の縮減につながる取組を積極的に取り入れながら、ライフサイクルコストを意識した施設整備を推進してまいります。","id":"exchange-144"},{"speaker":"まつざわ委員","kind":"提案","question":"ご答弁ありがとうあります。改築が難しい学校ほど、役所の前例、また標準、そういったものが通用しないと思っています。最後にご提案ですが、今後の学校の整備においては、設計図面だけではなく、例えば新築した場合と、長寿命化改修した場合のコストの比較であったり、教育効果のシミュレーションを多角的に示して、区民に公表する仕組みをぜひ構築していただきたいと考えますが、ご見解をお聞かせください。","respondent":"荒木学校施設担当課長","answer":"来年度取り組む改築困難校基本構想の対象として、２校の検討を進めていく中で、新築と改修のコスト比較など、より区民の皆様にご理解いただきやすい形での情報発信に努めていきたいと考えています。","id":"exchange-145"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/361190?Template=document&Id=7381#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":123748,"voices":343}},{"id":"r08-20260304-10","meetingId":"r08-1t","date":"2026年3月4日","dateIso":"2026-03-04","committee":"議会運営委員会","time":"午後 ５時０９分～午後 ５時２６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"うまく言えなかったのですけれども、特別区長会の声明なども参考にして、記書きのところの、「地域間の税収格差の是正にあたっては」という表現を変えるとか、「あたっては」というのであれば、上に書いている「国の責任において、地方全体の財源充実をもって解消するべきである」とかというふうに書いたほうが、趣旨としては正確なのではないかと思ったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"私も拝見して、中身はそのとおりということで、反対はしませんけれども、最初の行のところに、「国が地方創生の推進、税源偏在是正の名のもとに断行してきた」という言葉になっているのです。でも、あえて忖度して断行、忖度というか、あえて気を遣って断行したという言い方にしたのであれば別にいいのですけれども、違和感があるので、一応申し述べさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"議長がいらっしゃるので、議長会で出ているかの確認なのですが、要は東京独り勝ちに対しての国および地方自治体からのこういう対応で、偏在是正が生まれているのですけれども、特別区で今行っている特別区全国連携プロジェクトは、あえてこういうことがあるからやっているという面もある一方で、見方としては、そんな余裕があるのと見られると。","respondent":"渡辺議長","answer":"それぞれ何点かポイントがあったと思います。特別区全国連携プロジェクトの項目出しを、成果もあるのですが、実は理解されていない自治体もあるという感じです。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579932?Template=document&Id=7339#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":5412,"voices":29}}]);
